import { Feather } from '@expo/vector-icons';
import { router, useLocalSearchParams } from 'expo-router';
import { useEffect, useMemo } from 'react';
import { Pressable, ScrollView, Share, StyleSheet, View } from 'react-native';
import Animated, {
  Easing,
  FadeInDown,
  ReduceMotion,
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withRepeat,
  withTiming,
} from 'react-native-reanimated';
import { SafeAreaView } from 'react-native-safe-area-context';

import { Cloudy } from '@/components/cloudy';
import { Carte } from '@/components/ecran';
import { Bande, TuilesStats } from '@/components/elements';
import { BoutonPrincipal, BoutonSecondaire } from '@/components/formulaire';
import { t } from '@/i18n';
import { espace, motion, ombre, police, useCouleurs, type Couleurs } from '@/theme/tokens';

/** Une entrée en fondu montant, décalée, qui respecte « réduire les animations ». */
const entree = (delai: number) =>
  FadeInDown.duration(motion.duree.normal).delay(delai).reduceMotion(ReduceMotion.System);

/**
 * L'écran de célébration « Semaine bouclée », pièce maîtresse de la charte v9.
 *
 * Il est purement présentationnel : il reçoit ses chiffres par params de route
 * et ne décide de rien. Le point de déclenchement (quand l'ouvrir) vit
 * ailleurs, en fin de semaine quand tous les moments prévus sont clôturés. Ici
 * on ne fait que fêter, avec Cloudy en célébration et le seul dégradé d'action
 * de l'écran sur le bouton de partage.
 *
 * 🚨 La croix vit HORS du ScrollView, comme partout dans l'app : elle reste
 * visible même quand on descend. Même patron que le paywall.
 *
 * Les chiffres arrivent en chaînes (params de route) : on parse avec des replis
 * raisonnables plutôt que d'afficher un écran cassé si l'appelant en oublie un.
 */
function nombre(v: string | undefined, defaut: number) {
  if (!v) return defaut;
  const n = parseInt(v, 10);
  return Number.isFinite(n) ? n : defaut;
}

export default function Celebration() {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const params = useLocalSearchParams<{
    observations?: string;
    points?: string;
    semaines?: string;
    collegues?: string;
    moments?: string;
  }>();

  const observations = nombre(params.observations, 12);
  const points = nombre(params.points, 4);
  const semaines = nombre(params.semaines, 4);
  const collegues = nombre(params.collegues, 0);
  const moments = nombre(params.moments, 4);

  async function partager() {
    await Share.share({
      message: t.celebration.partageTexte(observations, points, semaines),
    }).catch(() => null);
  }

  // Le halo derrière Cloudy respire, comme un souffle de fête qui ne retombe
  // pas. Coupé sous « réduire les animations ».
  const reduire = useReducedMotion();
  const pulse = useSharedValue(1);
  useEffect(() => {
    if (reduire) return;
    pulse.value = withRepeat(
      withTiming(1.08, { duration: 2600, easing: Easing.inOut(Easing.quad) }),
      -1,
      true,
    );
  }, [reduire, pulse]);
  const styleHalo = useAnimatedStyle(() => ({ transform: [{ scale: pulse.value }] }));

  return (
    <SafeAreaView style={styles.racine} edges={['top', 'bottom']}>
      <Pressable
        accessibilityRole="button"
        accessibilityLabel={t.celebration.fermer}
        onPress={() => router.back()}
        style={styles.fermer}>
        <Feather name="x" size={22} color={c.encreDouce} />
      </Pressable>

      <ScrollView contentContainerStyle={styles.contenu} showsVerticalScrollIndicator={false}>
        {/* Une seule mascotte par écran, en célébration, jaune : elle porte
            l'émotion, le fond reste neutre (charte v9). Elle entre en pop et
            respire ; un halo qui respire l'auréole. */}
        <View style={styles.mascotte}>
          <Animated.View style={[styles.halo, styleHalo]} pointerEvents="none" />
          <Cloudy pose="celebration" taille={120} anime respire />
        </View>

        <Animated.Text entering={entree(120)} style={styles.titre}>
          {t.celebration.titre}
        </Animated.Text>
        <Animated.Text entering={entree(200)} style={styles.sous}>
          {t.celebration.sousTitre(moments, observations, points)}
        </Animated.Text>

        {/* La couleur vit dans les tuiles, jamais sur un aplat. Trois moments
            distincts pour trois chiffres distincts. Les tuiles se posent en
            cascade (anime). */}
        <Carte>
          <TuilesStats
            anime
            items={[
              {
                valeur: observations,
                libelle:
                  observations <= 1
                    ? t.celebration.statObservation
                    : t.celebration.statObservations,
                moment: 'accueil',
              },
              {
                valeur: `+${points}`,
                libelle: points <= 1 ? t.celebration.statPoint : t.celebration.statPoints,
                moment: 'recreation',
              },
              {
                valeur: semaines,
                libelle: t.celebration.statSemaines(semaines),
                moment: 'ateliers',
              },
            ]}
          />
        </Carte>

        {/* La bande rose n'apparaît que si des collègues ont vraiment repris une
            leçon : pas de « 0 collègue » qui sonnerait creux. */}
        {collegues > 0 ? (
          <Animated.View entering={entree(440)}>
            <Bande moment="social" titre={t.celebration.collegues(collegues)} />
          </Animated.View>
        ) : null}

        <Animated.View entering={entree(collegues > 0 ? 540 : 440)} style={styles.actions}>
          {/* Le seul dégradé d'action de l'écran. « Partager ma semaine » ouvre
              la feuille de partage native avec un texte de bilan (aucun prénom
              d'enfant), un geste qui existe déjà ailleurs dans l'app. */}
          <BoutonPrincipal libelle={t.celebration.partager} onPress={partager} />
          <BoutonSecondaire libelle={t.celebration.revenir} onPress={() => router.back()} />
        </Animated.View>
      </ScrollView>
    </SafeAreaView>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  racine: { flex: 1, backgroundColor: c.fond },
  fermer: {
    position: 'absolute',
    top: espace.md,
    right: espace.md,
    zIndex: 10,
    width: 36,
    height: 36,
    borderRadius: 18,
    backgroundColor: c.surface,
    alignItems: 'center',
    justifyContent: 'center',
    ...ombre.carte,
  },
  contenu: {
    padding: espace.lg,
    paddingTop: espace.xl * 2,
    paddingBottom: espace.xl,
    gap: espace.md,
  },
  // Boîte carrée qui cadre la mascotte et son auréole : taille fixe pour que le
  // halo, absolu, se centre proprement dessous.
  mascotte: {
    width: 170,
    height: 170,
    alignSelf: 'center',
    alignItems: 'center',
    justifyContent: 'center',
    marginBottom: espace.xs,
  },
  // Auréole miel derrière la mascotte. Absolue, elle remplit la boîte (donc un
  // disque de 170) sans pousser la mise en page ; la mascotte passe au-dessus.
  halo: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    borderRadius: 85,
    backgroundColor: c.actionTeinte,
  },
  titre: {
    fontFamily: police.titre,
    fontSize: 32,
    lineHeight: 36,
    color: c.encre,
    textAlign: 'center',
    marginTop: espace.sm,
  },
  sous: {
    fontFamily: police.corps,
    fontSize: 17,
    lineHeight: 24,
    color: c.encreDouce,
    textAlign: 'center',
    marginBottom: espace.sm,
  },
  actions: { gap: espace.sm, marginTop: espace.sm },
});
