import AsyncStorage from '@react-native-async-storage/async-storage';

import type { Reseau } from './donnees';

/**
 * Le brouillon d'onboarding PRÉ-COMPTE.
 *
 * 🔑 Le nouvel accueil (`ACCUEIL_V2`) laisse un·e arrivant·e choisir son niveau
 * et son réseau AVANT même d'avoir un compte. Mais la suite de l'onboarding
 * (détection des attendus, création de la classe) passe par des appels
 * authentifiés : il FAUT une session pour les jouer. On ne peut donc pas tout
 * dérouler pré-compte. Le compromis : on retient localement les deux choix déjà
 * faits, on crée le compte, puis `bienvenue` relit ce brouillon pour reprendre
 * l'onboarding là où il en était — sans redemander niveau et réseau.
 *
 * ⚠️ Ce brouillon n'est JAMAIS écrit quand `ACCUEIL_V2` est éteint : c'est le
 * seul chemin (« Je découvre ») qui le pose. Tant qu'il n'existe pas, `bienvenue`
 * démarre exactement comme avant. C'est une marque d'appareil, pas une donnée de
 * compte : elle vit le temps d'un premier lancement et s'efface dès qu'elle est lue.
 */
export type BrouillonOnboarding = {
  niveaux: string[];
  reseau: Reseau | null;
  /**
   * Vrai quand l'arrivant·e est passé·e par « Je découvre » : `bienvenue`
   * proposera alors de définir un mot de passe à la fin de l'onboarding.
   */
  definirMotDePasse: boolean;
};

const CLE = 'educooo:onboarding-brouillon';

export async function ecrireBrouillonOnboarding(brouillon: BrouillonOnboarding): Promise<void> {
  try {
    await AsyncStorage.setItem(CLE, JSON.stringify(brouillon));
  } catch {
    // Silencieux : au pire, `bienvenue` repart de l'étape niveau. Rien de cassé,
    // juste deux taps de plus. On ne fait pas échouer la création de compte pour ça.
  }
}

export async function lireBrouillonOnboarding(): Promise<BrouillonOnboarding | null> {
  try {
    const brut = await AsyncStorage.getItem(CLE);
    if (!brut) return null;
    const objet = JSON.parse(brut) as Partial<BrouillonOnboarding>;
    // On se méfie de ce qu'on relit : une forme inattendue vaut « pas de
    // brouillon » plutôt qu'un écran qui plante au montage.
    if (!Array.isArray(objet.niveaux)) return null;
    return {
      niveaux: objet.niveaux.filter((n): n is string => typeof n === 'string'),
      reseau: (objet.reseau ?? null) as Reseau | null,
      definirMotDePasse: objet.definirMotDePasse === true,
    };
  } catch {
    return null;
  }
}

export async function effacerBrouillonOnboarding(): Promise<void> {
  try {
    await AsyncStorage.removeItem(CLE);
  } catch {
    // Sans gravité : le brouillon est de toute façon à usage unique, et
    // `bienvenue` ne le relit qu'une fois par montage.
  }
}
