import { useEffect, useMemo } from 'react';
import { StyleSheet, useWindowDimensions, View } from 'react-native';
import Animated, {
  Easing,
  Extrapolation,
  interpolate,
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withDelay,
  withTiming,
} from 'react-native-reanimated';

import { useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * Une pluie de confettis, en overlay plein écran, pour la célébration d'un
 * palier de trophée.
 *
 * 🚨 Aucune lib de confettis dans le projet, et surtout pas de dépendance native
 * nouvelle : tout est fait avec `react-native-reanimated` (déjà partout) sur de
 * simples `Animated.View` colorés. Rien à recompiler.
 *
 * Les couleurs sont celles de la charte : les six couleurs de moment plus le
 * dégradé d'action. La couleur vit ainsi dans de toutes petites surfaces, jamais
 * en aplat — la règle centrale de la v9 tient même dans la fête.
 *
 * ⚠️ « Réduire les animations » coupe TOUT mouvement (comme la dictée et la
 * célébration : on lit `useReducedMotion()`). On rend alors un burst STATIQUE et
 * discret, une poignée de confettis posés en haut à faible opacité, plutôt qu'une
 * pluie qui tombe. Pas de boucle, pas de chute animée.
 *
 * L'overlay est absolu et `pointerEvents="none"` : il ne prend jamais le doigt,
 * on peut fermer l'écran dessous pendant qu'il retombe.
 *
 * `Math.random()` est utilisé ici pour disperser les confettis : c'est un
 * composant RN normal (pas un workflow déterministe), donc parfaitement légitime.
 */

/** Une pièce de confetti : sa position, sa forme, sa couleur, sa trajectoire. */
type Piece = {
  gauche: number; // position horizontale de départ, en points
  taille: number; // côté / diamètre, en points
  couleur: string;
  rond: boolean; // rond ou petit rectangle
  derive: number; // amplitude du va-et-vient horizontal, signée, en points
  oscillations: number; // nombre de demi-vagues du drift sur la chute
  tours: number; // nombre de tours de rotation, signé
  delai: number; // décalage de départ, en ms
  duree: number; // durée de la chute, en ms
  reposY: number; // position verticale du burst statique (réduire les animations)
  reposOpacite: number; // opacité du burst statique
};

const NOMBRE = 32;

function palette(c: Couleurs): string[] {
  return [
    c.moment.accueil,
    c.moment.ateliers,
    c.moment.dirigees,
    c.moment.recreation,
    c.moment.sortie,
    c.moment.social,
    c.action[0],
    c.action[1],
  ];
}

function entier(min: number, max: number): number {
  return Math.floor(min + Math.random() * (max - min + 1));
}

/**
 * Le tirage des pièces, hors du composant : `Math.random()` est impur, il n'a
 * pas sa place dans le corps d'un rendu. Le composant l'appelle depuis un
 * `useMemo`, donc une fois par taille d'écran, comme avant.
 */
function tirerPieces(width: number, height: number, couleurs: string[]): Piece[] {
  return Array.from({ length: NOMBRE }, () => {
    const signe = Math.random() < 0.5 ? -1 : 1;
    return {
      gauche: Math.random() * width,
      taille: entier(6, 12),
      couleur: couleurs[entier(0, couleurs.length - 1)],
      rond: Math.random() < 0.5,
      derive: signe * (20 + Math.random() * 45),
      oscillations: 1 + Math.random() * 2,
      tours: signe * (1 + Math.random() * 2),
      delai: Math.round(Math.random() * 320),
      duree: Math.round(2200 + Math.random() * 600),
      // Burst statique : quart supérieur de l'écran, dispersé.
      reposY: 40 + Math.random() * (height * 0.22),
      reposOpacite: 0.35 + Math.random() * 0.25,
    };
  });
}

export function Confettis() {
  const c = useCouleurs();
  const reduire = useReducedMotion();
  const { width, height } = useWindowDimensions();

  // On tire les pièces une fois : la dispersion est aléatoire mais fixe pour la
  // durée de vie de l'overlay. On re-tire seulement si l'écran change de taille
  // (rotation), sans quoi une pièce partirait hors-champ.
  const couleurs = palette(c);
  const pieces = useMemo<Piece[]>(() => {
    return tirerPieces(width, height, couleurs);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [width, height]);

  return (
    <View pointerEvents="none" style={StyleSheet.absoluteFill}>
      {pieces.map((piece, i) => (
        <PieceConfetti key={i} piece={piece} hauteur={height} reduire={reduire} />
      ))}
    </View>
  );
}

/**
 * Une pièce animée. Sous « réduire les animations », elle ne bouge pas : elle se
 * pose à sa position de repos, à faible opacité. Sinon, elle chute du haut vers
 * le bas sur ~2,5 s, dérive latéralement en douceur, tourne sur elle-même, et
 * s'estompe en fin de course.
 */
function PieceConfetti({
  piece,
  hauteur,
  reduire,
}: {
  piece: Piece;
  hauteur: number;
  reduire: boolean;
}) {
  // La progression va de 0 (au-dessus de l'écran) à 1 (sous l'écran). Une seule
  // valeur pilote chute, dérive, rotation et fondu, ce qui garde tout synchrone.
  const progres = useSharedValue(reduire ? 1 : 0);

  useEffect(() => {
    // 🚨 Sous « réduire les animations », aucune chute : on saute directement à
    // l'état de repos, jamais de `withTiming`.
    if (reduire) {
      progres.value = 1;
      return;
    }
    progres.value = 0;
    progres.value = withDelay(
      piece.delai,
      // Chute accélérée (Easing.in) : le confetti prend de la vitesse en tombant.
      withTiming(1, { duration: piece.duree, easing: Easing.in(Easing.quad) }),
    );
  }, [reduire, progres, piece]);

  const style = useAnimatedStyle(() => {
    if (reduire) {
      return {
        transform: [{ translateY: piece.reposY }, { translateX: 0 }, { rotate: '0deg' }],
        opacity: piece.reposOpacite,
      };
    }
    const p = progres.value;
    const y = -30 + p * (hauteur + 60);
    const x = piece.derive * Math.sin(p * Math.PI * piece.oscillations);
    const rot = p * piece.tours * 360;
    // Fondu : entrée franche, tenue, puis disparition sur le dernier quart.
    const opacite = interpolate(p, [0, 0.08, 0.72, 1], [0, 1, 1, 0], Extrapolation.CLAMP);
    return {
      transform: [{ translateY: y }, { translateX: x }, { rotate: `${rot}deg` }],
      opacity: opacite,
    };
  });

  return (
    <Animated.View
      style={[
        styles.piece,
        {
          left: piece.gauche,
          width: piece.taille,
          height: piece.taille,
          borderRadius: piece.rond ? piece.taille / 2 : 2,
          backgroundColor: piece.couleur,
        },
        style,
      ]}
    />
  );
}

const styles = StyleSheet.create({
  piece: { position: 'absolute', top: 0 },
});
