import { couvertureDe, oublierCatalogue, type Classe, type Perimetre } from './donnees';
import { lireNiveaux, niveauxDeCompetence } from './niveaux';
import { supabase } from './supabase';

/**
 * Ce qu'une classe enseigne RÉELLEMENT, au grain du domaine.
 *
 * Retour de Mme Mahé (primaire) : cocher un référentiel en entier est trop
 * grossier. Une prof qui ne donne que le français, ou qui travaille en
 * immersion, veut préciser les DOMAINES qu'elle enseigne à l'intérieur d'un
 * référentiel qu'elle garde actif.
 *
 * 🔑 Le mécanisme est celui, déjà en place, de `classroom_framework_exclusions`,
 * descendu d'un cran : `classroom_domain_exclusions`. Une ligne = ce domaine est
 * ÉCARTÉ. Absence de ligne = domaine enseigné (le défaut). Ce sens « exclusion »
 * rend tout rétro-compatible sans backfill : les classes existantes n'ont aucune
 * ligne, donc tous leurs domaines restent enseignés, exactement comme avant.
 *
 * Tout passe par ici et jamais par un écran. ⚠️ Depuis le co-enseignement (Étape 2),
 * la RLS ouvre une classe à PLUSIEURS profs et ne discrimine pas le `teacher_id` :
 * on filtre/écrit donc EXPLICITEMENT `teacher_id = auth.uid()` ci-dessous, pour que
 * chaque prof ne voie et ne touche que SA propre délégation.
 */

/** Découpe une liste d'identifiants : une requête avec 400 UUID dépasse la longueur d'URL. */
function parPaquets<T>(liste: T[], taille = 100): T[][] {
  const paquets: T[][] = [];
  for (let i = 0; i < liste.length; i += taille) paquets.push(liste.slice(i, i + taille));
  return paquets;
}

/**
 * Mon identifiant enseignant·e (co-enseignement / immersion Étape 2).
 *
 * La sélection fine est PAR PROF : `classroom_domain_exclusions` et
 * `classroom_competency_status` portent désormais un `teacher_id`, et chaque
 * co-enseignant·e a SA propre délégation. Toute lecture/écriture ci-dessous
 * filtre/écrit `teacher_id = auth.uid()`. Retro-compat : sur une classe sans
 * co-prof, `auth.uid()` = propriétaire, et ses lignes historiques (backfillées
 * au propriétaire par la migration) sont exactement celles d'aujourd'hui.
 */
async function monUid(): Promise<string> {
  const { data } = await supabase.auth.getUser();
  return data.user?.id ?? '';
}

export type DomaineEnseigne = {
  id: string;
  nom: string;
  competences: number;
  attendus: number;
  /** Faux quand la classe a écarté ce domaine. Enseigné par défaut. */
  enseigne: boolean;
};

/**
 * Les domaines d'UN référentiel actif, avec leur volume et l'état enseigné/écarté.
 *
 * Chargé à la demande, quand l'enseignante déplie un référentiel : inutile de
 * lire les domaines des sept référentiels d'un coup alors qu'elle n'en précise
 * qu'un à la fois.
 *
 * 🔑 On compte les compétences et attendus AU NIVEAU DE LA CLASSE (filtre
 * `niveau_scolaire`), pas en brut : le chiffre annoncé doit être celui qu'elle
 * enseigne vraiment, pas celui du référentiel entier. C'est le même comptage que
 * `referentielsDeLaClasse`, appliqué domaine par domaine.
 */
export async function domainesDuReferentiel(
  classe: Perimetre,
  referentielId: string,
): Promise<DomaineEnseigne[]> {
  const niveauxClasse = lireNiveaux(classe.cycle);
  const uid = await monUid();

  const [domainesRes, exclusionsRes] = await Promise.all([
    supabase.from('domains').select('id, name').eq('framework_id', referentielId),
    supabase
      .from('classroom_domain_exclusions')
      .select('domain_id')
      .eq('classroom_id', classe.id ?? '')
      .eq('teacher_id', uid),
  ]);
  if (domainesRes.error) throw domainesRes.error;
  if (exclusionsRes.error) throw exclusionsRes.error;

  const domaines = domainesRes.data ?? [];
  if (!domaines.length) return [];
  const nomDomaine = new Map(domaines.map((d) => [d.id as string, (d.name ?? '') as string]));
  const exclus = new Set((exclusionsRes.data ?? []).map((x) => x.domain_id as string));

  // Compétences par domaine, filtrées au niveau de la classe.
  const domaineParCompetence = new Map<string, string>();
  const compteCompetences = new Map<string, number>();
  for (const paquet of parPaquets([...nomDomaine.keys()])) {
    const { data, error } = await supabase
      .from('competencies')
      .select('id, domain_id, niveau_scolaire')
      .in('domain_id', paquet);
    if (error) throw error;
    for (const c of data ?? []) {
      const niveaux = niveauxDeCompetence(c.niveau_scolaire);
      if (niveaux && niveauxClasse.length && !niveaux.some((n) => niveauxClasse.includes(n))) {
        continue;
      }
      const domaineId = c.domain_id as string;
      domaineParCompetence.set(c.id as string, domaineId);
      compteCompetences.set(domaineId, (compteCompetences.get(domaineId) ?? 0) + 1);
    }
  }

  // Attendus par domaine (via leur compétence).
  const compteAttendus = new Map<string, number>();
  for (const paquet of parPaquets([...domaineParCompetence.keys()])) {
    const { data, error } = await supabase
      .from('expectations')
      .select('competency_id')
      .in('competency_id', paquet);
    if (error) throw error;
    for (const e of data ?? []) {
      const domaineId = domaineParCompetence.get(e.competency_id as string);
      if (!domaineId) continue;
      compteAttendus.set(domaineId, (compteAttendus.get(domaineId) ?? 0) + 1);
    }
  }

  return domaines
    .map((d) => ({
      id: d.id as string,
      nom: (d.name ?? '') as string,
      competences: compteCompetences.get(d.id as string) ?? 0,
      attendus: compteAttendus.get(d.id as string) ?? 0,
      enseigne: !exclus.has(d.id as string),
    }))
    // On ne montre pas un domaine vide au niveau de la classe : il n'y aurait
    // rien à enseigner ni à écarter, et sa case tromperait.
    .filter((d) => d.competences > 0)
    // Le plus gros d'abord, comme pour les référentiels : son exclusion se voit le plus.
    .sort((a, b) => b.competences - a.competences || a.nom.localeCompare(b.nom, 'fr'));
}

/**
 * Marque un domaine enseigné (défaut) ou écarté, pour une classe.
 *
 * `enseigne = true` retire la ligne d'exclusion, `false` l'ajoute. L'ajout est
 * idempotent (contrainte d'unicité + `ignoreDuplicates`) : deux appareils qui
 * basculent le même domaine ne créent pas de doublon.
 *
 * ⚠️ On oublie le catalogue en mémoire, par symétrie avec `basculerReferentiel`.
 * Le catalogue soumis à l'IA ne filtre PAS encore par domaine (ça vivrait dans
 * `donnees.ts`, hors périmètre ici), donc c'est surtout un garde-fou pour le jour
 * où il le fera : mieux vaut vider un cache pour rien que servir un catalogue
 * périmé sans que personne le sache.
 */
export async function basculerDomaine(params: {
  classeId: string;
  domaineId: string;
  enseigne: boolean;
}): Promise<void> {
  const uid = await monUid();
  if (params.enseigne) {
    const { error } = await supabase
      .from('classroom_domain_exclusions')
      .delete()
      .eq('classroom_id', params.classeId)
      .eq('domain_id', params.domaineId)
      .eq('teacher_id', uid);
    if (error) throw error;
  } else {
    const { error } = await supabase
      .from('classroom_domain_exclusions')
      .upsert(
        { classroom_id: params.classeId, domain_id: params.domaineId, teacher_id: uid },
        // La contrainte d'unicité gagne teacher_id (une exclusion par prof).
        { onConflict: 'classroom_id,domain_id,teacher_id', ignoreDuplicates: true },
      );
    if (error) throw error;
  }
  oublierCatalogue(params.classeId);
}

export type DomaineNonVu = {
  /** La source du référentiel (ex. « TC-MATH-BE »), pour situer le domaine. */
  referentiel: string;
  domaine: string;
  /** Combien de compétences ce domaine porte au niveau de la classe. */
  competences: number;
};

/**
 * Les domaines ENSEIGNÉS mais pas encore travaillés cette année : zéro séance
 * clôturée les touche.
 *
 * 🔑 On repart de `couvertureDe`, qui porte déjà la logique délicate (on compte
 * des SÉANCES clôturées, pas des liens ; `deleted_at is null`). Un domaine est
 * « pas encore vu » si AUCUNE de ses compétences n'a été travaillée. On retire
 * ensuite les domaines que la classe a écartés : ce qu'on n'enseigne pas ne peut
 * pas manquer.
 *
 * C'est le signal utile de la sélection fine : une fois qu'elle a dit ce qu'elle
 * enseigne, l'app peut lui pointer ce qui lui reste à ouvrir, sans le noyer sous
 * des domaines qui ne la concernent pas.
 *
 * ⚠️ Comme `SEUIL_RESISTE`, ceci ne connaît pas le calendrier : un domaine non
 * travaillé en septembre est normal. La carte le présente donc comme un repère,
 * pas comme un reproche.
 */
export async function domainesNonVus(classe: Classe): Promise<DomaineNonVu[]> {
  const couverture = await couvertureDe(classe);
  if (!couverture.length) return [];

  const SEP = '\u0000';
  const groupes = new Map<string, { referentiel: string; domaine: string; competences: number; seances: number }>();
  for (const c of couverture) {
    // On saute les competences DELEGUEES : elles restent dans la couverture
    // (0 seance, pour le label collegue) mais un domaine entierement delegue
    // n'est pas « a ouvrir » : ce n'est pas a moi de le travailler.
    if (!c.domaine || c.delegue) continue;
    const cle = `${c.referentiel}${SEP}${c.domaine}`;
    const g = groupes.get(cle) ?? { referentiel: c.referentiel, domaine: c.domaine, competences: 0, seances: 0 };
    g.competences += 1;
    g.seances += c.seances;
    groupes.set(cle, g);
  }

  // Plus de re-filtrage des exclusions ici : couvertureDe a deja retire les
  // domaines ecartes et les competences hors programme. Un domaine ne remonte
  // « pas encore vu » que si aucune de ses competences (non deleguees) n'a de
  // seance.
  return [...groupes.entries()]
    .filter(([, g]) => g.seances === 0)
    .map(([, g]) => ({ referentiel: g.referentiel, domaine: g.domaine, competences: g.competences }))
    .sort((a, b) => a.referentiel.localeCompare(b.referentiel, 'fr') || a.domaine.localeCompare(b.domaine, 'fr'));
}

/**
 * Les trois etats qu'une competence peut prendre pour une classe (immersion).
 *
 *   * `enseignee` : le defaut. AUCUNE ligne en base (rétro-compatibilité).
 *   * `deleguee`  : suivie par un·e collegue. Sort de ma couverture mais reste
 *     au programme de l'eleve, avec un label « suivi par un·e collegue ».
 *   * `exclue`    : hors programme. Disparait de tout, comme un domaine ecarte
 *     mais pour une seule competence.
 *
 * Le stockage vit dans `classroom_competency_status` : une ligne pour `deleguee`
 * ou `exclue`, aucune pour `enseignee`. C'est ce qui rend l'ajout rétro-compatible
 * sans backfill (voir la migration).
 */
export type StatutCompetence = 'enseignee' | 'deleguee' | 'exclue';

export type CompetenceStatut = {
  id: string;
  libelle: string;
  /** Combien d'attendus la competence porte : le volume, comme pour un domaine. */
  attendus: number;
  statut: StatutCompetence;
};

/**
 * Les compétences d'UN domaine, filtrées au niveau de la classe, avec leur
 * statut (enseignée / déléguée / hors programme) et leur volume d'attendus.
 *
 * Chargé à la demande, quand l'enseignante déplie un domaine : on descend d'un
 * cran sous `domainesDuReferentiel`, même logique de comptage au niveau de la
 * classe (filtre `niveau_scolaire`), pour que le grain fin de l'immersion soit
 * réglable là où elle regarde déjà ses domaines.
 */
export async function competencesDuDomaine(
  classe: Perimetre,
  domaineId: string,
): Promise<CompetenceStatut[]> {
  const niveauxClasse = lireNiveaux(classe.cycle);
  const uid = await monUid();

  const [competencesRes, statutsRes] = await Promise.all([
    supabase.from('competencies').select('id, label, niveau_scolaire').eq('domain_id', domaineId),
    supabase
      .from('classroom_competency_status')
      .select('competency_id, status')
      .eq('classroom_id', classe.id ?? '')
      .eq('teacher_id', uid),
  ]);
  if (competencesRes.error) throw competencesRes.error;
  if (statutsRes.error) throw statutsRes.error;

  const statutParId = new Map<string, StatutCompetence>();
  for (const s of statutsRes.data ?? []) {
    statutParId.set(s.competency_id as string, s.status as StatutCompetence);
  }

  // On garde les compétences du niveau de la classe (même filtre que partout).
  const retenues: { id: string; libelle: string }[] = [];
  for (const c of competencesRes.data ?? []) {
    const niveaux = niveauxDeCompetence(c.niveau_scolaire);
    if (niveaux && niveauxClasse.length && !niveaux.some((n) => niveauxClasse.includes(n))) continue;
    retenues.push({ id: c.id as string, libelle: (c.label ?? '') as string });
  }
  if (!retenues.length) return [];

  // Le volume d'attendus par compétence, en un seul aller-retour paginé.
  const compteAttendus = new Map<string, number>();
  for (const paquet of parPaquets(retenues.map((c) => c.id))) {
    const { data, error } = await supabase
      .from('expectations')
      .select('competency_id')
      .in('competency_id', paquet);
    if (error) throw error;
    for (const e of data ?? []) {
      const id = e.competency_id as string;
      compteAttendus.set(id, (compteAttendus.get(id) ?? 0) + 1);
    }
  }

  return retenues
    .map((c) => ({
      id: c.id,
      libelle: c.libelle,
      attendus: compteAttendus.get(c.id) ?? 0,
      statut: statutParId.get(c.id) ?? ('enseignee' as StatutCompetence),
    }))
    .sort((a, b) => a.libelle.localeCompare(b.libelle, 'fr'));
}

/**
 * Le statut d'UNE compétence pour une classe. `enseignee` par défaut (aucune
 * ligne). Utile pour un affichage ponctuel sans recharger tout un domaine.
 */
export async function statutCompetence(
  classe: Perimetre,
  competencyId: string,
): Promise<StatutCompetence> {
  const uid = await monUid();
  const { data, error } = await supabase
    .from('classroom_competency_status')
    .select('status')
    .eq('classroom_id', classe.id ?? '')
    .eq('competency_id', competencyId)
    .eq('teacher_id', uid)
    .maybeSingle();
  if (error) throw error;
  return (data?.status as StatutCompetence) ?? 'enseignee';
}

/**
 * Fixe le statut d'une compétence pour une classe. Idempotent :
 *
 *   * `enseignee` retire la ligne (retour au défaut) ;
 *   * `deleguee` / `exclue` posent (ou changent) la ligne, via un upsert sur la
 *     contrainte d'unicité `(classroom_id, competency_id)`. Deux appareils qui
 *     basculent la même compétence hors-ligne ne créent pas de doublon, et un
 *     changement d'état écrase proprement le précédent.
 *
 * ⚠️ On oublie le catalogue en mémoire, comme `basculerDomaine` : sans ça l'IA
 * continuerait à proposer des attendus d'une compétence qu'on vient de déléguer
 * ou d'exclure.
 */
export async function definirStatutCompetence(params: {
  classeId: string;
  competencyId: string;
  statut: StatutCompetence;
}): Promise<void> {
  const uid = await monUid();
  if (params.statut === 'enseignee') {
    const { error } = await supabase
      .from('classroom_competency_status')
      .delete()
      .eq('classroom_id', params.classeId)
      .eq('competency_id', params.competencyId)
      .eq('teacher_id', uid);
    if (error) throw error;
  } else {
    const { error } = await supabase
      .from('classroom_competency_status')
      .upsert(
        {
          classroom_id: params.classeId,
          competency_id: params.competencyId,
          status: params.statut,
          teacher_id: uid,
        },
        // La contrainte d'unicité gagne teacher_id (un statut par prof).
        { onConflict: 'classroom_id,competency_id,teacher_id' },
      );
    if (error) throw error;
  }
  oublierCatalogue(params.classeId);
}
