import { Feather } from '@expo/vector-icons';
import { router, useLocalSearchParams } from 'expo-router';
import { useEffect, useMemo } from 'react';
import { Pressable, ScrollView, StyleSheet, View } from 'react-native';
import Animated, {
  Easing,
  FadeInDown,
  ReduceMotion,
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withRepeat,
  withTiming,
} from 'react-native-reanimated';
import { SafeAreaView } from 'react-native-safe-area-context';

import { Cloudy } from '@/components/cloudy';
import { Confettis } from '@/components/confettis';
import { BoutonPrincipal, BoutonSecondaire } from '@/components/formulaire';
import { Trophee } from '@/components/trophee';
import { t } from '@/i18n';
import { espace, motion, ombre, police, useCouleurs, type Couleurs } from '@/theme/tokens';

/** Une entrée en fondu montant, décalée, qui respecte « réduire les animations ». */
const entree = (delai: number) =>
  FadeInDown.duration(motion.duree.normal).delay(delai).reduceMotion(ReduceMotion.System);

/**
 * L'écran de célébration d'un PALIER DE TROPHÉE : franchir un jalon d'activités
 * clôturées (1, 3, 5, 10…). Frère de `app/celebration.tsx` (la semaine bouclée),
 * même patron : Cloudy en fête, un halo qui respire, la croix HORS du ScrollView.
 *
 * Il est purement présentationnel : il reçoit le palier atteint par param de
 * route et ne décide de rien. Le point de déclenchement (quand l'ouvrir, et le
 * garde anti-répétition) vit dans `lib/celebration.ts`, appelé après une clôture
 * réussie. Ici on ne fait que fêter.
 *
 * 🚨 La croix vit HORS du ScrollView, comme partout dans l'app : elle reste
 * visible même quand on descend. Même patron que le paywall et la semaine bouclée.
 *
 * Les confettis se posent en overlay au-dessus de tout, `pointerEvents="none"` :
 * ils ne prennent jamais le doigt, on ferme l'écran dessous pendant qu'ils
 * retombent. Ils se coupent d'eux-mêmes sous « réduire les animations ».
 */
function nombre(v: string | undefined, defaut: number) {
  if (!v) return defaut;
  const n = parseInt(v, 10);
  return Number.isFinite(n) ? n : defaut;
}

export default function TropheeCelebration() {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const params = useLocalSearchParams<{ palier?: string }>();
  const palier = nombre(params.palier, 1);

  // Le halo derrière Cloudy respire, comme un souffle de fête qui ne retombe pas.
  // Coupé sous « réduire les animations ».
  const reduire = useReducedMotion();
  const pulse = useSharedValue(1);
  useEffect(() => {
    if (reduire) return;
    pulse.value = withRepeat(
      withTiming(1.08, { duration: 2600, easing: Easing.inOut(Easing.quad) }),
      -1,
      true,
    );
  }, [reduire, pulse]);
  const styleHalo = useAnimatedStyle(() => ({ transform: [{ scale: pulse.value }] }));

  return (
    <SafeAreaView style={styles.racine} edges={['top', 'bottom']}>
      <Pressable
        accessibilityRole="button"
        accessibilityLabel={t.moi.celebreFermer}
        onPress={() => router.back()}
        style={styles.fermer}>
        <Feather name="x" size={22} color={c.encreDouce} />
      </Pressable>

      <ScrollView contentContainerStyle={styles.contenu} showsVerticalScrollIndicator={false}>
        {/* Une seule mascotte par écran, en célébration : elle porte l'émotion,
            le fond reste neutre (charte v9). Le trophée du palier se pose à côté,
            en évidence, sur son propre halo miel. */}
        <View style={styles.scene}>
          <View style={styles.mascotte}>
            <Animated.View style={[styles.halo, styleHalo]} pointerEvents="none" />
            <Cloudy pose="celebration" taille={120} anime respire />
          </View>
          <View style={styles.tropheeBoite}>
            <Trophee palier={palier} obtenu taille={92} />
          </View>
        </View>

        <Animated.Text entering={entree(120)} style={styles.titre}>
          {t.moi.celebreTitre(palier)}
        </Animated.Text>
        <Animated.Text entering={entree(200)} style={styles.sous}>
          {t.moi.celebreSous}
        </Animated.Text>

        <Animated.View entering={entree(320)} style={styles.actions}>
          {/* « Génial ! » referme la fête et rend la main à l'écran dessous. */}
          <BoutonPrincipal libelle={t.moi.celebreFermer} onPress={() => router.back()} />
          {/* « Voir ma collection » ouvre l'onglet Moi, où vit la collection de
              trophées : on remplace la modale plutôt que de l'empiler. */}
          <BoutonSecondaire libelle={t.moi.celebreVoir} onPress={() => router.replace('/vous')} />
        </Animated.View>
      </ScrollView>

      {/* Les confettis, une seule fois à l'ouverture, par-dessus tout le reste. */}
      <Confettis />
    </SafeAreaView>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    racine: { flex: 1, backgroundColor: c.fond },
    fermer: {
      position: 'absolute',
      top: espace.md,
      right: espace.md,
      zIndex: 10,
      width: 36,
      height: 36,
      borderRadius: 18,
      backgroundColor: c.surface,
      alignItems: 'center',
      justifyContent: 'center',
      ...ombre.carte,
    },
    contenu: {
      padding: espace.lg,
      paddingTop: espace.xl * 2,
      paddingBottom: espace.xl,
      gap: espace.md,
    },
    // Cloudy et le trophée côte à côte, centrés : la mascotte porte l'émotion, le
    // trophée dit lequel des jalons vient d'être franchi.
    scene: {
      flexDirection: 'row',
      alignItems: 'center',
      justifyContent: 'center',
      gap: espace.sm,
    },
    // Boîte carrée qui cadre la mascotte et son auréole : taille fixe pour que le
    // halo, absolu, se centre proprement dessous.
    mascotte: {
      width: 170,
      height: 170,
      alignItems: 'center',
      justifyContent: 'center',
    },
    // Auréole miel derrière la mascotte. Absolue, elle remplit la boîte (un disque
    // de 170) sans pousser la mise en page ; la mascotte passe au-dessus.
    halo: {
      position: 'absolute',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      borderRadius: 85,
      backgroundColor: c.actionTeinte,
    },
    tropheeBoite: { alignItems: 'center', justifyContent: 'center' },
    titre: {
      fontFamily: police.titre,
      fontSize: 32,
      lineHeight: 36,
      color: c.encre,
      textAlign: 'center',
      marginTop: espace.sm,
    },
    sous: {
      fontFamily: police.corps,
      fontSize: 17,
      lineHeight: 24,
      color: c.encreDouce,
      textAlign: 'center',
      marginBottom: espace.sm,
    },
    actions: { gap: espace.sm, marginTop: espace.sm },
  });
