import { Feather } from '@expo/vector-icons';
import { router, useLocalSearchParams } from 'expo-router';
import { useMemo, useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';

import { Cloudy } from '@/components/cloudy';
import { Carte, EnteteSection } from '@/components/ecran';
import { type Moment, Tuile } from '@/components/elements';
import {
  Alerte,
  BoutonDiscret,
  BoutonPrincipal,
  Champ,
  Pastilles,
} from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { t } from '@/i18n';
import { effacerMonCompte, monProfil } from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { useSession } from '@/lib/session';
import { espace, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Ce qui arrive aux données d'une enseignante, et le bouton qui les efface.
 *
 * 🔑 Porté de la page « Sécurité » de l'app web, mais **réécrit**, parce qu'une
 * de ses cinq promesses était fausse : « Les vrais noms ne quittent jamais
 * votre appareil. » Les prénoms sont dans une base en Irlande. Ce qui est vrai,
 * c'est qu'ils ne partent jamais vers l'IA. La page dit maintenant les deux.
 *
 * 🎨 REFONTE VISUELLE v9. L'écran s'ouvre désormais sur une démonstration — le
 * prénom « Lucas » qui devient « Élève 1 » avant l'envoi à l'IA — puis une liste
 * de tuiles teintées, une promesse par tuile. Deux de ces tuiles PORTENT une
 * action réelle : « Tout est exportable » ouvre l'écran d'export, « Tout
 * effacer » lance le flux de suppression. Ni l'export ni la suppression n'ont
 * changé : seule leur présentation l'a fait.
 *
 * Les textes honnêtes de l'ancienne page (l'IA est Claude aux États-Unis, la
 * dictée peut passer par Gladia sur certains téléphones, le cloisonnement au
 * niveau de la base) ne sont pas perdus : ils vivent en détail sous « Pour aller
 * plus loin », parce qu'on ne rassure pas avec une porte qui n'existe pas, et
 * qu'on ne cache pas non plus la seule chose qui sort d'Europe.
 *
 * 🚨 LA SUPPRESSION EST IRRÉVERSIBLE ET ELLE LE DIT TROIS FOIS : dans le texte
 * (la carte de danger qui s'ouvre), dans la confirmation, et par le geste
 * demandé (réécrire son adresse). Apple l'exige pour publier (règle 5.1.1(v)) ;
 * l'exigence porte sur le fait de pouvoir la déclencher depuis l'app, pas sur la
 * façon de la rendre difficile. Le geste coûteux, c'est nous qui le choisissons :
 * il n'y a pas de corbeille derrière, donc il faut que la main hésite.
 */

// Une promesse de la liste : une tuile teintée (icône), un titre, un sous-texte.
// `moment` donne la teinte du socle ; certaines portent une action (export,
// suppression), les autres sont de simples repères.
type Point = {
  icone: keyof typeof Feather.glyphMap;
  moment: Moment;
  titre: string;
  texte: string;
  onPress?: () => void;
};

export default function Donnees() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { session, deconnecter } = useSession();
  const profil = useRequete(monProfil, []);
  // On préfère `||` à `??` : une chaîne vide (profil sans email) doit retomber
  // sur l'email de session, sinon la confirmation serveur (qui EXIGE l'adresse
  // exacte) partirait vide et la suppression échouerait en silence.
  const adresse = (profil.donnees?.email || session?.user.email || '').trim();

  // 🔑 Arrivée directe depuis « Réglages → Supprimer mon compte ». Le lien passe
  // `supprimer=1` pour qu'on ouvre le flux tout de suite, et surtout qu'on le
  // remonte en haut de l'écran (voir plus bas). POURQUOI : Apple (règle
  // 5.1.1(v)) veut la suppression trouvable et évidente. Enfouie sous une tuile
  // au milieu d'un écran « Tes données », le contrôle ne l'a pas trouvée. Ici,
  // celle qui a touché « Supprimer mon compte » tombe droit sur le geste.
  const params = useLocalSearchParams<{ supprimer?: string }>();
  const arriveePourSupprimer = params.supprimer === '1';

  // Trois états, dans l'ordre du parcours : le repos, la question du départ,
  // puis la confirmation. La question ne se contourne pas par le bouton, mais
  // elle se traverse sans rien dire. Ouverte d'emblée si on vient du lien dédié.
  const [etape, setEtape] = useState<'repos' | 'pourquoi' | 'confirmer'>(
    arriveePourSupprimer ? 'pourquoi' : 'repos',
  );
  const [raison, setRaison] = useState<string | null>(null);
  const [commentaire, setCommentaire] = useState('');
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);
  // Vrai une fois la suppression réussie : on montre une confirmation explicite
  // avant de retomber sur la connexion, plutôt qu'un simple basculement d'écran
  // qui ne se lit pas comme « c'est fait ».
  const [supprime, setSupprime] = useState(false);

  // Ouvre le flux de suppression depuis la tuile « Tout effacer ». Repart d'un
  // état propre à chaque fois : ni raison, ni adresse traînée d'une hésitation
  // précédente.
  function ouvrirSuppression() {
    setErreur(null);
    setRaison(null);
    setCommentaire('');
    setEtape('pourquoi');
  }

  // La liste de promesses. La couleur vit ici, sur de petites tuiles teintées,
  // jamais sur un grand aplat (charte v9). L'ordre suit la maquette : ce qui
  // protège d'abord, l'export et la suppression ensuite (les deux gestes).
  const points: Point[] = [
    {
      icone: 'lock',
      moment: 'dirigees',
      titre: t.confiance.pointMasquageTitre,
      texte: t.confiance.pointMasquageTexte,
    },
    {
      icone: 'globe',
      moment: 'accueil',
      titre: t.confiance.pointEuropeTitre,
      texte: t.confiance.pointEuropeTexte,
    },
    {
      icone: 'mic',
      moment: 'sortie',
      titre: t.confiance.pointDicteeTitre,
      texte: t.confiance.pointDicteeTexte,
    },
    {
      icone: 'download',
      moment: 'recreation',
      titre: t.confiance.pointExportTitre,
      texte: t.confiance.pointExportTexte,
      // L'export vit ici : la tuile ouvre l'écran qui rend ses données avant de
      // fermer son compte. C'est l'action d'export existante, inchangée.
      onPress: () => router.push('/vous/exporter'),
    },
    {
      icone: 'trash-2',
      moment: 'social',
      titre: t.confiance.pointEffacerTitre,
      texte: t.confiance.pointEffacerTexte,
      // La tuile déclenche le flux de suppression déjà en place (question du
      // départ, puis confirmation à l'adresse). Elle ne supprime rien elle-même.
      onPress: ouvrirSuppression,
    },
  ];

  async function effacer() {
    setErreur(null);
    // La confirmation d'intention passe par le PARCOURS (Réglages → Supprimer →
    // raison → bouton destructif), pas par la recopie de l'adresse : recopier son
    // email exact était trop piégeux (un testeur, et donc un examinateur, tapait
    // autre chose et le bouton restait muet, sans jamais appeler le serveur). On
    // envoie donc l'adresse connue du compte, que le serveur revérifie de son
    // côté. Sans adresse (ne devrait pas arriver une fois connectée), on le dit.
    if (!adresse) {
      setErreur(t.confiance.effacerErreur);
      return;
    }
    setOccupe(true);
    try {
      await effacerMonCompte({
        confirmation: adresse,
        // « Je préfère ne pas dire » se note aussi : sinon on ne compte que
        // celles qui ont pris le temps, et la statistique ment.
        raison: raison ?? 'sans_reponse',
        commentaire: commentaire.trim() || undefined,
      });
      // Succès : le compte est parti côté serveur. On ARRÊTE le spinner et on
      // montre une confirmation explicite, plutôt que d'attendre la déconnexion
      // pour rebasculer (cet appel `signOut` pouvait pendre sur un compte
      // supprimé, et le spinner tournait alors sans fin). La déconnexion réelle
      // se fait quand l'utilisatrice touche « Revenir à la connexion ».
      setOccupe(false);
      setSupprime(true);
    } catch (e) {
      // Un seul message : on n'expose plus « adresse incorrecte » puisqu'on ne
      // fait plus recopier l'adresse. Toute panne (réseau, serveur) se dit pareil.
      setErreur(t.confiance.effacerErreur);
      setOccupe(false);
    }
  }

  // La carte de danger : le texte d'irréversibilité, puis la question du départ,
  // puis la confirmation à l'adresse. Extraite ici pour être rendue à deux
  // endroits possibles selon le chemin d'arrivée (voir plus bas), sans dupliquer
  // le flux. Elle ne s'ouvre qu'une fois le geste engagé (etape hors « repos »).
  const carteDanger =
    supprime ? (
      // Confirmation explicite : le compte est supprimé. On l'affiche clairement
      // (au lieu de rebasculer en silence), et le retour à la connexion ne se
      // fait que sur le geste de l'utilisatrice, pour qu'elle ait le temps de lire.
      <View style={styles.danger}>
        <Text style={texte.corps}>{t.confiance.effacerFiniTitre}</Text>
        <Text style={styles.detail}>{t.confiance.effacerFiniTexte}</Text>
        <BoutonPrincipal
          libelle={t.confiance.effacerFiniBouton}
          onPress={() => void deconnecter()}
        />
      </View>
    ) : etape !== 'repos' ? (
      <View style={styles.danger}>
        <Text style={texte.corps}>{t.confiance.effacerTitre}</Text>
        <Text style={styles.detail}>{t.confiance.effacerTexte}</Text>

        {erreur ? <Alerte message={erreur} /> : null}

        {etape === 'pourquoi' ? (
          <View style={styles.confirmation}>
            <Text style={texte.corps}>{t.confiance.departTitre}</Text>
            <Text style={styles.detail}>{t.confiance.departTexte}</Text>
            <Pastilles
              options={t.confiance.departRaisons.map((r) => ({ id: r.id, libelle: r.libelle }))}
              choisi={raison}
              onChoisir={(v) => setRaison(v ?? null)}
            />
            {/* Le champ libre n'apparaît pas pour « je préfère ne pas dire » :
                proposer d'en dire plus juste après avoir dit non, c'est insister. */}
            {raison && raison !== 'sans_reponse' ? (
              <>
                <Champ
                  etiquette={t.confiance.departPrecision}
                  value={commentaire}
                  onChangeText={setCommentaire}
                  placeholder={t.confiance.departPrecisionIndice}
                  multiline
                  numberOfLines={3}
                />
                <Text style={styles.detail}>{t.confiance.departPrecisionGarde}</Text>
              </>
            ) : null}
            <Text style={styles.detail}>{t.confiance.departAnonyme}</Text>
            <BoutonPrincipal
              libelle={t.confiance.departSuite}
              onPress={() => setEtape('confirmer')}
              inactif={!raison}
            />
            <BoutonDiscret libelle={t.confiance.effacerRenoncer} onPress={() => setEtape('repos')} />
          </View>
        ) : (
          <View style={styles.confirmation}>
            <Text style={texte.corps}>{t.confiance.effacerConfirmerTitre}</Text>
            <Text style={styles.detail}>{t.confiance.effacerConfirmerTexte(adresse)}</Text>
            {/* L'erreur est rendue ICI, juste au-dessus du bouton, et pas
                seulement en haut de la carte : sinon une panne s'affiche hors
                écran, là où l'on ne regarde pas, et le geste semble muet. */}
            {erreur ? <Alerte message={erreur} /> : null}
            <BoutonPrincipal
              libelle={occupe ? t.confiance.effacerEnCours : t.confiance.effacerDefinitif}
              onPress={effacer}
              occupe={occupe}
              inactif={occupe}
            />
            <BoutonDiscret libelle={t.confiance.effacerRenoncer} onPress={() => setEtape('repos')} />
          </View>
        )}
      </View>
    ) : null;

  return (
    <SousEcran titre={t.confiance.titre} chargement={profil.chargement}>
      {/* Le titre fort, puis la promesse en une phrase. */}
      <View style={styles.hero}>
        <Text style={styles.heroTitre}>{t.confiance.heroTitre}</Text>
        <Text style={styles.heroSous}>{t.confiance.heroSous}</Text>
      </View>

      {/* Arrivée par le lien dédié « Supprimer mon compte » : la carte de danger
          est remontée juste sous le titre, pour tomber droit sur le geste sans
          faire défiler tout l'écran. POURQUOI : Apple veut la suppression
          évidente (règle 5.1.1(v)), et une carte enfouie ne l'est pas. */}
      {arriveePourSupprimer ? carteDanger : null}

      {/* La démonstration : chez toi le prénom, envoyé à l'IA « Élève 1 ». */}
      <Carte>
        <View style={styles.compare}>
          <View style={styles.colonne}>
            <Text style={styles.compareLabel}>{t.confiance.exempleChezToi}</Text>
            <Text style={styles.comparePhrase}>
              <Text style={styles.compareNom}>{t.confiance.exempleNomVrai}</Text>{' '}
              {t.confiance.exemplePhrase}
            </Text>
          </View>
          <Feather name="arrow-right" size={20} color={c.encreDouce} style={styles.fleche} />
          <View style={[styles.colonne, styles.colonneMasquee]}>
            <Text style={styles.compareLabel}>{t.confiance.exempleEnvoye}</Text>
            <Text style={styles.comparePhrase}>
              <Text style={styles.compareNomMasque}>{t.confiance.exempleNomMasque}</Text>{' '}
              {t.confiance.exemplePhrase}
            </Text>
          </View>
        </View>
      </Carte>

      {/* Les promesses, une tuile teintée par ligne. Celles qui portent une
          action (export, suppression) sont tactiles. */}
      {points.map((p) => (
        <Carte key={p.titre} onPress={p.onPress}>
          <View style={styles.ligne}>
            <Tuile icone={p.icone} moment={p.moment} taille={40} />
            <View style={styles.ligneTexte}>
              <Text style={texte.corps}>{p.titre}</Text>
              <Text style={styles.detail}>{p.texte}</Text>
            </View>
            {p.onPress ? (
              <Feather name="chevron-right" size={20} color={c.nonRattache} />
            ) : null}
          </View>
        </Carte>
      ))}

      {/* La sixième promesse, portée par Cloudy : une seule mascotte par écran,
          celle-ci. Pose sereine, elle décore la ligne comme les tuiles décorent
          les autres. */}
      <Carte>
        <View style={styles.ligne}>
          <Cloudy pose="serenite" taille={40} cercle respire={false} />
          <View style={styles.ligneTexte}>
            <Text style={texte.corps}>{t.confiance.pointClasseTitre}</Text>
            <Text style={styles.detail}>{t.confiance.pointClasseTexte}</Text>
          </View>
        </View>
      </Carte>

      {/* La carte de danger, dans sa place d'origine (après les promesses),
          quand on est venu en naviguant l'écran. Si on arrive par le lien dédié
          « Supprimer mon compte », elle est remontée tout en haut à la place, et
          ce bloc-ci ne rend rien (voir plus haut). */}
      {arriveePourSupprimer ? null : carteDanger}

      {/* Le détail honnête, plus bas : ce que résume chaque tuile, dit en entier.
          C'est ici que vit la seule chose qui sort d'Europe (l'IA américaine) et
          le repli Gladia de la dictée. On ne rassure pas à moitié. */}
      <EnteteSection titre={t.confiance.detailTitre} />
      <Carte>
        <Text style={texte.corps}>{t.confiance.intro}</Text>
      </Carte>
      {DETAILS.map((d) => (
        <Carte key={d.titre}>
          <Text style={texte.corps}>{d.titre}</Text>
          <Text style={styles.detail}>{d.texte}</Text>
        </Carte>
      ))}
    </SousEcran>
  );
}

// Les six textes honnêtes, en entier, sous « Pour aller plus loin ». Déclarés
// hors du composant : ils ne dépendent d'aucun état, seulement des libellés.
const DETAILS: { titre: string; texte: string }[] = [
  { titre: t.confiance.masquageTitre, texte: t.confiance.masquageTexte },
  { titre: t.confiance.lieuTitre, texte: t.confiance.lieuTexte },
  { titre: t.confiance.iaTitre, texte: t.confiance.iaTexte },
  { titre: t.confiance.dicteeTitre, texte: t.confiance.dicteeTexte },
  { titre: t.confiance.cloisonTitre, texte: t.confiance.cloisonTexte },
  { titre: t.confiance.rienTitre, texte: t.confiance.rienTexte },
];

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    detail: { fontFamily: police.corps, fontSize: 14, lineHeight: 21, color: c.encreDouce },

    hero: { gap: espace.xs, paddingHorizontal: espace.xs },
    heroTitre: {
      fontFamily: police.titre,
      fontSize: 28,
      lineHeight: 32,
      color: c.encre,
      letterSpacing: -0.5,
    },
    heroSous: { fontFamily: police.corps, fontSize: 15, lineHeight: 22, color: c.encreDouce },

    compare: { flexDirection: 'row', alignItems: 'center', gap: espace.sm },
    colonne: {
      flex: 1,
      backgroundColor: c.fond,
      borderRadius: rayon.bloc,
      padding: espace.md,
      gap: espace.xs,
    },
    // La colonne « envoyé à l'IA » prend la teinte lavande de « dirigées » : la
    // couleur vit sur une petite surface, jamais en grand aplat.
    colonneMasquee: { backgroundColor: c.teinte.dirigees },
    compareLabel: { fontFamily: police.accent, fontSize: 12, color: c.encreDouce },
    comparePhrase: { fontFamily: police.corps, fontSize: 14, lineHeight: 20, color: c.encre },
    compareNom: { fontFamily: police.titre, color: c.encre },
    compareNomMasque: { fontFamily: police.titre, color: c.moment.dirigees },
    fleche: { marginTop: 20 },

    ligne: { flexDirection: 'row', alignItems: 'center', gap: espace.md },
    ligneTexte: { flex: 1, gap: 2 },

    danger: {
      backgroundColor: c.fond,
      borderWidth: 1,
      borderColor: c.bord,
      borderRadius: rayon.carte,
      padding: espace.md,
      gap: espace.sm,
    },
    confirmation: { gap: espace.sm, marginTop: espace.xs },
  });
