import { Feather } from '@expo/vector-icons';
import { router, useLocalSearchParams } from 'expo-router';
import { useMemo, useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

import { Carte } from '@/components/ecran';
import { type Moment, Tuile } from '@/components/elements';
import { Alerte, BoutonDiscret, Pastilles } from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import { localeDate } from '@/lib/dates';
import {
  activitesDuProjet,
  changerEtatProjet,
  creneauxDe,
  projetsDe,
  type ActiviteListe,
  type Creneau,
  type Projet,
} from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, police, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Un projet et ses activités.
 *
 * L'écran répond à « où j'en suis dans ma séquence », donc l'avancement passe
 * devant la liste : le chiffre avant le tableau, comme partout ailleurs.
 *
 * ⚠️ **Terminer un projet ne termine aucune activité.** Ce sont deux échelles
 * de temps, et une séance non clôturée reste à clôturer même si la séquence est
 * finie. L'écran le dit, parce que l'inverse semblerait logique et ferait
 * disparaître des séances de la couverture sans que personne le demande.
 */

const ETATS: Projet['statut'][] = ['active', 'paused', 'completed'];

/** L'icône d'un moment de la journée, pour sa tuile teintée. */
const ICONE_MOMENT: Record<Moment, keyof typeof Feather.glyphMap> = {
  accueil: 'sunrise',
  ateliers: 'grid',
  dirigees: 'edit-2',
  recreation: 'coffee',
  sortie: 'map-pin',
  social: 'users',
};

function libelleDate(dateIso: string | null): string {
  if (!dateIso) return t.activite.sansDate;
  const [a, m, j] = dateIso.split('-').map((n) => parseInt(n, 10));
  const d = new Date(a, m - 1, j);
  const s = d.toLocaleDateString(localeDate(), { weekday: 'long', day: 'numeric', month: 'long' });
  return s.charAt(0).toLocaleUpperCase('fr') + s.slice(1);
}

export default function FicheProjet() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { id } = useLocalSearchParams<{ id: string }>();
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;

  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);

  const projets = useRequete(() => projetsDe(classeId!), [classeId], { actif: !!classeId });
  const activites = useRequete(() => activitesDuProjet(id!), [id], { actif: !!id });
  const creneaux = useRequete(() => creneauxDe(classeId!), [classeId], { actif: !!classeId });

  const projet = (projets.donnees ?? []).find((p) => p.id === id) ?? null;
  const parCreneau = new Map((creneaux.donnees ?? []).map((c) => [c.id, c]));

  async function changerEtat(statut: Projet['statut']) {
    if (!projet) return;
    setErreur(null);
    setOccupe(true);
    try {
      await changerEtatProjet({ projetId: projet.id, statut });
      projets.recharger();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.projet.erreurCreation);
    } finally {
      setOccupe(false);
    }
  }

  return (
    <SousEcran
      titre={projet?.titre ?? t.projet.titre}
      chargement={projets.chargement || activites.chargement}>
      {!projet ? (
        <Carte>
          <Text style={texte.discret}>{t.activite.introuvable}</Text>
        </Carte>
      ) : (
        <>
          {/* Le chiffre avant le tableau. */}
          <Carte>
            <Text style={texte.section}>
              {t.projet.avancement(projet.faites, projet.activites)}
            </Text>
            {projet.activites > 0 ? (
              <View style={styles.jauge}>
                <View
                  style={[
                    styles.jaugeRemplie,
                    { width: `${Math.round((projet.faites / projet.activites) * 100)}%` },
                  ]}
                />
              </View>
            ) : null}
            {t.projet.periode(projet.debut, projet.fin) ? (
              <Text style={texte.discret}>{t.projet.periode(projet.debut, projet.fin)}</Text>
            ) : null}
          </Carte>

          <Carte>
            <Pastilles
              options={ETATS.map((e) => ({ id: e, libelle: t.projet.etats[e] }))}
              choisi={projet.statut}
              onChoisir={(v) => (v ? changerEtat(v as Projet['statut']) : undefined)}
            />
            <Text style={styles.aide}>{t.projet.terminerAide}</Text>
          </Carte>

          {erreur ? <Alerte message={erreur} /> : null}

          {(activites.donnees ?? []).length === 0 ? (
            <Carte>
              <Text style={texte.discret}>{t.projet.vide}</Text>
            </Carte>
          ) : (
            (activites.donnees ?? []).map((a) => (
              <LigneActivite
                key={a.id}
                activite={a}
                creneau={a.creneauId ? parCreneau.get(a.creneauId) : undefined}
              />
            ))
          )}

          <BoutonDiscret
            libelle={t.activite.nouvelle}
            onPress={() => router.push('/activite/nouvelle')}
          />
        </>
      )}
    </SousEcran>
  );
}

function LigneActivite({ activite, creneau }: { activite: ActiviteListe; creneau?: Creneau }) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const faite = activite.statut === 'completed';
  const detail = [
    libelleDate(activite.date),
    creneau ? `${creneau.debut} ${creneau.libelle}` : null,
    faite ? t.activite.faite : t.activite.aFaire,
  ]
    .filter(Boolean)
    .join(' · ');

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={`${activite.titre}, ${detail}`}
      onPress={() => router.push({ pathname: '/activite/[id]', params: { id: activite.id } })}>
      <Carte compacte>
        <View style={styles.ligne}>
          {/* Vert « fait » d'abord, sinon la couleur du moment, gris quand il
              n'est pas connu. */}
          {faite ? (
            <Tuile icone="check" moment="recreation" />
          ) : creneau?.moment ? (
            <Tuile icone={ICONE_MOMENT[creneau.moment]} moment={creneau.moment} />
          ) : (
            <Tuile icone="clock" />
          )}
          <View style={styles.corps}>
            <Text style={texte.corps}>{activite.titre}</Text>
            <Text style={texte.discret}>{detail}</Text>
          </View>
          <Feather name="chevron-right" size={20} color={c.nonRattache} />
        </View>
      </Carte>
    </Pressable>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  aide: { fontFamily: police.corps, fontSize: 14, color: c.encreDouce },
  ligne: { flexDirection: 'row', gap: espace.md, alignItems: 'center' },
  corps: { flex: 1, gap: espace.xs },
  jauge: { height: 8, borderRadius: 4, backgroundColor: c.fond, overflow: 'hidden' },
  jaugeRemplie: { height: 8, borderRadius: 4, backgroundColor: c.action[0] },
});
