import { Feather } from '@expo/vector-icons';
import {
  RecordingPresets,
  requestRecordingPermissionsAsync,
  setAudioModeAsync,
  useAudioRecorder,
  useAudioRecorderState,
} from 'expo-audio';
import * as Haptics from 'expo-haptics';
import { LinearGradient } from 'expo-linear-gradient';
import {
  ExpoSpeechRecognitionModule,
  useSpeechRecognitionEvent,
} from 'expo-speech-recognition';
import { useEffect, useMemo, useRef, useState } from 'react';
import { ActivityIndicator, Platform, Pressable, StyleSheet, Text, View } from 'react-native';
import Animated, {
  cancelAnimation,
  Easing,
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withRepeat,
  withTiming,
} from 'react-native-reanimated';

import { t } from '@/i18n';
import { transcrire } from '@/lib/donnees';
import { espace, motion, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * Le bouton qui écoute, et rend du texte.
 *
 * 🔑 **Le geste fréquent doit être le moins cher.** Une enseignante de
 * maternelle n'a pas deux mains libres. Dire « Zoé a compté jusqu'à douze toute
 * seule » prend quatre secondes ; le taper accroupie près du bac à sable en
 * prend vingt, et c'est vingt secondes où elle ne regarde plus sa classe.
 *
 * 🚨 **Le texte revient AVEC les prénoms, et se pose dans le champ.**
 *
 * Pas de rangement automatique, pas d'envoi direct : le texte atterrit dans la
 * zone de saisie, exactement comme si elle l'avait tapé. Deux raisons, et la
 * seconde compte plus que la première.
 *
 * La première : une transcription se trompe. « toute seule » est revenu en
 * « toutes seules » à l'essai. Elle doit pouvoir corriger avant de ranger.
 *
 * La seconde : à partir du champ de saisie, un texte dicté et un texte tapé
 * suivent EXACTEMENT le même chemin, donc le même masquage avant l'IA. Un
 * raccourci qui enverrait la dictée directement créerait un deuxième chemin, et
 * un deuxième chemin, c'est un deuxième trou à surveiller.
 *
 * ⚠️ **L'audio ne se range nulle part.** Il part, revient en texte, disparaît.
 * C'est ce que promet le texte de l'autorisation micro, et il faut que ce soit
 * vrai.
 *
 * 🔑 **La reconnaissance se fait SUR L'APPAREIL en premier.** C'est le chemin
 * principal : le téléphone transcrit lui-même, l'audio ne part jamais sur le
 * réseau, et ça marche sans connexion. Deux gains qui vont ensemble, la vie
 * privée des enfants et la classe sans wifi.
 *
 * Le serveur (Gladia) reste en REPLI, derrière un test de disponibilité. Un
 * appareil sans reconnaissance embarquée, une locale française non installée,
 * ou le web : on retombe alors sur l'enregistrement + transcription serveur,
 * exactement comme avant. Le test se fait avant d'écouter, pas au milieu : une
 * bascule en cours de dictée perdrait ce qui a déjà été dit.
 *
 * Dans les deux cas, la sortie est la même : du texte, avec les prénoms, posé
 * dans le champ via `onTexte`. Jamais rangé, jamais envoyé directement.
 */
export function Dictee({
  onTexte,
  inactif = false,
  hero = false,
}: {
  /** Le texte transcrit, à poser dans le champ. Jamais à ranger directement. */
  onTexte: (texte: string) => void;
  inactif?: boolean;
  /**
   * Variante « héro » : le gros bouton micro à halo dégradé du témoin v9, pièce
   * maîtresse de l'écran Capter. Même machine d'enregistrement, autre habillage.
   */
  hero?: boolean;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const enregistreur = useAudioRecorder(RecordingPresets.HIGH_QUALITY);
  const etat = useAudioRecorderState(enregistreur);
  const [travail, setTravail] = useState(false);
  const [souci, setSouci] = useState<string | null>(null);

  // Chemin appareil : la reconnaissance embarquée émet des évènements, elle ne
  // rend pas une promesse. On garde son état à part de l'enregistreur audio du
  // chemin serveur.
  const [ecoute, setEcoute] = useState(false);
  const [secondesApp, setSecondesApp] = useState(0);
  // `null` hors dictée. Sert de garde : les évènements `end`/`error` qui
  // arrivent après coup ne doivent agir qu'une fois, et jamais sur le chemin
  // serveur.
  const moteurRef = useRef<'appareil' | null>(null);
  // Le texte final se construit segment par segment (mode continu), l'interim
  // est la phrase en train de se former. La sortie, c'est les deux recollés.
  const finalRef = useRef('');
  const interimRef = useRef('');
  const minuteurRef = useRef<ReturnType<typeof setInterval> | null>(null);
  // 🚨 Garde anti-double-démarrage. `demarrer` est asynchrone (permissions,
  // choix du moteur) et `setEcoute(true)` n'arrive qu'après : un second tap dans
  // cette fenêtre relancerait une deuxième reconnaissance et fuiterait le
  // premier minuteur. Un ref posé de façon synchrone à l'entrée ferme la course
  // là où un état React arriverait trop tard.
  const demarrantRef = useRef(false);

  function arreterMinuteur() {
    if (minuteurRef.current) {
      clearInterval(minuteurRef.current);
      minuteurRef.current = null;
    }
  }

  // On coupe tout à la sortie de l'écran : un minuteur qui tourne dans le vide,
  // et surtout une reconnaissance restée active qui garderait le micro.
  useEffect(() => {
    return () => {
      arreterMinuteur();
      if (moteurRef.current === 'appareil') {
        try {
          ExpoSpeechRecognitionModule.abort();
        } catch {
          // Rien à faire : on quitte, le micro se libère de toute façon.
        }
      }
    };
  }, []);

  function livrer(erreurSiVide: string) {
    arreterMinuteur();
    setEcoute(false);
    setTravail(false);
    moteurRef.current = null;
    const texte = `${finalRef.current} ${interimRef.current}`.trim();
    if (texte) onTexte(texte);
    else setSouci(erreurSiVide);
  }

  /**
   * Le repli serveur : enregistrement audio local, puis transcription par le
   * serveur (Gladia). C'est le chemin d'origine, isolé ici pour qu'on puisse y
   * basculer automatiquement quand l'appareil ne sait pas transcrire, sans le
   * dupliquer. Rend `true` si l'enregistrement a bien démarré.
   */
  async function demarrerServeur(): Promise<boolean> {
    const droit = await requestRecordingPermissionsAsync();
    if (!droit.granted) {
      setSouci(t.dictee.sansMicro);
      return false;
    }
    // Sur iOS, sans ce mode, l'enregistrement passe par le haut-parleur du
    // téléphone et le niveau est inutilisable.
    await setAudioModeAsync({ allowsRecording: true, playsInSilentMode: true });
    await enregistreur.prepareToRecordAsync();
    enregistreur.record();
    return true;
  }

  /**
   * Bascule du chemin appareil vers le serveur, en cours de tentative. On solde
   * d'abord l'état de la reconnaissance embarquée (minuteur, écoute, refs) pour
   * que le chemin serveur reparte propre, puis on lance l'enregistrement. Utilisé
   * quand l'appareil rend une erreur qui n'est ni un refus ni un silence.
   */
  function basculerVersServeur() {
    arreterMinuteur();
    setEcoute(false);
    setTravail(false);
    moteurRef.current = null;
    finalRef.current = '';
    interimRef.current = '';
    demarrantRef.current = false;
    void demarrerServeur();
  }

  // Un résultat final s'ajoute à ce qui précède ; un interim remplace le
  // précédent. On ne prend que la première alternative, la plus probable.
  useSpeechRecognitionEvent('result', (e) => {
    if (moteurRef.current !== 'appareil') return;
    const tx = e.results?.[0]?.transcript ?? '';
    if (e.isFinal) {
      finalRef.current = `${finalRef.current} ${tx}`.trim();
      interimRef.current = '';
    } else {
      interimRef.current = tx;
    }
  });

  // Fin normale : après un `stop()`, ou après un silence en mode non continu.
  useSpeechRecognitionEvent('end', () => {
    if (moteurRef.current !== 'appareil') return;
    livrer(t.dictee.rienEntendu);
  });

  // Une erreur en cours de dictée. Si des mots ont déjà été captés, on les rend
  // quand même plutôt que de les jeter. Sinon on trie : un refus de permission
  // ou un silence ont un message propre ; tout le reste — au premier chef
  // `language-not-supported`, le paquet dictée FR hors-ligne pas installé — n'est
  // pas une impasse, on bascule alors sur le serveur (Gladia) automatiquement.
  useSpeechRecognitionEvent('error', (e) => {
    if (moteurRef.current !== 'appareil') return;
    const texte = `${finalRef.current} ${interimRef.current}`.trim();
    if (texte) {
      livrer(t.dictee.rienEntendu);
      return;
    }
    // 🔎 On log l'erreur réelle. Avant, un `language-not-supported` (modèle FR
    // hors-ligne absent) était avalé et devenait un « erreur » muet et
    // indébrouillable pour l'enseignante ET pour nous.
    console.warn('[dictee] erreur reconnaissance appareil', e.error, e.message);
    if (e.error === 'not-allowed' || e.error === 'service-not-allowed') {
      arreterMinuteur();
      setEcoute(false);
      setTravail(false);
      moteurRef.current = null;
      setSouci(t.dictee.sansMicro);
      return;
    }
    if (e.error === 'no-speech' || e.error === 'speech-timeout') {
      arreterMinuteur();
      setEcoute(false);
      setTravail(false);
      moteurRef.current = null;
      setSouci(t.dictee.rienEntendu);
      return;
    }
    // L'appareil ne sait pas transcrire (locale FR hors-ligne absente, moteur
    // indisponible…) : on ne laisse pas l'enseignante coincée, on enchaîne sur
    // le repli serveur exactement comme si l'appareil n'avait jamais été retenu.
    basculerVersServeur();
  });

  /**
   * Décide du moteur AVANT d'écouter. La reconnaissance appareil gagne si elle
   * existe et qu'une locale française est disponible ; sinon on retombe sur le
   * serveur.
   *
   * ⚠️ Sur Android 12 et moins, `getSupportedLocales` rend une liste vide : ces
   * appareils passent donc au serveur, ce qui est le bon comportement, la
   * reconnaissance hors-ligne fiable demande Android 13.
   */
  async function choisirMoteur(): Promise<{ locale: string } | null> {
    if (Platform.OS === 'web') return null;
    try {
      if (!ExpoSpeechRecognitionModule.supportsOnDeviceRecognition()) return null;
      const { locales, installedLocales } = await ExpoSpeechRecognitionModule.getSupportedLocales({
        androidRecognitionServicePackage:
          Platform.OS === 'android' ? 'com.google.android.as' : undefined,
      });
      // Les locales installées (hors-ligne) priment quand la liste existe ;
      // sinon on se rabat sur les locales supportées. iOS ne remplit en général
      // pas `installedLocales`, mais y expose bien fr-FR dans `locales`.
      const dispo = (installedLocales.length ? installedLocales : locales).map((l) =>
        l.toLowerCase(),
      );
      const preferees = ['fr-be', 'fr-fr', 'fr-ca', 'fr'];
      const choix = preferees.find((p) => dispo.includes(p)) ?? dispo.find((l) => l.startsWith('fr'));
      return choix ? { locale: choix } : null;
    } catch {
      return null;
    }
  }

  async function demarrer() {
    // 🚨 Un seul démarrage à la fois. `demarrer` est asynchrone et `enCours` ne
    // passe à vrai qu'après `start()` : sans ce garde synchrone, un second tap
    // dans la fenêtre lancerait une deuxième reconnaissance et fuiterait le
    // premier minuteur. Le `finally` le relâche sur TOUS les chemins, y compris
    // les retours anticipés (permission refusée), sinon la dictée resterait
    // bloquée après un premier refus.
    if (demarrantRef.current || moteurRef.current || etat.isRecording) return;
    demarrantRef.current = true;
    try {
      setSouci(null);
      const appareil = await choisirMoteur();

      if (appareil) {
        // Cette permission couvre le micro ET, sur iOS, la reconnaissance vocale.
        const perm = await ExpoSpeechRecognitionModule.requestPermissionsAsync();
        if (!perm.granted) {
          setSouci(t.dictee.sansMicro);
          return;
        }
        finalRef.current = '';
        interimRef.current = '';
        try {
          ExpoSpeechRecognitionModule.start({
            lang: appareil.locale,
            interimResults: true,
            // Continu : une observation tient en deux phrases avec des pauses, on
            // ne veut pas que la première pause coupe la dictée.
            continuous: true,
            // 🔑 Le cœur du hors-ligne : interdit l'envoi de l'audio sur le réseau.
            requiresOnDeviceRecognition: true,
            addsPunctuation: true,
            ...(Platform.OS === 'android'
              ? { androidRecognitionServicePackage: 'com.google.android.as' }
              : {}),
          });
        } catch (e) {
          // Le démarrage embarqué a échoué d'entrée (moteur indisponible, locale
          // non installée…). Plutôt que de rester bloqué, on enchaîne sur le
          // repli serveur : l'enseignante ne voit qu'un micro qui écoute.
          console.warn('[dictee] démarrage appareil échoué, repli serveur', e);
          await demarrerServeur();
          return;
        }
        moteurRef.current = 'appareil';
        setSecondesApp(0);
        setEcoute(true);
        minuteurRef.current = setInterval(() => setSecondesApp((s) => s + 1), 1000);
        return;
      }

      // Repli serveur : l'enregistrement audio d'origine, quand aucun moteur
      // embarqué n'a été retenu (web, appareil trop ancien, locale FR absente).
      await demarrerServeur();
    } finally {
      demarrantRef.current = false;
    }
  }

  async function arreter() {
    // Chemin appareil : on demande la fin, le résultat final arrive par `end`.
    if (moteurRef.current === 'appareil') {
      setTravail(true);
      setSouci(null);
      try {
        ExpoSpeechRecognitionModule.stop();
      } catch {
        // stop() a échoué : le recognizer peut être resté actif. On le coupe de
        // force avant de livrer — sinon le micro resterait ouvert, car le
        // nettoyage d'unmount ne l'abort plus une fois moteurRef remis à null
        // par livrer().
        try {
          ExpoSpeechRecognitionModule.abort();
        } catch {
          // Plus rien à tenter, on quitte de toute façon.
        }
        livrer(t.dictee.erreur);
      }
      return;
    }

    setTravail(true);
    setSouci(null);
    try {
      await enregistreur.stop();
      const uri = enregistreur.uri;
      if (!uri) throw new Error('sans_audio');

      // `fetch` sur une URI locale marche des deux côtés, natif et web, et
      // évite d'embarquer expo-file-system juste pour lire un fichier.
      const blob = await (await fetch(uri)).blob();

      // 🚨 Un enregistrement vide ne part pas. Trouvé à l'essai du 20/08 : quand
      // l'enregistreur échoue à démarrer, le blob fait zéro octet, on envoyait
      // une chaîne vide et le serveur rendait un 400 que l'enseignante lisait
      // comme « la dictée n'a pas abouti ». Un aller-retour pour rien, et un
      // message qui accuse le réseau alors que le micro n'a rien capté.
      //
      // Le seuil n'est pas zéro : un conteneur audio pèse déjà quelques
      // centaines d'octets d'en-têtes sans une seconde de son dedans.
      if (blob.size < 2000) {
        setSouci(t.dictee.rienEntendu);
        return;
      }

      const base64 = await enBase64(blob);

      const texte = await transcrire({
        audio: base64,
        type: blob.type || (Platform.OS === 'web' ? 'audio/webm' : 'audio/m4a'),
      });
      onTexte(texte);
    } catch (e) {
      setSouci(
        e instanceof Error && e.message === 'transcription_vide'
          ? t.dictee.rienEntendu
          : t.dictee.erreur,
      );
    } finally {
      setTravail(false);
    }
  }

  const enCours = ecoute || etat.isRecording;
  const secondes = ecoute ? secondesApp : Math.floor(etat.durationMillis / 1000);
  // Un choc au doigt au moment où l'on lance et où l'on arrête l'écoute : le seul
  // ajout de mouvement à la machine de dictée, qui ne touche ni ses refs ni ses
  // évènements. Plus franc au démarrage (Medium), plus léger à l'arrêt (Light).
  const presser = () => {
    if (enCours) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light).catch(() => {});
      void arreter();
    } else {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium).catch(() => {});
      void demarrer();
    }
  };

  // Le halo respire pendant l'écoute : il enfle et se dégonfle en boucle lente,
  // signe vivant que le micro est ouvert. Il se fige dès qu'on arrête, et ne
  // démarre jamais sous « réduire les animations ».
  const reduire = useReducedMotion();
  const pulse = useSharedValue(1);
  useEffect(() => {
    // Le halo respire aussi pendant la transcription (`travail`), pas seulement
    // pendant l'écoute : c'est justement le moment d'attente qui semblait mort.
    if ((enCours || travail) && !reduire) {
      pulse.value = withRepeat(
        withTiming(1.08, { duration: 900, easing: Easing.inOut(Easing.quad) }),
        -1,
        true,
      );
    } else {
      cancelAnimation(pulse);
      pulse.value = withTiming(1, { duration: motion.duree.rapide });
    }
  }, [enCours, travail, reduire, pulse]);
  const styleHalo = useAnimatedStyle(() => ({ transform: [{ scale: pulse.value }] }));

  if (hero) {
    return (
      <View style={styles.heroBloc}>
        {/* Halo : un anneau teinté derrière le bouton, comme le témoin. Il
            respire pendant l'écoute. */}
        <Animated.View style={[styles.halo, (enCours || travail) && styles.haloActif, styleHalo]}>
          <Pressable
            accessibilityRole="button"
            accessibilityLabel={enCours ? t.dictee.arreter : t.dictee.parler}
            disabled={inactif || travail}
            onPress={presser}
            style={({ pressed }) => pressed && styles.presse}>
            <LinearGradient
              colors={c.action}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 1 }}
              style={styles.heroBouton}>
              {/* Pendant la transcription, un vrai spinner tourne : avant, l'icône
                  « loader » était figée et l'écran semblait planté (retour Valentin
                  24/08). On écoute (mic), on arrête (square), on patiente (spinner). */}
              {travail ? (
                <ActivityIndicator color={c.surface} size="large" />
              ) : (
                <Feather name={enCours ? 'square' : 'mic'} size={44} color={c.surface} />
              )}
            </LinearGradient>
          </Pressable>
        </Animated.View>
        <Text style={styles.heroIndice}>
          {travail
            ? t.dictee.enCours
            : enCours
              ? t.dictee.arreterAvec(secondes)
              : t.capter.dicterIndice}
        </Text>
        {souci ? <Text style={styles.souci}>{souci}</Text> : null}
      </View>
    );
  }

  return (
    <View style={styles.bloc}>
      <Pressable
        accessibilityRole="button"
        accessibilityLabel={enCours ? t.dictee.arreter : t.dictee.parler}
        disabled={inactif || travail}
        onPress={presser}
        style={[styles.bouton, enCours && styles.boutonActif]}>
        {travail ? (
          <ActivityIndicator color={c.encre} />
        ) : (
          <Feather name={enCours ? 'square' : 'mic'} size={18} color={enCours ? c.surface : c.encre} />
        )}
        <Text style={[styles.libelle, enCours && styles.libelleActif]}>
          {travail ? t.dictee.enCours : enCours ? t.dictee.arreterAvec(secondes) : t.dictee.parler}
        </Text>
      </Pressable>
      {souci ? <Text style={styles.souci}>{souci}</Text> : null}
    </View>
  );
}

/** Un blob en base64 sans préfixe, des deux côtés. */
function enBase64(blob: Blob): Promise<string> {
  return new Promise((resoudre, rejeter) => {
    const lecteur = new FileReader();
    lecteur.onerror = () => rejeter(new Error('lecture_impossible'));
    lecteur.onloadend = () => {
      const brut = String(lecteur.result ?? '');
      // `data:audio/m4a;base64,XXXX` : on ne garde que la queue.
      resoudre(brut.slice(brut.indexOf(',') + 1));
    };
    lecteur.readAsDataURL(blob);
  });
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  bloc: { gap: espace.xs },
  heroBloc: { alignItems: 'center', gap: espace.md, paddingVertical: espace.sm },
  halo: {
    borderRadius: 999,
    padding: 12,
    backgroundColor: c.actionTeinte,
  },
  haloActif: { backgroundColor: c.teinte.recreation },
  heroBouton: {
    width: 132,
    height: 132,
    borderRadius: 66,
    alignItems: 'center',
    justifyContent: 'center',
    shadowColor: c.action[1],
    shadowOpacity: 0.34,
    shadowRadius: 24,
    shadowOffset: { width: 0, height: 14 },
    elevation: 10,
  },
  presse: { opacity: 0.9, transform: [{ scale: 0.98 }] },
  heroIndice: {
    fontFamily: police.corps,
    fontSize: 14,
    color: c.encreDouce,
    textAlign: 'center',
    lineHeight: 20,
  },
  bouton: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: espace.sm,
    paddingVertical: espace.sm,
    paddingHorizontal: espace.md,
    borderRadius: rayon.bloc,
    borderWidth: 1,
    borderColor: c.bord,
  },
  boutonActif: { backgroundColor: c.moment.recreation, borderColor: c.moment.recreation },
  libelle: { fontFamily: police.accent, fontSize: 15, color: c.encre },
  libelleActif: { color: c.surface },
  souci: { fontFamily: police.corps, fontSize: 14, color: c.encreDouce },
});
