/**
 * Les libellés de la clôture d'une SÉQUENCE multi-étapes, en local
 * (`{ fr, nl }[langue]`) : la feature est neuve, on ne touche pas aux catalogues
 * `src/i18n/*`.
 */
const CLOT = {
  fr: {
    etapeSuivante: 'Étape suivante',
    cloturerLecon: 'Clôturer la leçon',
    suiteTitre: 'Quand fais-tu la suite ?',
    suiteAide: (titre: string) => `Prochaine étape : ${titre}. Choisis quand la poser.`,
    quand: 'Quand ?',
    creneau: 'Sur quel créneau ?',
    sansCreneau: 'Sans créneau',
    planifier: 'Planifier la suite',
    retour: 'Retour',
  },
  nl: {
    etapeSuivante: 'Volgende stap',
    cloturerLecon: 'De les afsluiten',
    suiteTitre: 'Wanneer doe je het vervolg?',
    suiteAide: (titre: string) => `Volgende stap: ${titre}. Kies wanneer je die plaatst.`,
    quand: 'Wanneer?',
    creneau: 'Op welk tijdslot?',
    sansCreneau: 'Zonder tijdslot',
    planifier: 'Het vervolg plannen',
    retour: 'Terug',
  },
}[langue];

/** Sentinelle « sans créneau » du mini-sélecteur (jamais un id de créneau réel). */
const SANS_CRENEAU = 'sans';

/** Les prochains jours de classe (lundi→vendredi), aujourd'hui compris. */
function joursSuite(combien: number): string[] {
  const jours: string[] = [];
  for (let i = 0; jours.length < combien && i < combien + 7; i++) {
    const d = new Date();
    d.setHours(12, 0, 0, 0);
    d.setDate(d.getDate() + i);
    const dow = d.getDay();
    if (dow >= 1 && dow <= 5) {
      jours.push(
        `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`,
      );
    }
  }
  return jours;
}

/** « Lun 9 » : jour court + numéro, pour une pastille de date compacte. */
function dateCourte(iso: string): string {
  const [a, m, j] = iso.split('-').map((n) => parseInt(n, 10));
  const d = new Date(a, m - 1, j);
  const jj = d.toLocaleDateString(localeDate(), { weekday: 'short' }).replace('.', '');
  return `${jj.charAt(0).toLocaleUpperCase('fr')}${jj.slice(1)} ${j}`;
}

/**
 * Clôturer une séance. C'est le seul geste de l'app qui écrit un jugement dans
 * le dossier d'un enfant, et il se fait en deux étapes, dans cet ordre.
 *
 * ÉTAPE 1, COMMENT TU ÉVALUES. Elle existait déjà dans l'app web, au bon
 * endroit, avant le jugement. Posée avant, elle change le jugement ; posée
 * après, elle ne fait que le justifier. C'est toute la différence entre un
 * outil pédagogique et un outil administratif, et c'est le père
 * d'Anne-Charlotte qui l'avait demandée : « parfois l'enseignant ne sait même
 * pas comment il va évaluer ».
 *
 * Ce qui change ici, c'est le format. Le champ libre hérité a produit 19
 * réponses réelles : 13 répondent à la question, et 12 de ces 13 disent
 * « observation », dont trois avec une faute de frappe. Le reste répond à côté,
 * jusqu'à « kjn ». Un champ libre fait retaper le même mot des dizaines de fois
 * pour une donnée inexploitable. Des choix nommés posent la même question en
 * deux secondes, et le champ « précise » reste là pour qui veut nuancer.
 *
 * ÉTAPE 2, ÉLÈVE PAR ÉLÈVE. « Hortense et Jean l'ont acquis, par contre Lily,
 * Lola et César pas du tout. »
 *
 * 🔑 Rien n'est coché d'avance, mais « tous acquis » est à un tap. L'app web
 * pré-remplissait tout en `acquired`, ce qui enregistre un jugement que personne
 * n'a posé. Le cas courant doit rester à un geste, pas devenir un défaut.
 *
 * 🔑 Un absent n'est pas jugé, et n'est surtout pas noté « non acquis ». Non
 * évaluée n'est pas non acquise.
 */

/**
 * Les trois états, dans l'ordre du plus fréquent au moins fréquent.
 *
 * La couleur suit celle de l'accueil : vert pour ce qui est fait, jaune pour ce
 * qui résiste, encre neutre pour ce qui n'est pas commencé. Aucun rouge, ici
 * moins qu'ailleurs : on informe sur un enfant de cinq ans, on ne le punit pas.
 */
const NIVEAUX: { cle: NiveauMaitrise; teinte: string }[] = [
  { cle: 'acquired', teinte: color.moment.recreation },
  { cle: 'in_progress', teinte: color.moment.ateliers },
  { cle: 'not_started', teinte: color.encre },
];

export default function Cloturer() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { id } = useLocalSearchParams<{ id: string }>();
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;
  const moi = useMoi();

  // Trois phases : 1 « comment tu évalues », 2 « niveaux par élève », et — pour
  // une SÉQUENCE dont il reste des étapes — 3 « quand fais-tu la suite ? ».
  const [etape, setEtape] = useState<1 | 2 | 3>(1);
  // Le mini-sélecteur de la suite (phase 3) : la date et, si on veut, le créneau.
  const [suiteDate, setSuiteDate] = useState<string | null>(null);
  const [suiteCreneau, setSuiteCreneau] = useState<string | null>(null);
  // 🚨 Pas de modalité par défaut, et c'est délibéré même si les données
  // poussaient à l'inverse : sur les 13 réponses exploitables déjà en base, 12
  // disent « observation ». Présélectionner ferait donc gagner un tap dans
  // presque tous les cas. Mais c'est le seul endroit du produit où l'app fait
  // RÉFLÉCHIR au lieu d'enregistrer, et une réponse déjà cochée se franchit
  // sans être lue. Le tap qu'on économiserait est précisément celui qui compte.
  const [modalite, setModalite] = useState<Modalite | null>(null);
  const [precision, setPrecision] = useState('');
  const [niveaux, setNiveaux] = useState<Record<string, NiveauMaitrise>>({});
  const [absents, setAbsents] = useState<string[]>([]);
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);

  // Les photos « preuve » sont un à-côté de la clôture : jointes tout de suite
  // (l'activité existe déjà, on est en train de la clôturer), rechargées à la
  // volée, et surtout elles ne bloquent jamais l'enregistrement des constats.
  const [photoOccupe, setPhotoOccupe] = useState(false);
  const [photoErreur, setPhotoErreur] = useState<string | null>(null);
  const medias = useRequete(() => listerMediasActivite(id), [id]);
  const photos = medias.donnees ?? [];
  const photoPleine = photos.length >= 2;

  async function ajouterPhoto(prendre: boolean) {
    if (photoOccupe) return;
    setPhotoErreur(null);
    try {
      const image = prendre ? await prendrePhoto() : await choisirPhoto();
      if (!image) return;
      setPhotoOccupe(true);
      await joindrePhotoActivite(id, image);
      medias.recharger();
    } catch (e) {
      setPhotoErreur(e instanceof Error ? e.message : t.cloture.erreur);
    } finally {
      setPhotoOccupe(false);
    }
  }

  async function enleverPhoto(media: ActivityMedia) {
    if (photoOccupe) return;
    setPhotoErreur(null);
    setPhotoOccupe(true);
    try {
      await retirerMediaActivite(media);
      medias.recharger();
    } catch (e) {
      setPhotoErreur(e instanceof Error ? e.message : t.cloture.erreur);
    } finally {
      setPhotoOccupe(false);
    }
  }

  const activite = useRequete(() => detailActivite(id), [id]);
  const eleves = useRequete(() => elevesDe(classeId!), [classeId], { actif: !!classeId });
  // Les étapes de la séquence (si c'en est une) : sert à décider « étape suivante »
  // vs « clôturer la leçon », et à réarmer la bonne étape.
  const etapes = useRequete(() => etapesDe(id), [id]);
  // Les créneaux de la classe, pour le mini-sélecteur de la suite (phase 3).
  const creneaux = useRequete(() => creneauxDe(classeId!), [classeId], { actif: !!classeId });

  const detail = activite.donnees;
  const liste = eleves.donnees ?? [];

  // La séquence, si l'activité clôturée en fait partie. `prochaine` = la première
  // étape NON faite autre que la courante (de préférence après elle, sinon un trou
  // plus haut) : sa présence dit qu'il RESTE des étapes.
  const sequence = useMemo(() => etapes.donnees ?? [], [etapes.donnees]);
  const estSequence = sequence.length > 1;
  const prochaine = useMemo<EtapeSequence | null>(() => {
    if (!estSequence) return null;
    const courante = sequence.find((e) => e.id === id);
    const ordre = courante?.ordre ?? 0;
    const restantes = sequence.filter((e) => e.id !== id && e.statut !== 'completed');
    if (!restantes.length) return null;
    const apres = restantes.filter((e) => e.ordre > ordre).sort((a, b) => a.ordre - b.ordre);
    const avant = restantes.filter((e) => e.ordre <= ordre).sort((a, b) => a.ordre - b.ordre);
    return apres[0] ?? avant[0] ?? null;
  }, [sequence, id, estSequence]);
  const ilResteDesEtapes = !!prochaine;

  // Les créneaux du jour choisi pour la suite (par jour ISO), pour proposer où la
  // poser. Sans date choisie, on n'affiche pas encore de créneau.
  const creneauxSuite = useMemo(() => {
    if (!suiteDate) return [];
    const dow = jourDeISO(suiteDate);
    return (creneaux.donnees ?? [])
      .filter((cr) => cr.jour === dow)
      .sort((a, b) => a.debut.localeCompare(b.debut));
  }, [creneaux.donnees, suiteDate]);

  // Les absences déjà connues pour ce jour pré-marquent les absents. La table
  // est vide en base aujourd'hui, mais la lire ne coûte rien et évite de faire
  // juger un enfant dont l'absence était déjà notée.
  const absencesConnues = useRequete(
    () => absencesDu({ date: detail!.date!, elevesIds: liste.map((e) => e.id) }),
    [detail?.date, liste.length],
    { actif: !!detail?.date && liste.length > 0 },
  );

  const preAbsents = absencesConnues.donnees;
  const estAbsent = (eleveId: string) =>
    absents.includes(eleveId) || (!!preAbsents?.has(eleveId) && !niveaux[eleveId]);

  const presents = liste.filter((e) => !estAbsent(e.id));
  const restants = presents.filter((e) => !niveaux[e.id]).length;

  const aRegler = useMemo(
    () =>
      Object.fromEntries(
        presents.filter((e) => niveaux[e.id]).map((e) => [e.id, niveaux[e.id]]),
      ) as Record<string, NiveauMaitrise>,
    [presents, niveaux],
  );

  function situer(eleveId: string, niveau: NiveauMaitrise) {
    setAbsents((l) => l.filter((x) => x !== eleveId));
    setNiveaux((n) => ({ ...n, [eleveId]: niveau }));
  }

  function marquerAbsent(eleveId: string) {
    setNiveaux((n) => {
      const suite = { ...n };
      delete suite[eleveId];
      return suite;
    });
    setAbsents((l) => (l.includes(eleveId) ? l.filter((x) => x !== eleveId) : [...l, eleveId]));
  }

  function tousAcquis() {
    setNiveaux((n) => {
      const suite = { ...n };
      for (const e of presents) suite[e.id] = 'acquired';
      return suite;
    });
  }

  /**
   * Le geste de clôture, en deux temps STRICTS.
   *
   * 1. On écrit les constats (`cloturerActivite`). C'est la seule partie sacrée :
   *    si elle échoue, on remonte l'erreur et on laisse l'écran tel quel pour
   *    réessayer, SANS rien tenter d'autre.
   * 2. Une fois les constats écrits, on ne rejoue JAMAIS la clôture (ce serait des
   *    constats en double). Tout le reste — `apres` (réarmer/arrêter la séquence)
   *    et les célébrations — est best-effort : une erreur y est avalée, on navigue
   *    quand même vers la fiche.
   */
  async function conclure(apres?: () => Promise<void>) {
    if (!detail || !classe || !modalite) return;
    setErreur(null);
    setOccupe(true);
    try {
      await cloturerActivite({
        activiteId: detail.id,
        anneeScolaire: classe.anneeScolaire,
        modalite,
        precision,
        niveaux: aRegler,
      });
    } catch (e) {
      // Les constats ont échoué : rien d'autre n'a été tenté, on peut réessayer.
      setErreur(e instanceof Error ? e.message : t.cloture.erreur);
      setOccupe(false);
      return;
    }

    // Constats écrits. Le réarmement / l'arrêt de la séquence est important mais
    // recouvrable (l'étape reste « à replanifier ») : on ne bloque pas dessus, et
    // surtout on ne rejoue pas la clôture.
    try {
      if (apres) await apres();
    } catch {
      // Silencieux : la clôture a réussi, seule la suite n'a pas pu être posée.
    }

    // Les célébrations sont un BONUS, jamais un risque pour la donnée. Deux fêtes
    // possibles, jamais empilées : priorité au palier de trophée, plus rare et
    // plus marquant qu'une semaine bouclée.
    try {
      router.replace({ pathname: '/activite/[id]', params: { id: detail.id } });
      if (await celebrerSiPalierTrophee()) return;
      if (classeId && moi) {
        const fete = await celebrerSiSemaineBouclee({
          classeId,
          userId: moi,
          dateSeance: detail.date,
        });
        if (fete) {
          router.push({
            pathname: '/celebration',
            params: {
              observations: String(fete.observations),
              points: String(fete.points),
              semaines: String(fete.semaines),
              collegues: String(fete.collegues),
              moments: String(fete.moments),
            },
          });
        }
      }
      return;
    } catch {
      // Rien : la clôture a réussi, seule la fête a manqué.
    }
    router.replace({ pathname: '/activite/[id]', params: { id: detail.id } });
  }

  // Clôture simple : mono-étape, ou dernière étape d'une séquence (rien à réarmer).
  const valider = () => conclure();

  // « Clôturer la leçon » sur une séquence qu'on arrête plus tôt : les étapes
  // restantes repassent `unplanned` + `deferred_at` (réutilisables, décision Q2).
  const cloturerLecon = () => conclure(async () => {
    if (detail) await arreterSequence(detail.id);
  });

  // « Étape suivante » : on réarme la prochaine étape non faite sur la date (et le
  // créneau) choisis — exactement la machinerie de replanification.
  const planifierSuite = () =>
    conclure(async () => {
      if (prochaine && suiteDate) {
        await replanifierActivite({
          activiteId: prochaine.id,
          date: suiteDate,
          creneauId: suiteCreneau,
        });
      }
    });

  return (
    <SousEcran
      titre={t.cloture.titre}
      sousTitre={etape === 3 ? CLOT.suiteTitre : t.cloture.etape(etape)}
      chargement={activite.chargement}
      // Le retour remonte d'une étape avant de sortir : quitter la clôture
      // depuis l'étape 2 ferait perdre les niveaux déjà posés. Depuis la phase 3
      // (mini-planif de la suite), on redescend sur les niveaux.
      auRetour={() =>
        etape === 3 ? setEtape(2) : etape === 2 ? setEtape(1) : router.back()
      }>
      {!detail ? (
        <Carte>
          <Text style={texte.discret}>{t.activite.introuvable}</Text>
        </Carte>
      ) : (
        <>
          <Carte>
            <Text style={texte.section}>{detail.titre}</Text>
            {detail.attendus.length === 0 ? (
              <Text style={styles.aide}>{t.cloture.sansAttendu}</Text>
            ) : (
              detail.attendus.map((a) => <LigneAttendu key={a.id} attendu={a} />)
            )}
            {detail.attendus.length === 0 ? (
              <BoutonDiscret
                libelle={t.cloture.ajouterAttendu}
                onPress={() =>
                  router.replace({ pathname: '/activite/[id]', params: { id: detail.id } })
                }
              />
            ) : null}
          </Carte>

          {etape === 1 ? (
            <>
              <Carte>
                <Text style={texte.section}>{t.cloture.commentTitre}</Text>
                <Text style={styles.aide}>{t.cloture.commentAide}</Text>
                <Pastilles
                  options={MODALITES_EVALUATION.map((m) => ({
                    id: m,
                    libelle: t.cloture.modalites[m],
                  }))}
                  choisi={modalite}
                  onChoisir={(v) => setModalite((v as Modalite) ?? null)}
                />
                <Champ
                  etiquette={t.cloture.precision}
                  value={precision}
                  onChangeText={setPrecision}
                  placeholder={t.cloture.precisionIndice}
                  editable={!occupe}
                />
              </Carte>
              <BoutonPrincipal
                libelle={t.cloture.suivant}
                onPress={() => setEtape(2)}
                inactif={!modalite}
              />
            </>
          ) : etape === 3 ? (
            // Phase 3 : « Quand fais-tu la suite ? ». N'apparaît que via « Étape
            // suivante », donc `prochaine` existe. On clôture l'étape courante ET on
            // réarme la prochaine sur la date/le créneau choisis, en un geste.
            <>
              <Carte>
                <Text style={texte.section}>{CLOT.suiteTitre}</Text>
                {prochaine ? (
                  <Text style={styles.aide}>{CLOT.suiteAide(prochaine.titre)}</Text>
                ) : null}
                <Pastilles
                  etiquette={CLOT.quand}
                  options={joursSuite(8).map((d) => ({ id: d, libelle: dateCourte(d) }))}
                  choisi={suiteDate}
                  onChoisir={(v) => {
                    setSuiteDate(v);
                    setSuiteCreneau(null);
                  }}
                />
                {suiteDate && creneauxSuite.length ? (
                  <Pastilles
                    etiquette={CLOT.creneau}
                    options={[
                      ...creneauxSuite.map((cr) => ({
                        id: cr.id,
                        libelle: `${cr.debut} ${cr.libelle}`.trim(),
                      })),
                      { id: SANS_CRENEAU, libelle: CLOT.sansCreneau },
                    ]}
                    choisi={suiteCreneau ?? SANS_CRENEAU}
                    onChoisir={(v) => setSuiteCreneau(v && v !== SANS_CRENEAU ? v : null)}
                  />
                ) : null}
              </Carte>
              {erreur ? <Alerte message={erreur} /> : null}
              <BoutonPrincipal
                libelle={CLOT.planifier}
                onPress={planifierSuite}
                occupe={occupe}
                inactif={!suiteDate}
              />
              <BoutonDiscret libelle={CLOT.retour} onPress={() => setEtape(2)} />
            </>
          ) : (
            <>
              <Carte>
                <Text style={texte.section}>{t.cloture.niveauxTitre}</Text>
                <Text style={styles.aide}>{t.cloture.niveauxAide}</Text>
                {liste.length === 0 ? (
                  <Text style={styles.aide}>{t.cloture.sansEleve}</Text>
                ) : null}
                {liste.length > 1 ? (
                  <BoutonDiscret libelle={t.cloture.tousAcquis} onPress={tousAcquis} />
                ) : null}
              </Carte>

              {liste.map((e) => {
                const absent = estAbsent(e.id);
                const niveau = niveaux[e.id];
                return (
                  <Carte key={e.id} compacte>
                    <Text style={absent ? styles.nomAbsent : texte.corps}>{nomAffiche(e)}</Text>
                    <View style={styles.rangee}>
                      {NIVEAUX.map(({ cle, teinte }) => {
                        const actif = !absent && niveau === cle;
                        return (
                          <Pressable
                            key={cle}
                            accessibilityRole="button"
                            accessibilityState={{ selected: actif }}
                            accessibilityLabel={`${nomAffiche(e)}, ${niveauxMaitrise[cle]}`}
                            onPress={() => situer(e.id, cle)}
                            style={[
                              styles.choix,
                              actif && { backgroundColor: teinte, borderColor: teinte },
                              actif && ombre.carte,
                            ]}>
                            <Text style={[styles.texteChoix, actif && styles.texteChoixActif]}>
                              {niveauxMaitrise[cle]}
                            </Text>
                          </Pressable>
                        );
                      })}
                      <Pressable
                        accessibilityRole="button"
                        accessibilityState={{ selected: absent }}
                        accessibilityLabel={`${nomAffiche(e)}, ${t.cloture.absent}`}
                        onPress={() => marquerAbsent(e.id)}
                        style={[styles.choix, absent && styles.choixAbsent]}>
                        <Text style={[styles.texteChoix, absent && styles.texteChoixActif]}>
                          {t.cloture.absent}
                        </Text>
                      </Pressable>
                    </View>
                  </Carte>
                );
              })}

              <Carte>
                <Text style={texte.section}>{t.cloture.photos}</Text>
                <Text style={styles.aide}>{t.cloture.photosAide}</Text>

                {photos.length > 0 ? (
                  <View style={styles.photoRangee}>
                    {photos.map((photo) => (
                      <View key={photo.id} style={styles.photoTuile}>
                        <Image
                          source={{ uri: photo.url }}
                          style={styles.photoImage}
                          contentFit="cover"
                        />
                        <Presse
                          accessibilityRole="button"
                          accessibilityLabel={t.cloture.photoRetirer}
                          onPress={() => enleverPhoto(photo)}
                          style={styles.photoCroix}>
                          <Feather name="x" size={16} color="#FFFFFF" />
                        </Presse>
                      </View>
                    ))}
                  </View>
                ) : null}

                {photoPleine ? (
                  <Text style={styles.aide}>{t.cloture.photoMax}</Text>
                ) : (
                  <>
                    <BoutonDiscret
                      libelle={t.cloture.photoPrendre}
                      onPress={() => ajouterPhoto(true)}
                    />
                    <BoutonDiscret
                      libelle={t.cloture.photoGalerie}
                      onPress={() => ajouterPhoto(false)}
                    />
                  </>
                )}

                {photoErreur ? <Alerte message={photoErreur} /> : null}
              </Carte>

              {erreur ? <Alerte message={erreur} /> : null}
              {restants > 0 ? (
                <Text style={styles.compte}>{t.cloture.reste(restants)}</Text>
              ) : null}

              {estSequence && ilResteDesEtapes ? (
                // Séquence dont il RESTE des étapes : deux chemins. « Étape suivante »
                // (défaut, dégradé) clôture l'étape courante puis va planifier la
                // suite ; « Clôturer la leçon » (cadre) arrête la séquence, les
                // étapes restantes repassant « à replanifier » (Q2).
                <>
                  <BoutonPrincipal
                    libelle={CLOT.etapeSuivante}
                    onPress={() => setEtape(3)}
                    inactif={!classe || occupe}
                  />
                  <BoutonSecondaire
                    libelle={CLOT.cloturerLecon}
                    onPress={cloturerLecon}
                    occupe={occupe}
                  />
                </>
              ) : (
                <BoutonPrincipal
                  libelle={t.cloture.valider}
                  onPress={valider}
                  occupe={occupe}
                  // On n'exige pas d'avoir situé tout le monde : une classe de
                  // vingt-cinq dont deux sont partis plus tôt ne doit pas
                  // bloquer la clôture. Mais on le dit, plutôt que de laisser
                  // croire que c'est complet.
                  inactif={!classe}
                />
              )}
            </>
          )}
        </>
      )}
    </SousEcran>
  );
}

