import AsyncStorage from '@react-native-async-storage/async-storage';
import * as Notifications from 'expo-notifications';
import { Platform } from 'react-native';

import { t } from '@/i18n';

/**
 * Le rituel du soir : un moment choisi pour ranger sa journée avec Cloudy.
 *
 * 🔑 Le rappel n'est plus « chaque soir » en bloc : c'est une SEMAINE de sept
 * jours, chacun avec son interrupteur et son heure. La classe ne tourne pas le
 * week-end, donc le défaut est lundi→vendredi à 16:30, samedi et dimanche
 * éteints. L'enseignant·e ajuste jour par jour depuis l'écran des notifications.
 *
 * 🔑 Deux couches, à ne pas confondre :
 *   1. l'INTENTION (quels jours, à quelle heure) : c'est ce que l'écran montre,
 *      ce qu'on sème par défaut, et ce que la future « série » lira comme les
 *      jours de travail de l'enseignant·e, indépendamment de toute permission ;
 *   2. la RÉALITÉ (un rappel réellement programmé sur l'appareil) : elle dépend
 *      de l'autorisation système. Sans elle, l'intention reste posée mais rien
 *      ne sonne, et l'écran le dit sans détour.
 *
 * 🔑 Un seul réveil par jour actif, jamais deux. On repart toujours d'une table
 * rase : on annule NOS rappels avant d'en reposer, en gardant leurs identifiants
 * sur le disque pour ne toucher qu'aux nôtres.
 *
 * Ce module reste INDÉPENDANT des « rappels pour ranger » de `notifications.tsx`
 * (l'ancien planificateur « observations »), qui n'est plus piloté par aucun écran.
 */

/** La clé du réglage sur le disque. On garde aussi les `id` planifiés, pour annuler proprement NOS rappels et pas un autre. */
const CLE = 'educooo.rituel';

/** Le même canal Android que les autres rappels de l'app. Ignoré sur iOS. */
const CANAL = 'default';

/** Les heures proposées d'un tap, plus « personnalisé » pour le reste. Fin de journée, quand on repense à sa classe. */
export const HEURES_PROPOSEES = ['16:30', '17:00', '18:00', '19:00'] as const;

/** L'heure par défaut d'un jour actif : la fin d'après-midi, après la classe. */
export const HEURE_DEFAUT = '16:30';

/** Les sept jours, 0 = lundi … 6 = dimanche. Même convention que `semaine.jours` (i18n) et la norme ISO. */
export const JOURS = [0, 1, 2, 3, 4, 5, 6] as const;

/** Un jour du rituel, tel que l'écran le lit et l'écrit. `actif` = l'enseignant·e veut un rappel ce jour-là. */
export type JourRituel = { jour: number; actif: boolean; heure: string };

/** La semaine complète, sept entrées, toujours dans l'ordre lundi→dimanche. */
export type SemaineRituel = JourRituel[];

/** Ce qu'on garde sur le disque : chaque jour, plus l'identifiant du rappel planifié (détail interne d'annulation). */
type JourStocke = JourRituel & { id: string | null };

/** La graine par défaut : lundi→vendredi allumés à 16:30, samedi et dimanche éteints. */
function semaineDefaut(): JourStocke[] {
  return JOURS.map((jour) => ({
    jour,
    actif: jour <= 4,
    heure: HEURE_DEFAUT,
    id: null,
  }));
}

/** Découpe une heure 'HH:mm' en nombres, ou null si le format ne colle pas. */
function decouperHeure(heure: string): { hour: number; minute: number } | null {
  const m = /^(\d{1,2}):(\d{2})$/.exec(heure.trim());
  if (!m) return null;
  const hour = Number(m[1]);
  const minute = Number(m[2]);
  if (hour < 0 || hour > 23 || minute < 0 || minute > 59) return null;
  return { hour, minute };
}

/**
 * Remet une liste de jours d'aplomb : exactement sept entrées (lundi→dimanche),
 * une seule par jour, une heure valide sinon le défaut. On accepte une liste
 * partielle ou désordonnée et on la range, pour ne jamais casser sur une donnée
 * bancale venue du disque ou de l'écran.
 */
function normaliser(entrees: Partial<JourRituel>[]): JourStocke[] {
  const parJour = new Map<number, Partial<JourRituel>>();
  for (const e of entrees) {
    if (typeof e?.jour === 'number' && e.jour >= 0 && e.jour <= 6) parJour.set(e.jour, e);
  }
  return JOURS.map((jour) => {
    const e = parJour.get(jour);
    const heure = typeof e?.heure === 'string' && decouperHeure(e.heure) ? e.heure : HEURE_DEFAUT;
    return { jour, actif: !!e?.actif, heure, id: null };
  });
}

/**
 * Lit l'état sur le disque, en tolérant l'absence, la casse et l'ancien format.
 *
 * Migration : l'ancien réglage était un rappel unique `{ actif, heure, id }`. On
 * sème la semaine par défaut et, si ce rappel était actif, on reporte son heure
 * sur les jours ouvrés pour ne pas perdre le choix. On annule au passage l'ancien
 * rappel quotidien s'il traîne encore, pour ne pas laisser deux réveils.
 */
async function lireStocke(): Promise<JourStocke[]> {
  try {
    const brut = await AsyncStorage.getItem(CLE);
    if (!brut) return semaineDefaut();
    const parse = JSON.parse(brut) as unknown;

    // Nouveau format : { semaine: JourStocke[] }.
    if (parse && typeof parse === 'object' && Array.isArray((parse as { semaine?: unknown }).semaine)) {
      const semaine = (parse as { semaine: Partial<JourStocke>[] }).semaine;
      const normalise = normaliser(semaine);
      // On récupère les identifiants planifiés, seul détail que `normaliser` ne
      // porte pas (il ne connaît que l'intention).
      return normalise.map((j) => {
        const source = semaine.find((s) => s?.jour === j.jour);
        return { ...j, id: typeof source?.id === 'string' ? source.id : null };
      });
    }

    // Ancien format monolithique : { actif, heure, id }.
    if (parse && typeof parse === 'object' && ('actif' in parse || 'heure' in parse)) {
      const ancien = parse as { actif?: unknown; heure?: unknown; id?: unknown };
      if (typeof ancien.id === 'string') void annuler(ancien.id);
      const base = semaineDefaut();
      if (ancien.actif && typeof ancien.heure === 'string' && decouperHeure(ancien.heure)) {
        for (const j of base) if (j.jour <= 4) j.heure = ancien.heure;
      }
      return base;
    }

    return semaineDefaut();
  } catch {
    // Un JSON corrompu ne doit pas casser l'écran : on repart d'un réglage par défaut.
    return semaineDefaut();
  }
}

async function ecrireStocke(semaine: JourStocke[]): Promise<void> {
  await AsyncStorage.setItem(CLE, JSON.stringify({ semaine }));
}

/** La semaine courante (intention), pour l'écran des notifications. Toujours sept entrées, lundi→dimanche. */
export async function lireSemaineRituel(): Promise<SemaineRituel> {
  const s = await lireStocke();
  return s.map(({ jour, actif, heure }) => ({ jour, actif, heure }));
}

/**
 * Les jours où un rappel est voulu, 0 = lundi … 6 = dimanche, triés.
 *
 * 🔑 Le point d'entrée de la future « série » : ce sont les jours de travail de
 * l'enseignant·e. On rend l'INTENTION, pas la réalité système : la série compte
 * les jours choisis, qu'une permission de notification soit accordée ou non.
 */
export async function joursActifs(): Promise<number[]> {
  const s = await lireStocke();
  return s.filter((j) => j.actif).map((j) => j.jour).sort((a, b) => a - b);
}

/** Traduit la permission système dans le vocabulaire de l'app. */
function traduire(
  reponse: Notifications.NotificationPermissionsStatus,
): 'accordee' | 'refusee' | 'indeterminee' {
  if (reponse.granted) return 'accordee';
  if (reponse.status === 'undetermined') return 'indeterminee';
  return 'refusee';
}

/** L'état d'autorisation courant, sans rien demander. Pour afficher la vérité au chargement. */
export async function permissionRituel(): Promise<'accordee' | 'refusee' | 'indeterminee'> {
  try {
    return traduire(await Notifications.getPermissionsAsync());
  } catch {
    return 'indeterminee';
  }
}

/**
 * Demande l'autorisation, au moment où l'enseignant·e ACTIVE un rappel et pas
 * avant. Crée aussi le canal Android quand c'est accordé, sans quoi un rappel n'y
 * aurait ni son ni importance. Renvoie vrai si on a le droit de notifier.
 */
export async function demanderPermissionRituel(): Promise<boolean> {
  const reponse = await Notifications.requestPermissionsAsync();
  const ok = reponse.granted;
  if (ok && Platform.OS === 'android') {
    await Notifications.setNotificationChannelAsync(CANAL, {
      name: 'Rappels EducooO',
      importance: Notifications.AndroidImportance.DEFAULT,
    });
  }
  return ok;
}

/**
 * Convertit notre index de jour (0 = lundi … 6 = dimanche) vers la convention
 * d'expo-notifications, où le déclencheur hebdomadaire attend 1 = dimanche …
 * 7 = samedi. Lundi → 2, samedi → 7, dimanche → 1.
 */
function jourExpo(jour: number): number {
  return ((jour + 1) % 7) + 1;
}

/** Programme le rappel HEBDOMADAIRE d'un jour à son heure, et rend son identifiant (ou null si l'heure est bancale ou si la planification échoue). */
async function programmerJour(jour: number, heure: string): Promise<string | null> {
  const d = decouperHeure(heure);
  if (!d) return null;
  try {
    return await Notifications.scheduleNotificationAsync({
      content: {
        title: t.rituel.notifTitre,
        body: t.rituel.notifCorps,
        // Le tap sur ce rappel ouvre le rituel : c'est `notifications.tsx` qui
        // route sur ce `type`. Sans lui, le rappel n'aurait nulle part où mener.
        data: { type: 'rituel' },
      },
      // Le déclencheur WEEKLY sonne chaque semaine au jour et à l'heure donnés,
      // et se répète tout seul. Un rappel par jour actif, donc jusqu'à sept.
      trigger: {
        type: Notifications.SchedulableTriggerInputTypes.WEEKLY,
        weekday: jourExpo(jour),
        hour: d.hour,
        minute: d.minute,
        channelId: CANAL,
      },
    });
  } catch {
    // Sans autorisation (ou sur un déclencheur refusé par le système), on ne
    // programme rien : l'intention reste posée, mais aucun réveil n'est promis.
    return null;
  }
}

/** Annule NOTRE rappel s'il existe, en tolérant un identifiant déjà expiré. */
async function annuler(id: string | null): Promise<void> {
  if (!id) return;
  await Notifications.cancelScheduledNotificationAsync(id).catch(() => {
    // Un identifiant inconnu ou déjà passé n'est pas une erreur à propager.
  });
}

/**
 * Pose une semaine entière : on persiste l'intention ET on (re)programme un
 * rappel hebdomadaire pour chaque jour actif. On repart toujours d'une table
 * rase (annulation de tous NOS rappels précédents) pour ne jamais empiler.
 *
 * ⚠️ Suppose l'autorisation déjà demandée par l'écran quand on active. Sans
 * autorisation, `programmerJour` renvoie null : l'intention est gardée, mais
 * rien ne sonne. Rend la semaine posée (sans les identifiants internes).
 */
export async function definirSemaineRituel(entrees: Partial<JourRituel>[]): Promise<SemaineRituel> {
  const courant = await lireStocke();
  await Promise.all(courant.map((j) => annuler(j.id)));

  const voulu = normaliser(entrees);
  const posee: JourStocke[] = [];
  for (const j of voulu) {
    const id = j.actif ? await programmerJour(j.jour, j.heure) : null;
    posee.push({ ...j, id });
  }

  await ecrireStocke(posee);
  return posee.map(({ jour, actif, heure }) => ({ jour, actif, heure }));
}

/** Éteint tout le rituel : annule chaque rappel et repasse chaque jour à inactif (en gardant les heures pour la prochaine fois). */
export async function desactiverSemaineRituel(): Promise<SemaineRituel> {
  const courant = await lireStocke();
  await Promise.all(courant.map((j) => annuler(j.id)));
  const eteints = courant.map((j) => ({ ...j, actif: false, id: null }));
  await ecrireStocke(eteints);
  return eteints.map(({ jour, actif, heure }) => ({ jour, actif, heure }));
}

// ---------------------------------------------------------------------------
// Compat : l'ancienne API à rappel unique, dérivée de la semaine.
//
// L'écran `rituel.tsx` (ouvert depuis « Moi ») et l'indice de `reglages.tsx`
// lisent encore un rappel « du soir » global. On les garde d'aplomb en dérivant
// leur vue de la semaine : actif = au moins un jour allumé ; heure = celle du
// premier jour allumé. Régler l'heure ou activer depuis ces écrans s'applique
// aux jours ouvrés, pour ne pas fabriquer un second réveil concurrent.
// ---------------------------------------------------------------------------

/** Ce que l'ancienne API expose : un rappel global, dérivé de la semaine. */
export type Rituel = { actif: boolean; heure: string };

/** Vue « rappel unique » de la semaine : actif si un jour l'est, heure du premier jour actif. */
export async function lireRituel(): Promise<Rituel> {
  const s = await lireStocke();
  const premierActif = s.find((j) => j.actif);
  return { actif: !!premierActif, heure: premierActif?.heure ?? HEURE_DEFAUT };
}

/**
 * Applique une heure « globale » depuis l'ancien écran. Si des jours sont déjà
 * actifs, on ne touche qu'à leur heure ; sinon on (ré)active les jours ouvrés
 * (lundi→vendredi) à cette heure, comme le défaut du produit.
 */
export async function definirRituel(heure: string): Promise<void> {
  const s = await lireStocke();
  const auMoinsUn = s.some((j) => j.actif);
  const voulu: JourRituel[] = s.map((j) => {
    if (auMoinsUn) return { jour: j.jour, actif: j.actif, heure: j.actif ? heure : j.heure };
    return { jour: j.jour, actif: j.jour <= 4, heure: j.jour <= 4 ? heure : j.heure };
  });
  await definirSemaineRituel(voulu);
}

/** Éteint tout le rituel depuis l'ancien écran. */
export async function desactiverRituel(): Promise<void> {
  await desactiverSemaineRituel();
}
