import { router, useLocalSearchParams } from 'expo-router';
import { useMemo, useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, Switch, Text, View } from 'react-native';

import { Carte, EnteteSection } from '@/components/ecran';
import { SousEcran } from '@/components/sous-ecran';
import { Tuile } from '@/components/elements';
import { VignettesMedias } from '@/components/vignettes-medias';
import { Alerte, BoutonDiscret, BoutonSecondaire, Champ, Pastilles } from '@/components/formulaire';
import { niveauxMaitrise, t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import { localeDate } from '@/lib/dates';
import {
  basculerActifEleve,
  BESOINS,
  competencesDelegueesDe,
  constatsDe,
  constatsRapportesDe,
  definirConstatRapporte,
  elevesDe,
  MATIERE_MINIMALE,
  nomAffiche,
  observationsDeEleve,
  poserBesoins,
  resumerEleve,
  type NiveauRapporte,
  type ResumeEleve,
} from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

function jour(iso: string): string {
  return new Date(iso).toLocaleDateString(localeDate(), { day: 'numeric', month: 'long' });
}

/**
 * La fiche d'un élève : ce qu'on a noté sur lui, et ce qui a été relevé.
 *
 * Les observations d'abord, les constats ensuite. C'est l'ordre du travail réel :
 * l'enseignante se souvient d'un moment, pas d'un code d'attendu.
 */
export default function FicheEleve() {
  const couleurs = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(couleurs), [couleurs]);
  const { id } = useLocalSearchParams<{ id: string }>();
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;

  // On inclut les inactifs : sinon la fiche d'un élève parti ne se chargerait
  // pas et on ne pourrait plus le réactiver.
  const eleves = useRequete(() => elevesDe(classeId!, true), [classeId], { actif: !!classeId });
  const observations = useRequete(() => observationsDeEleve(id!), [id], { actif: !!id });
  const constats = useRequete(() => constatsDe(id!), [id], { actif: !!id });

  // Le suivi RAPPORTÉ (immersion). Les compétences déléguées se lisent au niveau
  // de la CLASSE (la section n'apparaît que s'il y en a) ; les constats
  // rapportés, eux, sont propres à l'ÉLÈVE. Ils vivent dans `reported_mastery`,
  // jamais dans `constats` : ce ne sont pas les vrais constats de la prof.
  const deleguees = useRequete(() => competencesDelegueesDe(classe!), [classeId], {
    actif: !!classe,
  });
  const rapportesReq = useRequete(() => constatsRapportesDe(id!), [id], { actif: !!id });

  const eleve = (eleves.donnees ?? []).find((e) => e.id === id) ?? null;
  const chargement = eleves.chargement || observations.chargement || constats.chargement;

  const [resume, setResume] = useState<ResumeEleve | null>(null);
  const [ecrit, setEcrit] = useState(false);
  const [erreurResume, setErreurResume] = useState<string | null>(null);

  // Copie locale des constats rapportés, pour un rendu immédiat au tap. On la
  // resynchronise dès que la requête revient (changement d'élève, rechargement),
  // au rendu même où la réponse change plutôt que dans un effet.
  const [rapportes, setRapportes] = useState<Map<string, NiveauRapporte>>(new Map());
  const [erreurRapporte, setErreurRapporte] = useState<string | null>(null);
  const [rapportesSource, setRapportesSource] = useState<typeof rapportesReq.donnees>(null);
  if (rapportesReq.donnees !== rapportesSource) {
    setRapportesSource(rapportesReq.donnees);
    if (rapportesReq.donnees) setRapportes(new Map(rapportesReq.donnees));
  }

  async function noterRapporte(competencyId: string, niveau: NiveauRapporte | null) {
    if (!classeId || !id) return;
    const precedent = rapportes;
    setErreurRapporte(null);
    // Optimiste : on applique tout de suite, on annule si l'écriture échoue.
    setRapportes((prev) => {
      const suivant = new Map(prev);
      if (niveau) suivant.set(competencyId, niveau);
      else suivant.delete(competencyId);
      return suivant;
    });
    try {
      await definirConstatRapporte({ classeId, eleveId: id, competencyId, niveau });
    } catch (e) {
      setRapportes(precedent);
      setErreurRapporte(e instanceof Error ? e.message : t.eleve.rapporteErreur);
    }
  }

  const matiere = (observations.donnees ?? []).length + (constats.donnees ?? []).length;

  // Les besoins, modifiables ici. Ils n'étaient réglables que dans l'app web,
  // alors que ce sont eux qui déclenchent les propositions d'adaptation.
  const [modifieBesoins, setModifieBesoins] = useState(false);
  const [besoins, setBesoins] = useState<string[]>([]);
  const [besoinLibre, setBesoinLibre] = useState('');
  const [occupeBesoins, setOccupeBesoins] = useState(false);

  const [occupeActif, setOccupeActif] = useState(false);
  async function basculerActif(v: boolean) {
    if (!id) return;
    setOccupeActif(true);
    try {
      await basculerActifEleve(id, v);
      eleves.recharger();
    } finally {
      setOccupeActif(false);
    }
  }

  function ouvrirBesoins() {
    setBesoins(eleve?.besoins ?? []);
    setBesoinLibre(eleve?.besoinLibre ?? '');
    setModifieBesoins(true);
  }

  async function enregistrerBesoins() {
    setOccupeBesoins(true);
    try {
      await poserBesoins({ eleveId: id!, besoins, besoinLibre });
      setModifieBesoins(false);
      eleves.recharger();
    } catch (e) {
      setErreurResume(e instanceof Error ? e.message : t.eleve.besoinsErreur);
    } finally {
      setOccupeBesoins(false);
    }
  }

  async function ecrireResume() {
    setErreurResume(null);
    setEcrit(true);
    try {
      setResume(await resumerEleve({ eleveId: id!, eleves: eleves.donnees ?? [] }));
    } catch (e) {
      setErreurResume(e instanceof Error ? e.message : t.eleve.resumeErreur);
    } finally {
      setEcrit(false);
    }
  }

  return (
    <SousEcran titre={eleve ? nomAffiche(eleve) : ''}>
        {chargement ? (
          <View style={styles.attente}>
            <ActivityIndicator color={couleurs.encreDouce} />
          </View>
        ) : null}

        {!chargement && !eleve ? (
          <Carte>
            <Text style={texte.discret}>{t.eleve.introuvable}</Text>
          </Carte>
        ) : null}

        {observations.erreur || constats.erreur ? <Alerte message={t.eleve.erreur} /> : null}

        {eleve ? (
          <Carte>
            <View style={styles.ligneActif}>
              <View style={styles.actifTexte}>
                <Text style={texte.corps}>{t.eleve.actif}</Text>
                <Text style={texte.discret}>{t.eleve.actifAide}</Text>
              </View>
              <Switch
                value={eleve.actif}
                onValueChange={basculerActif}
                disabled={occupeActif}
                trackColor={{ false: couleurs.bord, true: couleurs.actif }}
              />
            </View>
          </Carte>
        ) : null}

        {eleve ? (
          <Carte>
            <Text style={texte.discret}>{t.eleve.besoins}</Text>

            {!modifieBesoins ? (
              <>
                {eleve.besoins.length || eleve.besoinLibre ? (
                  <View style={styles.rangee}>
                    {[...eleve.besoins, ...(eleve.besoinLibre ? [eleve.besoinLibre] : [])].map(
                      (b) => (
                        <View key={b} style={styles.etiquette}>
                          <Text style={styles.texteEtiquette}>{b}</Text>
                        </View>
                      ),
                    )}
                  </View>
                ) : null}
                <BoutonDiscret libelle={t.eleve.besoinsModifier} onPress={ouvrirBesoins} />
              </>
            ) : (
              <>
                <Text style={styles.aide}>{t.eleve.besoinsAide}</Text>
                <View style={styles.rangee}>
                  {BESOINS.map((b) => {
                    const actif = besoins.includes(b);
                    return (
                      <Pressable
                        key={b}
                        accessibilityRole="button"
                        accessibilityState={{ selected: actif }}
                        accessibilityLabel={`${t.eleve.besoins} ${b}`}
                        onPress={() =>
                          setBesoins((l) => (actif ? l.filter((x) => x !== b) : [...l, b]))
                        }
                        style={[styles.besoin, actif && styles.besoinActif]}>
                        <Text style={[styles.texteBesoin, actif && styles.texteBesoinActif]}>
                          {b}
                        </Text>
                      </Pressable>
                    );
                  })}
                </View>
                <Champ
                  etiquette={t.eleve.besoinLibre}
                  value={besoinLibre}
                  onChangeText={setBesoinLibre}
                  placeholder={t.eleve.besoinLibreIndice}
                  multiline
                  style={styles.zone}
                  editable={!occupeBesoins}
                />
                {/* On dit ce que ce champ devient. En base il contient déjà des
                    diagnostics et un prénom d'enfant, écrits par des
                    enseignantes qui ne pouvaient pas savoir où ça partirait. */}
                <Text style={styles.aide}>{t.eleve.besoinLibrePourquoi}</Text>
                <BoutonSecondaire
                  libelle={t.eleve.besoinsEnregistrer}
                  onPress={enregistrerBesoins}
                  occupe={occupeBesoins}
                />
                <BoutonDiscret
                  libelle={t.commun.annuler}
                  onPress={() => setModifieBesoins(false)}
                />
              </>
            )}
          </Carte>
        ) : null}

        {/* La synthèse, en tête : c'est le livrable de la boucle et l'objet de
            la passation de juin. Ce qui la nourrit vient après. */}
        {eleve ? (
          <>
            <EnteteSection titre={t.eleve.resume} />
            <Carte>
              <Text style={styles.aide}>{t.eleve.resumeAide}</Text>

              {matiere < MATIERE_MINIMALE ? (
                <Text style={styles.aide}>{t.eleve.resumeMince}</Text>
              ) : null}

              {ecrit ? (
                <View style={styles.ligneAttente}>
                  <ActivityIndicator color={couleurs.encreDouce} />
                  <Text style={texte.discret}>{t.eleve.resumeAttente}</Text>
                </View>
              ) : null}

              {erreurResume ? <Alerte message={erreurResume} /> : null}

              {resume ? (
                <>
                  <Text style={texte.corps}>{resume.synthese}</Text>
                  <BlocResume titre={t.eleve.resumeForces} lignes={resume.forces} />
                  <BlocResume titre={t.eleve.resumeAppuis} lignes={resume.pointsDAppui} />
                  <BlocResume titre={t.eleve.resumeStrategies} lignes={resume.strategies} />
                  <Text style={styles.aide}>{t.eleve.resumeNonEnregistre}</Text>
                </>
              ) : null}

              {matiere >= MATIERE_MINIMALE && !ecrit ? (
                <BoutonSecondaire
                  libelle={resume ? t.eleve.resumeRefaire : t.eleve.resumeEcrire}
                  onPress={ecrireResume}
                />
              ) : null}
            </Carte>

            <EnteteSection titre={t.eleve.observations} />
            {(observations.donnees ?? []).length === 0 ? (
              <Carte>
                <Text style={texte.discret}>{t.eleve.aucuneObservation}</Text>
              </Carte>
            ) : (
              (observations.donnees ?? []).map((o) => (
                <Pressable
                  key={o.id}
                  accessibilityRole={o.statut === 'pending' ? 'button' : 'text'}
                  disabled={o.statut !== 'pending'}
                  onPress={() => router.push({ pathname: '/ranger/[id]', params: { id: o.id } })}>
                  <Carte>
                    <View style={styles.ligne}>
                      {/* Vert « fait » quand c'est rangé, gris tant que non
                          rattaché : la règle de la charte v9. */}
                      {o.statut === 'processed' ? (
                        <Tuile icone="check" moment="recreation" />
                      ) : (
                        <Tuile icone="edit-3" />
                      )}
                      <View style={styles.corps}>
                        {o.texte ? <Text style={texte.corps}>{o.texte}</Text> : null}
                        {/* Les photos jointes à cette observation, sous son texte. */}
                        <VignettesMedias observationId={o.id} taille={64} />
                        <Text style={texte.discret}>
                          {jour(o.creeLe)} · {o.statut === 'pending' ? t.etat.nonRattache : t.etat.rattache}
                        </Text>
                      </View>
                    </View>
                  </Carte>
                </Pressable>
              ))
            )}

            <EnteteSection titre={t.eleve.constats} />
            {(constats.donnees ?? []).length === 0 ? (
              <Carte>
                <Text style={texte.discret}>{t.eleve.aucunConstat}</Text>
              </Carte>
            ) : (
              (constats.donnees ?? []).map((c) => (
                <Carte key={c.id}>
                  <View style={styles.ligne}>
                    {/* La couleur dit le niveau : vert acquis, jaune en cours,
                        gris pas commencé. Jamais de rouge. */}
                    {c.niveau === 'acquired' ? (
                      <Tuile icone="check" moment="recreation" />
                    ) : c.niveau === 'in_progress' ? (
                      <Tuile icone="trending-up" moment="ateliers" />
                    ) : (
                      <Tuile icone="target" />
                    )}
                    <View style={styles.corps}>
                      <Text style={texte.corps}>{c.attendu}</Text>
                      <Text style={texte.discret}>
                        {[c.domaine, c.code, niveauxMaitrise[c.niveau], jour(c.releveLe)]
                          .filter(Boolean)
                          .join(' · ')}
                      </Text>
                    </View>
                  </View>
                </Carte>
              ))
            )}

            {/* Le suivi RAPPORTÉ, tout en bas et visuellement à part : ce sont
                des constats de seconde main sur les compétences déléguées à
                un·e collègue, pas les relevés directs de la prof. La section
                n'apparaît que si la classe délègue au moins une compétence, pour
                que le bilan de l'enfant ne soit pas vide sur la moitié déléguée. */}
            {(deleguees.donnees ?? []).length > 0 ? (
              <>
                <EnteteSection titre={t.eleve.rapporteTitre} />
                <Carte>
                  <Text style={styles.aide}>{t.eleve.rapporteAide}</Text>
                </Carte>
                {erreurRapporte ? <Alerte message={erreurRapporte} /> : null}
                {(deleguees.donnees ?? []).map((d) => {
                  const niveau = rapportes.get(d.competenceId) ?? null;
                  return (
                    <Carte key={d.competenceId}>
                      <Text style={texte.corps}>{d.competence}</Text>
                      <Text style={texte.discret}>
                        {[d.domaine, d.referentiel, t.eleve.rapporteSelon]
                          .filter(Boolean)
                          .join(' · ')}
                      </Text>
                      <Pastilles
                        options={[
                          { id: 'non_renseigne', libelle: t.eleve.rapporteNonRenseigne },
                          { id: 'in_progress', libelle: t.eleve.rapporteEnCours },
                          { id: 'acquired', libelle: t.eleve.rapporteAcquis },
                        ]}
                        // Défaut « non renseigné » quand aucune ligne : une
                        // pastille est toujours mise en avant, l'état est lisible.
                        choisi={niveau ?? 'non_renseigne'}
                        onChoisir={(v) =>
                          noterRapporte(
                            d.competenceId,
                            v === 'in_progress' || v === 'acquired' ? v : null,
                          )
                        }
                      />
                    </Carte>
                  );
                })}
              </>
            ) : null}
          </>
        ) : null}
    </SousEcran>
  );
}

/** Une des trois parties de la synthèse. Une partie vide ne s'affiche pas. */
function BlocResume({ titre, lignes }: { titre: string; lignes: string[] }) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  if (!lignes.length) return null;
  return (
    <View style={styles.bloc}>
      <Text style={styles.etiquetteResume}>{titre}</Text>
      {lignes.map((l) => (
        <View key={l} style={styles.puce}>
          <View style={styles.rond} />
          <Text style={[texte.corps, styles.textePuce]}>{l}</Text>
        </View>
      ))}
    </View>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  aide: { fontFamily: police.corps, fontSize: 14, color: c.encreDouce },
  ligneAttente: { flexDirection: 'row', gap: espace.md, alignItems: 'center' },
  bloc: { gap: espace.xs, marginTop: espace.sm },
  etiquetteResume: { fontFamily: police.accent, fontSize: 14, color: c.encreDouce },
  puce: { flexDirection: 'row', gap: espace.sm, alignItems: 'flex-start' },
  rond: {
    width: 6,
    height: 6,
    borderRadius: 3,
    backgroundColor: c.nonRattache,
    marginTop: 9,
  },
  textePuce: { flex: 1 },
  zone: { minHeight: 72, textAlignVertical: 'top' },
  besoin: {
    backgroundColor: c.fond,
    borderRadius: rayon.pastille,
    borderWidth: 1,
    borderColor: c.bord,
    paddingHorizontal: espace.md,
    paddingVertical: espace.sm,
  },
  besoinActif: { backgroundColor: c.encre, borderColor: c.encre },
  texteBesoin: { fontFamily: police.accent, fontSize: 14, color: c.encreDouce },
  texteBesoinActif: { color: c.surface },
  attente: { paddingVertical: espace.xl, alignItems: 'center' },
  ligneActif: { flexDirection: 'row', gap: espace.md, alignItems: 'center' },
  actifTexte: { flex: 1, gap: 2 },
  ligne: { flexDirection: 'row', gap: espace.md, alignItems: 'center' },
  corps: { flex: 1, gap: espace.xs },
  rangee: { flexDirection: 'row', flexWrap: 'wrap', gap: espace.sm },
  etiquette: {
    backgroundColor: c.fond,
    borderRadius: rayon.pastille,
    paddingHorizontal: espace.md,
    paddingVertical: espace.xs,
  },
  texteEtiquette: { fontFamily: police.accent, fontSize: 13, color: c.encreDouce },
});
