/**
 * Les référentiels que suit une classe, et les domaines qu'elle y enseigne.
 *
 * 🚨 **Quatre filtres décident de ce qu'une classe voit, et un seul est entre
 * les mains de l'enseignante.** Les trois autres sont le cycle traduit par une
 * table de correspondance, le masquage de familles de sources dont l'extraction
 * est reprise, et le `niveau_scolaire` de chaque compétence.
 *
 * Cet écran ne montre donc que ce qui se règle vraiment. Afficher les 32
 * référentiels de la base avec 25 grisés donnerait à croire qu'ils sont à un
 * tap, alors qu'ils sont écartés par des règles qu'elle ne peut ni voir ni
 * juger. Une phrase le dit quand même, parce que taire un filtre serait pire :
 * elle chercherait un référentiel absent sans jamais comprendre pourquoi.
 *
 * 🔑 Le volume est affiché à côté de chaque référentiel. C'est ce qui rend
 * l'exclusion décidable : « retirer celui-ci enlève 41 compétences » est une
 * information, une case à cocher nue n'en est pas une.
 *
 * 🔑 Sous un référentiel ACTIF, on peut préciser les DOMAINES enseignés (retour
 * Mme Mahé) : une prof qui ne donne que le français, ou en immersion, décoche ce
 * qu'elle n'enseigne pas. Défaut : tout coché, donc rien ne change pour les
 * classes existantes.
 *
 * ⚠️ Une bascule vide le catalogue gardé en mémoire, sinon l'IA continuerait à
 * proposer des attendus d'un référentiel qu'elle vient d'écarter.
 */
export default function Referentiels() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { classe } = useClasse();
  // Co-prof en lecture seule : on cloisonne toute écriture de délégation. Reste
  // possible pour un accès write_partial/write_full et pour le·la propriétaire.
  const lectureSeule = classe?.access === 'read';
  const [occupe, setOccupe] = useState<string | null>(null);
  const [erreur, setErreur] = useState<string | null>(null);
  const [deplie, setDeplie] = useState<string | null>(null);
  // Bumpé à chaque bascule (référentiel OU domaine) pour rafraîchir l'alerte.
  const [version, setVersion] = useState(0);

  const referentiels = useRequete(
    () => referentielsDeLaClasse(classe!),
    [classe?.id, classe?.cycle],
    { actif: !!classe },
  );

  async function basculer(id: string, actif: boolean) {
    if (!classe) return;
    setErreur(null);
    setOccupe(id);
    try {
      await basculerReferentiel({ classeId: classe.id, referentielId: id, actif });
      referentiels.recharger();
      setVersion((v) => v + 1);
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.referentiels.erreurBascule);
    } finally {
      setOccupe(null);
    }
  }

  const liste = referentiels.donnees ?? [];

  return (
    <SousEcran
      titre={t.referentiels.titre}
      sousTitre={classe?.nom}
      chargement={referentiels.chargement}>
      <Carte>
        <Text style={styles.aide}>{t.referentiels.aide}</Text>
      </Carte>

      {lectureSeule ? (
        <Carte compacte>
          <Text style={texte.discret}>{L.lectureSeule}</Text>
        </Carte>
      ) : null}

      {referentiels.erreur ? <Alerte message={t.referentiels.erreur} /> : null}
      {erreur ? <Alerte message={erreur} /> : null}

      {classe ? <CarteNonVus classe={classe} version={version} styles={styles} c={c} texte={texte} /> : null}

      {liste.length === 0 ? (
        <Carte>
          <Text style={texte.discret}>{t.referentiels.aucun}</Text>
        </Carte>
      ) : (
        liste.map((r) => (
          <View key={r.id}>
            <Pressable
              accessibilityRole="button"
              accessibilityState={{ selected: r.actif, disabled: occupe === r.id }}
              accessibilityLabel={`${r.nom}, ${t.referentiels.volume(r.competences, r.attendus)}${
                r.actif ? '' : `, ${t.referentiels.ecarte}`
              }`}
              disabled={occupe === r.id || lectureSeule}
              onPress={() => basculer(r.id, !r.actif)}>
              <Carte compacte>
                <View style={styles.ligne}>
                  <View style={[styles.coche, r.actif && styles.cocheActive]}>
                    {r.actif ? <Feather name="check" size={16} color={c.surface} /> : null}
                  </View>
                  <View style={styles.corps}>
                    <Text style={r.actif ? texte.corps : styles.ecarte}>{r.nom}</Text>
                    <Text style={texte.discret}>
                      {[r.source, t.referentiels.volume(r.competences, r.attendus)]
                        .filter(Boolean)
                        .join(' · ')}
                    </Text>
                  </View>
                </View>
              </Carte>
            </Pressable>

            {/* Préciser les domaines : seulement sous un référentiel ACTIF. */}
            {r.actif && classe ? (
              <Pressable
                accessibilityRole="button"
                accessibilityState={{ expanded: deplie === r.id }}
                accessibilityLabel={deplie === r.id ? L.masquer : L.preciser}
                onPress={() => setDeplie((d) => (d === r.id ? null : r.id))}
                style={styles.declencheur}>
                <Feather
                  name={deplie === r.id ? 'chevron-up' : 'chevron-down'}
                  size={16}
                  color={c.encreDouce}
                />
                <Text style={styles.declencheurTexte}>
                  {deplie === r.id ? L.masquer : L.preciser}
                </Text>
              </Pressable>
            ) : null}

            {r.actif && classe && deplie === r.id ? (
              <DomainesReferentiel
                classe={classe}
                referentielId={r.id}
                onBascule={() => setVersion((v) => v + 1)}
                styles={styles}
                c={c}
                texte={texte}
              />
            ) : null}
          </View>
        ))
      )}

      <Carte>
        <Text style={styles.aide}>{t.referentiels.honnetete}</Text>
      </Carte>
    </SousEcran>
  );
}

/** La carte discrète « pas encore vus cette année ». v1 volontairement simple. */
function CarteNonVus({
  classe,
  version,
  styles,
  c,
  texte,
}: {
  classe: Classe;
  version: number;
  styles: ReturnType<typeof creerStyles>;
  c: Couleurs;
  texte: ReturnType<typeof useTexte>;
}) {
  const nonVus = useRequete(() => domainesNonVus(classe), [classe.id, classe.cycle, version]);
  const liste = nonVus.donnees ?? [];
  if (nonVus.chargement || !liste.length) return null;

  return (
    <Carte>
      <View style={styles.ligne}>
        <View style={styles.pastilleAlerte}>
          <Feather name="eye-off" size={16} color={c.actif} />
        </View>
        <View style={styles.corps}>
          <Text style={texte.corps}>{L.nonVusTitre}</Text>
          <Text style={styles.aide}>{L.nonVusAide(liste.length)}</Text>
        </View>
      </View>
      <View style={styles.puces}>
        {liste.map((d) => (
          <Text key={`${d.referentiel} ${d.domaine}`} style={texte.discret}>
            · {d.domaine}
            {d.referentiel ? ` (${d.referentiel})` : ''}
          </Text>
        ))}
      </View>
    </Carte>
  );
}

/** Les domaines d'un référentiel actif, cochables un à un. */
function DomainesReferentiel({
  classe,
  referentielId,
  onBascule,
  styles,
  c,
  texte,
}: {
  classe: Classe;
  referentielId: string;
  onBascule: () => void;
  styles: ReturnType<typeof creerStyles>;
  c: Couleurs;
  texte: ReturnType<typeof useTexte>;
}) {
  const [occupe, setOccupe] = useState<string | null>(null);
  const [erreur, setErreur] = useState<string | null>(null);
  // Quel domaine est déplié pour préciser ses compétences (immersion). Un seul à
  // la fois, comme les référentiels au-dessus : on ouvre celui qu'on règle.
  const [deplieDom, setDeplieDom] = useState<string | null>(null);
  const domaines = useRequete(
    () => domainesDuReferentiel(classe, referentielId),
    [classe.id, classe.cycle, referentielId],
  );

  async function basculer(d: DomaineEnseigne) {
    setErreur(null);
    setOccupe(d.id);
    try {
      await basculerDomaine({ classeId: classe.id, domaineId: d.id, enseigne: !d.enseigne });
      domaines.recharger();
      onBascule();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : L.erreurDomaines);
    } finally {
      setOccupe(null);
    }
  }

  if (domaines.chargement) {
    return (
      <View style={styles.domainesBloc}>
        <Text style={texte.discret}>{L.chargementDomaines}</Text>
      </View>
    );
  }
  if (domaines.erreur) return <Alerte message={L.erreurDomaines} />;

  const liste = domaines.donnees ?? [];
  return (
    <View style={styles.domainesBloc}>
      <Text style={styles.aideDomaines}>{L.aideDomaines}</Text>
      {erreur ? <Alerte message={erreur} /> : null}
      {liste.length === 0 ? (
        <Text style={texte.discret}>{L.aucunDomaine}</Text>
      ) : (
        liste.map((d) => (
          <View key={d.id}>
            <Pressable
              accessibilityRole="button"
              accessibilityState={{ selected: d.enseigne, disabled: occupe === d.id }}
              accessibilityLabel={`${d.nom}, ${t.referentiels.volume(d.competences, d.attendus)}${
                d.enseigne ? '' : `, ${L.domaineEcarte}`
              }`}
              disabled={occupe === d.id || classe.access === 'read'}
              onPress={() => basculer(d)}
              style={styles.domaineLigne}>
              <View style={[styles.cochePetite, d.enseigne && styles.cocheActive]}>
                {d.enseigne ? <Feather name="check" size={14} color={c.surface} /> : null}
              </View>
              <View style={styles.corps}>
                <Text style={d.enseigne ? texte.corps : styles.ecarte}>{d.nom}</Text>
                <Text style={texte.discret}>{t.referentiels.volume(d.competences, d.attendus)}</Text>
              </View>
            </Pressable>

            {/* Descendre au grain compétence : seulement sous un domaine ENSEIGNÉ.
                Un domaine écarté n'a rien à préciser, tout est déjà hors couverture. */}
            {d.enseigne ? (
              <Pressable
                accessibilityRole="button"
                accessibilityState={{ expanded: deplieDom === d.id }}
                accessibilityLabel={deplieDom === d.id ? L.masquerCompetences : L.preciserCompetences}
                onPress={() => setDeplieDom((x) => (x === d.id ? null : d.id))}
                style={styles.declencheurCompetences}>
                <Feather
                  name={deplieDom === d.id ? 'chevron-up' : 'chevron-down'}
                  size={14}
                  color={c.encreDouce}
                />
                <Text style={styles.declencheurTexte}>
                  {deplieDom === d.id ? L.masquerCompetences : L.preciserCompetences}
                </Text>
              </Pressable>
            ) : null}

            {d.enseigne && deplieDom === d.id ? (
              <CompetencesDomaine
                classe={classe}
                domaineId={d.id}
                onChange={onBascule}
                styles={styles}
                c={c}
                texte={texte}
              />
            ) : null}
          </View>
        ))
      )}
    </View>
  );
}

/** L'ordre des trois états, pour un contrôle segmenté toujours à un état choisi. */
const ETATS: StatutCompetence[] = ['enseignee', 'deleguee', 'exclue'];

function libelleStatut(s: StatutCompetence): string {
  if (s === 'deleguee') return L.statutDeleguee;
  if (s === 'exclue') return L.statutExclue;
  return L.statutEnseignee;
}

/**
 * Les compétences d'un domaine enseigné, chacune à trois états : enseignée,
 * déléguée à un·e collègue (immersion), hors programme.
 *
 * 🔑 Contrôle segmenté et non case à cocher : trois états ne tiennent pas dans un
 * oui/non. Un seul état est toujours actif ; retaper l'état courant ne le
 * désélectionne pas (il n'y a pas d'« aucun état »).
 */
function CompetencesDomaine({
  classe,
  domaineId,
  onChange,
  styles,
  c,
  texte,
}: {
  classe: Classe;
  domaineId: string;
  onChange: () => void;
  styles: ReturnType<typeof creerStyles>;
  c: Couleurs;
  texte: ReturnType<typeof useTexte>;
}) {
  const [occupe, setOccupe] = useState<string | null>(null);
  const [erreur, setErreur] = useState<string | null>(null);
  const competences = useRequete(
    () => competencesDuDomaine(classe, domaineId),
    [classe.id, classe.cycle, domaineId],
  );

  async function definir(comp: CompetenceStatut, statut: StatutCompetence) {
    if (comp.statut === statut) return;
    setErreur(null);
    setOccupe(comp.id);
    try {
      await definirStatutCompetence({ classeId: classe.id, competencyId: comp.id, statut });
      competences.recharger();
      onChange();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : L.erreurDomaines);
    } finally {
      setOccupe(null);
    }
  }

  if (competences.chargement) {
    return (
      <View style={styles.competencesBloc}>
        <Text style={texte.discret}>{L.chargementCompetences}</Text>
      </View>
    );
  }
  if (competences.erreur) return <Alerte message={L.erreurDomaines} />;

  const liste = competences.donnees ?? [];
  return (
    <View style={styles.competencesBloc}>
      <Text style={styles.aideDomaines}>{L.aideCompetences}</Text>
      {erreur ? <Alerte message={erreur} /> : null}
      {liste.length === 0 ? (
        <Text style={texte.discret}>{L.aucuneCompetence}</Text>
      ) : (
        liste.map((comp) => (
          <View key={comp.id} style={styles.competenceLigne}>
            <Text style={comp.statut === 'exclue' ? styles.ecarte : texte.corps}>{comp.libelle}</Text>
            <Text style={texte.discret}>{L.attendus(comp.attendus)}</Text>
            <View style={styles.segments}>
              {ETATS.map((etat) => {
                const actif = comp.statut === etat;
                return (
                  <Pressable
                    key={etat}
                    accessibilityRole="button"
                    accessibilityState={{ selected: actif, disabled: occupe === comp.id }}
                    accessibilityLabel={`${comp.libelle}, ${libelleStatut(etat)}`}
                    disabled={occupe === comp.id || classe.access === 'read'}
                    onPress={() => definir(comp, etat)}
                    style={[styles.segment, actif && styles.segmentActif]}>
                    <Text style={actif ? styles.segmentTexteActif : styles.segmentTexte}>
                      {libelleStatut(etat)}
                    </Text>
                  </Pressable>
                );
              })}
            </View>
          </View>
        ))
      )}
    </View>
  );
}

