import * as AppleAuthentication from 'expo-apple-authentication';
import {
  GoogleSignin,
  isErrorWithCode,
  isSuccessResponse,
  statusCodes,
} from '@react-native-google-signin/google-signin';
import Constants from 'expo-constants';
import { Platform } from 'react-native';

import { supabase } from '@/lib/supabase';

/**
 * Connexion Apple et Google, en NATIF.
 *
 * Les deux passent par le même point d'arrivée : on récupère un `idToken` du
 * fournisseur et on le remet à Supabase (`signInWithIdToken`). Pas de retour par
 * lien profond, pas de navigateur intermédiaire : c'est ce qui distingue le natif
 * du web, et c'est pour ça que ces deux boutons ne pouvaient pas être écrits ni
 * essayés tant qu'il n'y avait pas de build de développement.
 *
 * 🔑 Le contrat de retour est UN seul type pour les trois issues, parce que
 * « l'utilisatrice a fermé la feuille » n'est pas une erreur et ne doit pas
 * afficher d'alerte rouge. `{}` = connexion réussie (la bascule d'écran est faite
 * par le garde de session, jamais ici), `{ annule: true }` = fermé sans se
 * connecter, `{ erreur }` = vraie panne à montrer.
 */
export type Issue = { annule?: boolean; erreur?: string };

const extra = (Constants.expoConfig?.extra ?? {}) as {
  googleWebClientId?: string;
  googleIosClientId?: string;
};

// GoogleSignin.configure ne se fait qu'une fois. On le retarde au premier appel
// plutôt qu'au chargement du module : si les identifiants manquent (build sans
// Doppler), on ne veut pas casser tout l'écran, seulement le bouton Google.
let googleConfigure = false;
function configurerGoogle() {
  if (googleConfigure) return;
  GoogleSignin.configure({
    // webClientId définit l'audience du idToken que Supabase doit accepter.
    webClientId: extra.googleWebClientId,
    iosClientId: extra.googleIosClientId,
  });
  googleConfigure = true;
}

/** Le bouton Apple ne s'affiche que sur iOS : ailleurs, Apple refuse la connexion. */
export const appleDisponible = Platform.OS === 'ios';
// Google passe par le SDK natif @react-native-google-signin, indisponible sur le
// web : on masque le bouton hors natif pour ne pas proposer une connexion qui
// planterait. Sur le web, l'email OTP reste le chemin d'entrée.
export const googleDisponible = Platform.OS !== 'web' && Boolean(extra.googleWebClientId);

export async function connexionApple(): Promise<Issue> {
  try {
    const credential = await AppleAuthentication.signInAsync({
      requestedScopes: [
        AppleAuthentication.AppleAuthenticationScope.FULL_NAME,
        AppleAuthentication.AppleAuthenticationScope.EMAIL,
      ],
    });
    if (!credential.identityToken) return { erreur: 'jeton_absent' };
    const { error } = await supabase.auth.signInWithIdToken({
      provider: 'apple',
      token: credential.identityToken,
    });
    if (error) return { erreur: error.message };
    return {};
  } catch (e) {
    // Apple lève ERR_REQUEST_CANCELED quand on ferme la feuille : ce n'est pas une panne.
    if (
      e &&
      typeof e === 'object' &&
      'code' in e &&
      (e as { code?: string }).code === 'ERR_REQUEST_CANCELED'
    ) {
      return { annule: true };
    }
    return { erreur: e instanceof Error ? e.message : 'echec' };
  }
}

export async function connexionGoogle(): Promise<Issue> {
  try {
    configurerGoogle();
    await GoogleSignin.hasPlayServices({ showPlayServicesUpdateDialog: true });
    const reponse = await GoogleSignin.signIn();
    // Annulation ou aucun compte retenu : pas d'alerte.
    if (!isSuccessResponse(reponse)) return { annule: true };
    const idToken = reponse.data.idToken;
    if (!idToken) return { erreur: 'jeton_absent' };
    const { error } = await supabase.auth.signInWithIdToken({
      provider: 'google',
      token: idToken,
    });
    if (error) return { erreur: error.message };
    return {};
  } catch (e) {
    if (isErrorWithCode(e) && e.code === statusCodes.SIGN_IN_CANCELLED) {
      return { annule: true };
    }
    return { erreur: e instanceof Error ? e.message : 'echec' };
  }
}
