import type { Moment } from '@/theme/tokens';

/**
 * Les types d'activité SANS compétences (logistique, vie de classe) : source
 * unique, partagée entre le catalogue (`activite/type.tsx`) et l'affichage
 * (grille du semainier). La couleur code le moment, jamais la matière.
 *
 * 🔑 L'emoji n'est pas stocké en base : on le RETROUVE depuis le titre au moment
 * d'afficher. Un type connu (« Sieste », « Réunion de parents »…) récupère ainsi
 * sa pastille dans la grille, là où il n'y avait que le titre (retour Sophie).
 * Un titre libre (« Autre ») n'a pas d'emoji et retombe proprement sur la puce
 * neutre — rien ne casse.
 */
export type TypeLogistique = { libelle: string; emoji: string; moment: Moment | null };

export const TYPES_SANS_COMPETENCES: TypeLogistique[] = [
  // Réduit aux seuls événements de vie scolaire, dans l'ordre alphabétique
  // (retour Sophie 30/08 : il y en avait trop). « Autre » (champ libre) reste
  // à part, en fin de liste, côté écran.
  { libelle: 'Fête d’école', emoji: '🎉', moment: 'social' },
  { libelle: 'Journée pédagogique', emoji: '📚', moment: null },
  { libelle: 'Réunion de parents', emoji: '👪', moment: null },
  { libelle: 'Remise des bulletins', emoji: '📋', moment: null },
  { libelle: 'Sieste', emoji: '😴', moment: 'social' },
  { libelle: 'Visite médicale', emoji: '🩺', moment: null },
];

/** Normalise un libellé pour la recherche : minuscules, espaces tassés. */
function normaliser(s: string): string {
  return s.toLocaleLowerCase('fr').replace(/\s+/g, ' ').trim();
}

const EMOJI_PAR_LIBELLE = new Map(
  TYPES_SANS_COMPETENCES.map((t) => [normaliser(t.libelle), t.emoji]),
);

/**
 * L'emoji d'une activité logistique d'après son titre, ou `null` si le titre ne
 * correspond à aucun type connu (activité « Autre » au titre libre).
 */
export function emojiActivite(titre: string): string | null {
  return EMOJI_PAR_LIBELLE.get(normaliser(titre)) ?? null;
}
