import { Feather } from '@expo/vector-icons';
import { router, useFocusEffect } from 'expo-router';
import { useCallback, useMemo } from 'react';
import { StyleSheet, Text, View } from 'react-native';

import { Presse } from '@/components/presse';
import { t } from '@/i18n';
import { brouillonsDe } from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { ombre, police, useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * L'icône de boîte de réception dans l'en-tête (pilotage, journal, capter).
 *
 * 🔑 Elle ouvre l'écran `/boite` à trois onglets (Leçons, Observations, Projets)
 * — retour Valentin 24/08. Une pastille dit s'il reste du travail : observations
 * à ranger et brouillons en attente confondus. Le compte vient de `brouillonsDe`
 * (un seul appel), rechargé au retour de focus.
 */
export function BoiteReception({ classeId }: { classeId: string | null }) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);

  const boite = useRequete(() => brouillonsDe(classeId!), [classeId], { actif: !!classeId });

  useFocusEffect(
    useCallback(() => {
      if (classeId) boite.recharger();
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [classeId]),
  );

  const aRanger = boite.donnees?.observations.length ?? 0;
  const brouillons = boite.donnees?.activites.length ?? 0;
  const total = aRanger + brouillons;

  return (
    <Presse
      accessibilityRole="button"
      accessibilityLabel={total > 0 ? `${t.boite.ouvrir}, ${total}` : t.boite.ouvrir}
      onPress={() => router.push('/boite')}
      style={styles.rond}>
      <Feather name="inbox" size={18} color={c.encre} />
      {total > 0 ? (
        <View style={styles.pastille}>
          <Text style={styles.pastilleTexte}>{total > 9 ? '9+' : total}</Text>
        </View>
      ) : null}
    </Presse>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    rond: {
      width: 38,
      height: 38,
      borderRadius: 19,
      backgroundColor: c.surface,
      alignItems: 'center',
      justifyContent: 'center',
      ...ombre.carte,
    },
    pastille: {
      position: 'absolute',
      top: -3,
      right: -3,
      minWidth: 18,
      height: 18,
      borderRadius: 9,
      paddingHorizontal: 4,
      backgroundColor: c.actif,
      alignItems: 'center',
      justifyContent: 'center',
    },
    pastilleTexte: { fontFamily: police.titre, fontSize: 11, color: c.surface },
  });
