import { router } from 'expo-router';
import { useMemo, useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { Cloudy, type Pose } from '@/components/cloudy';
import { BoutonPrincipal } from '@/components/formulaire';
import { t } from '@/i18n';
import { marquerGuideVu } from '@/lib/guide';
import { useMoi } from '@/lib/session';
import { espace, ombre, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * Le tour de démarrage « Prends l'app en main » (retour Valentin 24/08).
 *
 * 🔑 Un TUNNEL, pas une checklist. Il se lance seul à la première session (voir
 * `(tabs)/_layout`), se fait d'un coup du début à la fin, puis ne revient plus.
 * Fond ombré, fenêtre claire au centre : on est présenté une fois, on avance
 * écran par écran, on sort. On peut le relancer depuis les réglages.
 *
 * ⚠️ Présenté en `transparentModal` (voir `_layout`) : le fond ombré laisse
 * deviner l'app dessous, et la fenêtre claire porte l'explication. Le vocabulaire
 * reste simple, pensé pour des enseignant·es.
 */

// Une pose par écran, dans l'ordre des étapes : accueil, capter, journal,
// compétences, collègues, profil, réglages.
const POSES: Pose[] = ['salut', 'micro', 'prof', 'loupe', 'collegues', 'joie', 'serenite'];

export default function Guide() {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const moi = useMoi();
  const [index, setIndex] = useState(0);

  const etapes = t.guide.etapes;
  const total = etapes.length;
  const dernier = index >= total - 1;
  const etape = etapes[index];

  // Fermer = poser le drapeau (ne se relancera plus seul) et rendre la main à
  // l'app. Utilisé par « Passer » et par « C'est parti ! ». Idempotent.
  async function fermer() {
    await marquerGuideVu(moi);
    router.back();
  }

  function suivant() {
    if (dernier) void fermer();
    else setIndex((i) => i + 1);
  }

  return (
    <View style={styles.fond}>
      <SafeAreaView style={styles.zone} edges={['top', 'bottom']}>
        {/* « Passer », discret en haut à droite : on ne piège personne, même si le
            but est de faire le tour d'un coup. */}
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={t.guide.passer}
          onPress={() => void fermer()}
          style={styles.passer}>
          <Text style={styles.passerTexte}>{t.guide.passer}</Text>
        </Pressable>

        {/* La fenêtre claire, au centre du fond ombré. */}
        <View style={styles.fenetre}>
          <Text style={styles.compteur}>{t.guide.etape(index + 1, total)}</Text>
          <Cloudy pose={POSES[index]} taille={132} anime />
          <Text style={styles.titre}>{etape.titre}</Text>
          <Text style={styles.corps}>{etape.corps}</Text>

          {/* Les points de progression. */}
          <View style={styles.points}>
            {etapes.map((_, i) => (
              <View key={i} style={[styles.point, i === index && styles.pointActif]} />
            ))}
          </View>

          {/* La fenêtre centre son contenu (alignItems:center), ce qui rétrécit
              le bouton à la largeur de son texte et l'écrase (retour Valentin
              24/08). On l'enveloppe dans un conteneur pleine largeur pour qu'il
              s'étende comme partout ailleurs. */}
          <View style={styles.actionPleine}>
            <BoutonPrincipal
              libelle={dernier ? t.guide.commencer : t.guide.suivant}
              onPress={suivant}
            />
          </View>
        </View>
      </SafeAreaView>
    </View>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    // Le fond ombré qui laisse deviner l'app dessous (transparentModal).
    fond: { flex: 1, backgroundColor: 'rgba(23, 22, 34, 0.62)' },
    zone: { flex: 1, justifyContent: 'center', padding: espace.lg },
    passer: {
      position: 'absolute',
      top: espace.lg,
      right: espace.lg,
      minHeight: 44,
      justifyContent: 'center',
      paddingHorizontal: espace.sm,
      zIndex: 10,
    },
    passerTexte: { fontFamily: police.accent, fontSize: 15, color: c.surface },
    fenetre: {
      backgroundColor: c.surface,
      borderRadius: rayon.carte,
      padding: espace.xl,
      alignItems: 'center',
      gap: espace.md,
      ...ombre.carte,
    },
    compteur: { fontFamily: police.accent, fontSize: 13, color: c.encreDouce },
    titre: {
      fontFamily: police.titre,
      fontSize: 24,
      color: c.encre,
      textAlign: 'center',
      letterSpacing: -0.3,
    },
    corps: {
      fontFamily: police.corps,
      fontSize: 16,
      lineHeight: 23,
      color: c.encreDouce,
      textAlign: 'center',
    },
    actionPleine: { alignSelf: 'stretch', width: '100%', marginTop: espace.xs },
    points: { flexDirection: 'row', justifyContent: 'center', gap: espace.sm, marginVertical: espace.xs },
    point: { width: 8, height: 8, borderRadius: 4, backgroundColor: c.bord },
    pointActif: { backgroundColor: c.actif, width: 22 },
  });
