import { Feather } from '@expo/vector-icons';
import { router, useLocalSearchParams } from 'expo-router';
import { useMemo, useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

import { Carte } from '@/components/ecran';
import { Alerte, BoutonPrincipal } from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import { mesCollegues, partagerLecon } from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Envoyer une leçon à des collègues.
 *
 * 🚨 L'écran dit ce qui part ET ce qui ne part pas, avant la liste des
 * destinataires. Une enseignante n'envoie pas une séance sans savoir si ses
 * élèves partent avec, et la réponse est non : le partage recopie le texte de
 * la leçon, jamais un lien vers l'activité, donc rien ne pend derrière.
 *
 * ⚠️ On ne propose que les collègues ACCEPTÉES. Le serveur le revérifie de son
 * côté : la politique d'insertion exige le lien. L'app ne fait que proposer une
 * liste, elle n'est pas ce qui protège.
 */
export default function Partager() {
  const couleurs = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(couleurs), [couleurs]);
  const { id } = useLocalSearchParams<{ id: string }>();
  const { classe } = useClasse();
  const collegues = useRequete(mesCollegues, []);

  const [choisies, setChoisies] = useState<string[]>([]);
  const [accepte, setAccepte] = useState(false);
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);

  const liees = (collegues.donnees ?? []).filter((c) => c.statut === 'accepted');

  async function envoyer() {
    if (!id) return;
    if (!accepte) {
      setErreur(t.partage.charteRefus);
      return;
    }
    setErreur(null);
    setOccupe(true);
    try {
      await partagerLecon({
        activiteId: id,
        destinatairesIds: choisies,
        niveaux: classe?.cycle ?? null,
      });
      router.back();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.partage.erreur);
      setOccupe(false);
    }
  }

  return (
    <SousEcran titre={t.partage.titre} chargement={collegues.chargement}>
      <Carte>
        <Text style={styles.quoi}>{t.partage.quoi}</Text>
      </Carte>

      {liees.length === 0 ? (
        <Carte>
          <Text style={texte.discret}>{t.partage.sansCollegue}</Text>
        </Carte>
      ) : (
        <Carte>
          <Text style={texte.section}>{t.partage.aQui}</Text>
          {liees.map((c) => {
            const prise = choisies.includes(c.personneId);
            return (
              <Pressable
                key={c.personneId}
                accessibilityRole="checkbox"
                accessibilityState={{ checked: prise }}
                accessibilityLabel={c.nom ?? ''}
                onPress={() =>
                  setChoisies((avant) =>
                    prise ? avant.filter((x) => x !== c.personneId) : [...avant, c.personneId],
                  )
                }
                style={[styles.ligne, prise && styles.lignePrise]}>
                <View style={[styles.pastille, prise && styles.pastillePrise]}>
                  <Text style={styles.initiale}>
                    {(c.nom ?? '?').trim().charAt(0).toLocaleUpperCase('fr')}
                  </Text>
                </View>
                <Text style={texte.corps}>{c.nom ?? '—'}</Text>
              </Pressable>
            );
          })}
        </Carte>
      )}

      {/* 🚨 La charte « tolérance zéro », exigée par Apple (règle 1.2). Elle
          s'accepte AVANT l'envoi : partager, c'est déposer du contenu chez
          autrui, donc l'engagement se prend au moment du geste, pas enfoui dans
          des réglages. Un moyen de contact est donné, comme la règle l'exige. */}
      {liees.length > 0 ? (
        <Carte>
          <Text style={texte.section}>{t.partage.charteTitre}</Text>
          <Text style={styles.quoi}>{t.partage.charte}</Text>
          <Text style={styles.quoi}>{t.partage.charteContact}</Text>
          <Pressable
            accessibilityRole="checkbox"
            accessibilityState={{ checked: accepte }}
            accessibilityLabel={t.partage.charteAccepter}
            onPress={() => setAccepte((v) => !v)}
            style={styles.accord}>
            <View style={[styles.case, accepte && styles.caseCochee]}>
              {accepte ? <Feather name="check" size={14} color={couleurs.surface} /> : null}
            </View>
            <Text style={texte.corps}>{t.partage.charteAccepter}</Text>
          </Pressable>
        </Carte>
      ) : null}

      {erreur ? <Alerte message={erreur} /> : null}

      {liees.length > 0 ? (
        <BoutonPrincipal
          libelle={t.partage.envoyer}
          onPress={envoyer}
          occupe={occupe}
          inactif={choisies.length === 0 || !accepte}
        />
      ) : null}
    </SousEcran>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  quoi: { fontFamily: police.corps, fontSize: 14, lineHeight: 21, color: c.encreDouce },
  accord: { flexDirection: 'row', alignItems: 'center', gap: espace.sm, marginTop: espace.xs },
  case: {
    width: 24,
    height: 24,
    borderRadius: 6,
    borderWidth: 1.5,
    borderColor: c.bord,
    alignItems: 'center',
    justifyContent: 'center',
  },
  caseCochee: { backgroundColor: c.actif, borderColor: c.actif },
  ligne: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: espace.md,
    paddingVertical: espace.sm,
    paddingHorizontal: espace.sm,
    borderRadius: rayon.bloc,
  },
  lignePrise: { backgroundColor: c.fond },
  pastille: {
    width: 32,
    height: 32,
    borderRadius: 16,
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: c.nonRattache,
  },
  pastillePrise: { backgroundColor: c.actif },
  initiale: { fontFamily: police.accent, fontSize: 14, color: c.surface },
});
