import { useMemo } from 'react';
import { StyleSheet, Text, View } from 'react-native';

import { langue } from '@/i18n';
import { TYPES_APPRENTISSAGE_DEFAUT, type TypeApprentissage } from '@/lib/bloom';
import { couleurDeToken, espace, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * L'AVANCEMENT et le TYPE d'une séance de séquence, en local (`{ fr, nl }[langue]`).
 * La feature est neuve : on ne touche pas aux catalogues `src/i18n/*`. Les
 * libellés des TYPES viennent, eux, de la table `ref_learning_types` (repli sur
 * la liste embarquée `TYPES_APPRENTISSAGE_DEFAUT`).
 */
const LIB = {
  fr: { etape: (k: number, n: number) => `étape ${k}/${n}` },
  nl: { etape: (k: number, n: number) => `stap ${k}/${n}` },
}[langue];

/** « étape k/N ». Le texte d'avancement d'une séance dans sa séquence. */
export function texteEtape(k: number, n: number): string {
  return LIB.etape(k, n);
}

/**
 * Résout un code de type d'apprentissage en sa définition, via la liste fournie
 * (source de vérité `ref_learning_types`), avec repli sur la liste embarquée.
 */
export function typeParCode(
  code: string | null,
  types?: TypeApprentissage[],
): TypeApprentissage | null {
  if (!code) return null;
  const source = types && types.length ? types : TYPES_APPRENTISSAGE_DEFAUT;
  return source.find((t) => t.code === code) ?? null;
}

/**
 * L'étiquette d'un type d'apprentissage (niveau Bloom / évaluation) : une
 * pastille de texte à POINT COLORÉ, volontairement de forme DISTINCTE d'une tuile
 * de moment (dans la charte, la couleur code le moment de la journée, pas le
 * type). Le point porte la couleur du type (via `couleurDeToken`), le libellé
 * vient de la table. Rien si le code est inconnu.
 */
export function EtiquetteType({
  code,
  types,
  compacte = false,
}: {
  code: string | null;
  types?: TypeApprentissage[];
  /** Variante minuscule pour la grille du semainier, où la place est comptée. */
  compacte?: boolean;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const type = typeParCode(code, types);
  if (!type) return null;
  const libelle = langue === 'nl' ? type.labelNl ?? type.labelFr : type.labelFr;
  return (
    <View style={[styles.pastille, compacte && styles.pastilleCompacte]}>
      <View
        style={[styles.point, compacte && styles.pointCompact, { backgroundColor: couleurDeToken(c, type.colorToken) }]}
      />
      <Text style={[styles.texte, compacte && styles.texteCompact]} numberOfLines={1}>
        {libelle}
      </Text>
    </View>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    pastille: {
      flexDirection: 'row',
      alignItems: 'center',
      gap: espace.xs,
      alignSelf: 'flex-start',
      paddingVertical: 2,
      paddingHorizontal: espace.sm,
      borderRadius: rayon.pastille,
      backgroundColor: c.fond,
      borderWidth: 1,
      borderColor: c.bord,
    },
    pastilleCompacte: { paddingHorizontal: 4, paddingVertical: 1, gap: 3, borderRadius: 8 },
    point: { width: 8, height: 8, borderRadius: 4 },
    pointCompact: { width: 6, height: 6, borderRadius: 3 },
    texte: { fontFamily: police.accent, fontSize: 12, color: c.encreDouce },
    texteCompact: { fontSize: 9.5 },
  });
