import * as Sentry from '@sentry/react-native';
import { useFonts } from 'expo-font';
import { Stack } from 'expo-router';
import * as SplashScreen from 'expo-splash-screen';
import { StatusBar } from 'expo-status-bar';
import { useEffect, useMemo, useState, type ReactNode } from 'react';
import { ActivityIndicator, Platform, StyleSheet, View } from 'react-native';

import { NavFlottanteWeb } from '@/components/nav-verre';
import { chargerLangue } from '@/i18n';
import { FournisseurAbonnement, useAbonnement } from '@/lib/abonnement';
import { FournisseurClasse, useClasse } from '@/lib/classe';
import { aVuIntro } from '@/lib/intro';
import { FournisseurLargeurWeb, useLargeurWeb } from '@/lib/largeur-web';
import { capterCodeWebDepuisURL, consommerCodeEnAttente } from '@/lib/parrainage-attente';
import { FournisseurNotifications } from '@/lib/notifications';
import { FournisseurPostHog } from '@/lib/observabilite';
import { FournisseurSession, useSession } from '@/lib/session';
import { chargerTheme, FournisseurTheme, useCouleurs, useTheme, type Couleurs } from '@/theme/tokens';

SplashScreen.preventAutoHideAsync();

/**
 * Le garde de session est déclaratif : on décrit quelles routes existent selon
 * qu'il y a une session ou non, et le routeur s'occupe de la bascule. Un
 * `router.replace` dans un effet marcherait aussi, mais deux endroits qui
 * naviguent finissent toujours par se battre au montage.
 */
function Navigation() {
  const { session, chargement } = useSession();
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);

  // Le code de parrainage capté sur le web (lien `?parrain=CODE`) se rattache
  // TOUT SEUL dès qu'un compte existe : plus rien à retaper. Sous session
  // seulement (la RPC a besoin du compte) ; `consommer` oublie le code une fois
  // appliqué ou jugé inutilisable, et le garde pour un prochain essai si l'échec
  // est transitoire. Rejoué à chaque changement de compte, no-op s'il n'y a rien.
  const compteId = session?.user?.id;
  useEffect(() => {
    if (compteId) void consommerCodeEnAttente();
  }, [compteId]);

  // Tant qu'on lit la session dans le stockage, on ne montre rien plutôt que de
  // faire clignoter l'écran de connexion à chaque ouverture de l'app.
  if (chargement) {
    return (
      <View style={styles.attente}>
        <ActivityIndicator color={c.encreDouce} />
      </View>
    );
  }

  return (
    // La classe active est fournie ici et pas dans les onglets : « Ranger » et
    // « Ma classe » sont empilés au-dessus des onglets, donc hors de leur
    // portée. Un contexte posé trop bas ne se voit pas à la compilation, il
    // explose au premier tap.
    <FournisseurClasse>
      <Routes connecte={!!session} />
    </FournisseurClasse>
  );
}

/**
 * Les routes, selon qu'il y a une session et une classe.
 *
 * Le garde reste **déclaratif** : on décrit quelles routes existent, et le
 * routeur s'occupe de la bascule. Un `router.replace` dans un effet marcherait
 * aussi, mais deux endroits qui naviguent finissent toujours par se battre au
 * montage.
 *
 * 🔑 Trois états, pas deux : pas de session, session sans classe, session avec
 * classe. Sans le deuxième, quelqu'un qui vient de créer un compte atterrit sur
 * un accueil vide qui ne lui apprend rien et ne lui propose rien.
 *
 * ⚠️ On attend de **savoir** s'il y a une classe avant de choisir. Router vers
 * la bienvenue pendant le chargement ferait passer l'onboarding devant le nez
 * de quelqu'un qui a déjà six classes, à chaque ouverture de l'app.
 */
function Routes({ connecte }: { connecte: boolean }) {
  const { enCours, chargement } = useClasse();
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  // 🚨 « Aucune classe » veut dire aucune classe EN COURS, pas aucune ligne en
  // base. Une enseignante qui a archivé son année en juillet doit retomber sur
  // l'onboarding en septembre, pas sur une app qui la croit encore équipée.
  const sansClasse = connecte && !chargement && enCours.length === 0;
  // Gate dur : l'app entière exige un accès premium. « Accès » = abonné
  // RevenueCat OU mois offert (grâce) encore en cours. Le paywall n'est pas une
  // porte qu'on peut ignorer : sans accès, il EST l'écran.
  const { accesPremium, premiumResolu } = useAbonnement();

  // Le tour d'introduction ne concerne qu'un arrivant NON connecté, et une seule
  // fois. On lit le drapeau une fois au montage. Tant qu'on ne SAIT pas (null),
  // on ne rend rien plutôt que de faire clignoter la connexion avant l'intro,
  // ou l'inverse. Un compte déjà connecté ne le voit jamais : le drapeau ne
  // gouverne que le sous-arbre non connecté.
  const [introVu, setIntroVu] = useState<boolean | null>(null);
  useEffect(() => {
    aVuIntro().then(setIntroVu);
  }, []);

  if (connecte && chargement) {
    return (
      <View style={styles.attente}>
        <ActivityIndicator color={c.encreDouce} />
      </View>
    );
  }

  // On attend de SAVOIR si l'accès est ouvert avant de choisir entre l'app et le
  // paywall verrouillé, sinon un compte sans accès verrait l'app clignoter une
  // fraction de seconde. Même prudence que pour le chargement de la classe.
  if (connecte && !sansClasse && !premiumResolu) {
    return (
      <View style={styles.attente}>
        <ActivityIndicator color={c.encreDouce} />
      </View>
    );
  }

  // Non connecté : on attend de SAVOIR si le tour a déjà été vu avant de choisir
  // entre l'intro et la connexion. Sans cette attente, la connexion clignoterait
  // une fraction de seconde avant que l'intro ne la remplace. Sur le web, l'intro
  // n'existe pas (on va droit à la connexion) : inutile d'attendre le drapeau.
  if (!connecte && introVu === null && Platform.OS !== 'web') {
    return (
      <View style={styles.attente}>
        <ActivityIndicator color={c.encreDouce} />
      </View>
    );
  }

  // Verrouillé = connecté, onboarding passé, accès résolu ET absent. Le paywall
  // est alors le seul écran (plein cadre) : on n'accède à rien d'autre tant
  // qu'on ne s'abonne pas. Le déverrouillage est automatique et déclaratif :
  // dès que l'achat bascule `accesPremium`, ce sous-arbre laisse place à l'app.
  if (connecte && !sansClasse && premiumResolu && !accesPremium) {
    return (
      <Stack screenOptions={{ headerShown: false, contentStyle: { backgroundColor: c.fond } }}>
        <Stack.Screen name="abonnement" />
      </Stack>
    );
  }

  return (
    <Stack screenOptions={{ headerShown: false, contentStyle: { backgroundColor: c.fond } }}>
      <Stack.Protected guard={sansClasse}>
        <Stack.Screen name="bienvenue" />
      </Stack.Protected>
      <Stack.Protected guard={connecte && !sansClasse}>
        <Stack.Screen name="(tabs)" />
        {/* La capture rapide, en modal, ouverte d'un appui long sur l'onglet
            micro depuis n'importe où : la même composition que l'onglet Capter,
            posée par-dessus l'écran courant, dont on revient d'un retour. */}
        <Stack.Screen name="capter-vite" options={{ presentation: 'modal' }} />
        <Stack.Screen name="classe/index" />
        <Stack.Screen name="classe/[id]" />
        {/* L'arc de l'année et la passation de juin : deux écrans qui pensent en
            septembre-à-juin, empilés au-dessus des onglets. On y entre depuis
            l'accueil (l'année) et depuis la classe (la passation), on en revient. */}
        <Stack.Screen name="annee" />
        <Stack.Screen name="passation" />
        <Stack.Screen name="ranger/[id]" options={{ presentation: 'modal' }} />
        {/* La liste « À ranger », ouverte depuis la boîte de réception de
            l'en-tête. Les observations en attente y vivent depuis que le
            journal ne déroule plus le fil « ce que tu as capté ». */}
        <Stack.Screen name="ranger/index" />
        {/* La boîte de réception, écran à trois onglets (Leçons, Observations,
            Projets), ouverte depuis l'icône d'en-tête. */}
        <Stack.Screen name="boite" />
        {/* Le rituel du soir, empilé au-dessus des onglets : on l'ouvre depuis le
            mot de Cloudy sur l'accueil, depuis « Toi », ou d'un tap sur le rappel.
            Il route lui-même vers « ranger/[id] » (modale) pour chaque note, donc
            il n'est pas modal lui-même : la modale de rangement se pose par-dessus
            et lui rend la main. */}
        <Stack.Screen name="soir" />
        {/* L'activité vit au-dessus des onglets, comme « Ranger » : on y
            arrive depuis le journal, depuis une compétence de l'accueil, et
            on en revient. Ce n'est pas un lieu où l'on séjourne. */}
        {/* Le sélecteur de type d'activité, en modal comme la création : on
            l'ouvre depuis une case vide du semainier ou du journal, on choisit un
            type, et il `replace` vers la création préremplie. */}
        <Stack.Screen name="activite/type" options={{ presentation: 'modal' }} />
        <Stack.Screen name="activite/nouvelle" options={{ presentation: 'modal' }} />
        <Stack.Screen name="activite/[id]" />
        <Stack.Screen name="activite/modifier/[id]" options={{ presentation: 'modal' }} />
        {/* L'absence de l'enseignant·e : déclarer, récupérer une journée
            planifiée, puis replanifier les activités reportées. Déclarer se
            présente en modal (on l'ouvre depuis le journal, on en revient) ; la
            liste « À replanifier » vit au-dessus des onglets, ouverte depuis les
            réglages, et la replanification s'y fait sur place. */}
        <Stack.Screen name="absence" options={{ presentation: 'modal' }} />
        <Stack.Screen name="replanifier/index" />
        <Stack.Screen name="activite/cloturer/[id]" options={{ presentation: 'modal' }} />
        <Stack.Screen name="competences/index" />
        <Stack.Screen name="lecon/[competence]" />
        <Stack.Screen name="projet/index" />
        <Stack.Screen name="projet/[id]" />
        {/* La vue direction/inspection : agrégée, en lecture seule, jamais
            nominative. L'écran se garde lui-même par rôle ; la vraie garde reste
            serveur (RPC self-scoping). Empilée au-dessus des onglets. */}
        <Stack.Screen name="direction/index" />
        {/* La fenêtre qui explique la vue direction du point de vue du prof,
            avant d'ouvrir la page côté site (rassurer, puis inviter). */}
        <Stack.Screen name="direction-info" />
        {/* Le parrainage : partage du lien, suivi des filleul·es, la manne.
            On y entre depuis Groupes (acte social/viral), pas depuis « Moi ». */}
        <Stack.Screen name="parrainage/index" />
        {/* Les réglages, empilés au-dessus des onglets eux aussi. */}
        <Stack.Screen name="vous/reglages" />
        <Stack.Screen name="vous/profil" />
        <Stack.Screen name="vous/classes" />
        <Stack.Screen name="vous/semaine" />
        <Stack.Screen name="vous/referentiels" />
        <Stack.Screen name="vous/notifications" />
        <Stack.Screen name="vous/rituel" />
        <Stack.Screen name="vous/exporter" />
        {/* Le paywall EducooO GO!, présenté en modal comme les autres écrans
            qu'on ouvre et dont on revient. */}
        <Stack.Screen name="abonnement" options={{ presentation: 'modal' }} />
        {/* La célébration « Semaine bouclée », présentée en modal par-dessus les
            onglets : on l'ouvre en fin de semaine et on en revient. */}
        <Stack.Screen name="celebration" options={{ presentation: 'modal' }} />
        {/* La célébration d'un palier de trophée : Cloudy en fête et des
            confettis quand on franchit un jalon d'activités clôturées. */}
        <Stack.Screen name="trophee-celebration" options={{ presentation: 'modal' }} />
        {/* Le tour de démarrage « Prends l'app en main », lancé seul au premier
            lancement et relançable depuis les réglages. En transparentModal : le
            fond ombré du tour laisse deviner l'app dessous. */}
        <Stack.Screen
          name="guide"
          options={{
            presentation: 'transparentModal',
            animation: 'fade',
            contentStyle: { backgroundColor: 'transparent' },
          }}
        />
      </Stack.Protected>
      {/* Le tour d'arrivée « intro », déclaré UNE SEULE FOIS. Un écran ne peut pas
          porter deux fois le même nom dans une pile : l'invariant expo-router le
          refuse en DEV (natif comme web), et la prod en prenait un au hasard (le
          double coûtait un crash du dev client, donc plus aucun dev/test natif en
          local). Un seul Stack.Screen, une garde qui couvre les DEUX usages, gardes
          mutuellement exclusives au runtime :
            - pré-connexion, tant qu'il n'a pas été vu : route d'atterrissage
              (déclarée AVANT « connexion ») ; « Commencer » pose le drapeau et
              remplace la route par « connexion » ;
            - reconnecté avec une classe prête : rejouable depuis « Toi » (revoir=1).
          Hors web dans les deux cas (le web va droit à la connexion : les planches
          font doublon avec le tour « Prends l'app en main » d'après connexion).
          Présentation par défaut : la version pré-connexion est la route d'accueil
          plein écran ; le replay pousse l'écran au lieu de glisser en modal
          (compromis assumé pour tenir en une seule déclaration). */}
      <Stack.Protected
        guard={Platform.OS !== 'web' && ((!connecte && !introVu) || (connecte && !sansClasse))}>
        <Stack.Screen name="intro" />
      </Stack.Protected>
      <Stack.Protected guard={!connecte}>
        <Stack.Screen name="connexion" />
      </Stack.Protected>
    </Stack>
  );
}

function RacineLayout() {
  const [policesPretes] = useFonts({
    'AlanSans-Regular': require('@/assets/fonts/AlanSans-Regular.ttf'),
    'AlanSans-SemiBold': require('@/assets/fonts/AlanSans-SemiBold.ttf'),
    'AlanSans-ExtraBold': require('@/assets/fonts/AlanSans-ExtraBold.ttf'),
  });

  // La langue se résout ici, derrière le splash déjà tenu pour les polices : on
  // lit le choix mémorisé avant le premier écran, pour que rien ne s'affiche
  // dans la langue de l'appareil puis bascule sous les yeux de l'utilisateur.
  const [languePrete, setLanguePrete] = useState(false);
  useEffect(() => {
    // La langue et le thème se résolvent ensemble, derrière le même splash : les
    // deux lisent un choix mémorisé qu'il faut appliquer avant le premier écran.
    Promise.all([chargerLangue(), chargerTheme()]).finally(() => setLanguePrete(true));
  }, []);

  // On capte le code de parrainage de l'URL AU PLUS TÔT (web), avant que quoi que
  // ce soit ne nettoie la barre d'adresse : il sera rattaché tout seul dès qu'un
  // compte existe. Sans effet sur natif (la fonction se garde par plateforme).
  useEffect(() => {
    void capterCodeWebDepuisURL();
  }, []);

  const pret = policesPretes && languePrete;

  useEffect(() => {
    if (pret) SplashScreen.hideAsync();
  }, [pret]);

  if (!pret) return null;

  return (
    // Le thème enveloppe tout : le StatusBar comme la navigation en dépendent.
    // Le choix (Système / Clair / Sombre) est lu par `useCouleurs`/`useTexte`
    // partout dessous, et la bascule est immédiate (pas de rechargement).
    <FournisseurTheme>
      <FournisseurSession>
        {/* Observabilité posée sous la session : PostHog (usage) et Sentry
            (erreurs) suivent l'identité du compte connecté. Aucun contenu
            d'observation d'enfant ni prénom n'est capté, et PostHog vise l'UE. */}
        <FournisseurPostHog>
          <BarreEtat />
          {/* L'abonnement est posé sous la session : il relie l'identité RevenueCat
              au compte connecté. Il enveloppe la navigation pour que l'état soit lu
              partout, y compris pendant que la session se charge. */}
          <FournisseurAbonnement>
            {/* Les notifications vivent sous la session (elles enregistrent le token
                push du compte connecté) et englobent la navigation pour que le tap
                sur une notif puisse router depuis n'importe quel écran. */}
            <FournisseurNotifications>
              <FournisseurLargeurWeb>
                <CadreWeb>
                  <Navigation />
                </CadreWeb>
              </FournisseurLargeurWeb>
            </FournisseurNotifications>
          </FournisseurAbonnement>
        </FournisseurPostHog>
      </FournisseurSession>
    </FournisseurTheme>
  );
}

/**
 * La barre d'état suit le thème : icônes sombres sur fond clair, claires sur
 * fond sombre. Sans ça, l'heure et la batterie disparaîtraient sur le fond nuit.
 */
function BarreEtat() {
  const { schema } = useTheme();
  return <StatusBar style={schema === 'sombre' ? 'light' : 'dark'} />;
}

/**
 * Le cadre « téléphone » du web.
 *
 * 🌐 L'app est dessinée pour un téléphone : une colonne unique de cartes
 * empilées. Sur un navigateur large, laissée libre, cette colonne s'étire sur
 * 1280 px et le moindre bouton devient une bande démesurée. On plafonne donc,
 * SUR LE WEB SEULEMENT, toute la navigation à une largeur de téléphone centrée,
 * posée sur un voile neutre : on retrouve l'app telle qu'elle est pensée, au
 * milieu de l'écran. Sous cette largeur (mobile, navigateur étroit), la colonne
 * prend tout : non-événement. Sur natif, c'est un simple passe-plat, la mise en
 * page mobile est strictement inchangée.
 */
// La largeur de confort du web : au-dessus, une colonne unique de cartes s'étire
// trop (longueur de ligne, formulaires démesurés). En dessous de ~520 (téléphone,
// navigateur étroit), la colonne prend tout. Entre les deux, l'app respire sans
// perdre en lisibilité. Les écrans qui GAGNENT à la largeur (la grille du
// semainier) demandent la pleine largeur ci-dessous.
const MAX_LARGEUR_WEB = 820;
const MAX_LARGEUR_WEB_PLEINE = 1120;
function CadreWeb({ children }: { children: ReactNode }) {
  const c = useCouleurs();
  const { schema } = useTheme();
  const { pleine } = useLargeurWeb();
  if (Platform.OS !== 'web') return <>{children}</>;
  // Un voile solide dans les deux thèmes (les jetons de bord sont translucides),
  // un cran plus contrasté que le fond pour détacher la colonne sans l'encadrer.
  const voile = schema === 'sombre' ? '#0E0D14' : '#E3E1EC';
  return (
    <View style={[cadreWebStyles.voile, { backgroundColor: voile }]}>
      <View
        style={[
          cadreWebStyles.colonne,
          { backgroundColor: c.fond, maxWidth: pleine ? MAX_LARGEUR_WEB_PLEINE : MAX_LARGEUR_WEB },
        ]}>
        {children}
        {/* 🌐 La barre de navigation flottante, posée par-dessus la colonne sur le
            web, pour rester accessible sur les écrans poussés (leçon, activité)
            où seule la flèche retour existait. Elle se gare elle-même sur les
            écrans d'onglets (déjà pourvus de leur barre) et hors coquille
            (connexion, paywall). Dans la colonne, elle hérite de sa largeur de
            téléphone et de son rognage. Jamais montée sur natif : ce composant
            ne vit que dans la branche web de ce cadre. */}
        <NavFlottanteWeb />
      </View>
    </View>
  );
}
const cadreWebStyles = StyleSheet.create({
  voile: { flex: 1, alignItems: 'center' },
  colonne: { flex: 1, width: '100%', overflow: 'hidden' },
});

// Sentry.wrap ajoute l'error boundary natif et le suivi du composant racine.
// L'init Sentry lui-même s'exécute déjà à l'import de `observabilite`, guardée
// par la présence du DSN (inerte sans clé, comme RevenueCat).
export default Sentry.wrap(RacineLayout);

const creerStyles = (c: Couleurs) => StyleSheet.create({
  attente: { flex: 1, backgroundColor: c.fond, alignItems: 'center', justifyContent: 'center' },
});
