import { useCallback, useEffect, useRef, useState } from 'react';

type Etat<T> = {
  donnees: T | null;
  chargement: boolean;
  erreur: string | null;
  /** Relance la requête. Sert au tirer-pour-rafraîchir et après une écriture. */
  recharger: () => void;
};

/**
 * Le minimum viable pour charger des données, sans ajouter de bibliothèque de
 * cache. Trois choses qu'on ne peut pas se permettre de rater et qui sont
 * traitées ici une fois pour toutes :
 *  - ne pas écrire dans un composant démonté, sinon avertissement et fuite,
 *  - ignorer la réponse d'une requête périmée quand les clés ont changé,
 *  - distinguer « pas encore chargé » de « chargé et vide », parce qu'avec la
 *    protection par ligne, vide est un résultat normal et pas une erreur.
 */
export function useRequete<T>(
  charger: () => Promise<T>,
  cles: ReadonlyArray<unknown>,
  options: { actif?: boolean } = {},
): Etat<T> {
  const actif = options.actif ?? true;
  const [donnees, setDonnees] = useState<T | null>(null);
  const [chargement, setChargement] = useState(actif);
  const [erreur, setErreur] = useState<string | null>(null);
  const [tour, setTour] = useState(0);
  const dernier = useRef(0);

  // La dernière version de `charger`, relue par l'effet sans en faire une
  // dépendance (c'est une fonction recréée à chaque rendu). On la range dans un
  // effet déclaré AVANT celui du chargement : les effets passent dans l'ordre,
  // donc le chargement lit toujours la version du rendu courant.
  const chargerRef = useRef(charger);
  useEffect(() => {
    chargerRef.current = charger;
  });

  // « Chargement en cours » et l'erreur remise à zéro suivent les clés : on les
  // ajuste pendant le rendu où elles changent (le schéma React « ajuster l'état
  // quand une prop change »), pas dans l'effet, ce qui évite un rendu en cascade.
  const cle: readonly unknown[] = [actif, tour, ...cles];
  const [clePrecedente, setClePrecedente] = useState(cle);
  if (cle.length !== clePrecedente.length || cle.some((v, i) => !Object.is(v, clePrecedente[i]))) {
    setClePrecedente(cle);
    setChargement(actif);
    if (actif) setErreur(null);
  }

  useEffect(() => {
    if (!actif) return;
    const monTour = ++dernier.current;
    let vivant = true;

    chargerRef
      .current()
      .then((r) => {
        if (!vivant || monTour !== dernier.current) return;
        setDonnees(r);
      })
      .catch((e: unknown) => {
        if (!vivant || monTour !== dernier.current) return;
        setErreur(e instanceof Error ? e.message : String(e));
      })
      .finally(() => {
        if (!vivant || monTour !== dernier.current) return;
        setChargement(false);
      });

    return () => {
      vivant = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [actif, tour, ...cles]);

  const recharger = useCallback(() => setTour((t) => t + 1), []);

  return { donnees, chargement, erreur, recharger };
}
