import { Feather } from '@expo/vector-icons';
import { router, useLocalSearchParams } from 'expo-router';
import { useMemo } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

import { Presse } from '@/components/presse';
import { SousEcran } from '@/components/sous-ecran';
import { TYPES_SANS_COMPETENCES } from '@/lib/types-activite';
import { espace, police, rayon, useCouleurs, useTexte, type Couleurs, type Moment } from '@/theme/tokens';

/**
 * Le catalogue d'activités : on choisit d'abord CE QU'ON POSE.
 *
 * 🔑 La vraie question, avant un titre, c'est « est-ce que ça travaille des
 * compétences ». Deux mondes, deux sections :
 *
 *   • AVEC compétences = le flux LEÇON. Deux gestes côte à côte : créer une
 *     nouvelle leçon (Cloudy détecte les attendus), ou reprendre une leçon qui
 *     existe déjà.
 *   • SANS compétences = la logistique et les routines. Un accueil, une piscine,
 *     une réunion : rien à rattacher. On les pose d'un tap, tous visibles d'un
 *     coup (pas de menu déroulant), en petits blocs teintés de leur moment.
 *
 * On reçoit `date` et `creneau` (comme `nouvelle`) : arriver ici depuis une case
 * du semainier ou un moment du journal pose vraiment l'activité à cet endroit-là.
 */

// Les types sans compétences vivent dans `@/lib/types-activite` : source unique,
// partagée avec l'affichage de la grille (pour retrouver l'emoji d'un type).

export default function ChoixTypeActivite() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { date, creneau } = useLocalSearchParams<{ date?: string; creneau?: string }>();

  const paramsBase = useMemo(() => {
    const p: Record<string, string> = {};
    if (date) p.date = date;
    if (creneau) p.creneau = creneau;
    return p;
  }, [date, creneau]);

  // Vers la création. `replace` (et non `push`) : le sélecteur est un aiguillage,
  // pas un lieu où l'on revient.
  function versCreation(prerempli?: { titre?: string; sansCompetences?: boolean }) {
    const params = { ...paramsBase };
    if (prerempli?.titre) params.titre = prerempli.titre;
    if (prerempli?.sansCompetences) params.sansCompetences = '1';
    router.replace({ pathname: '/activite/nouvelle', params });
  }

  // Reprendre une leçon existante : on garde le contexte (date/créneau) et on
  // ouvre la bibliothèque de leçons déjà produites (dans l'écran de création,
  // via `reprise=1`), qui recopie vraiment le contenu et les attendus.
  function versReprendre() {
    router.replace({ pathname: '/activite/nouvelle', params: { ...paramsBase, reprise: '1' } });
  }

  return (
    <SousEcran titre="Ajouter une activité">
      {/* ─────── Avec compétences : le flux leçon ─────── */}
      <Text style={[texte.section, styles.titre]}>Activité avec compétences</Text>
      <View style={styles.deux}>
        <GrandBloc
          emoji="✨"
          moment="dirigees"
          titre="Créer une nouvelle leçon"
          aide="Cloudy détecte ce que ça travaille"
          onPress={() => versCreation()}
        />
        <GrandBloc
          emoji="🔁"
          moment="accueil"
          titre="Reprendre une leçon existante"
          aide="Repartir d'une leçon déjà prête"
          onPress={versReprendre}
        />
      </View>

      {/* ─────── Sans compétences : la logistique, tout visible ─────── */}
      <Text style={[texte.section, styles.titre]}>Activité sans compétences</Text>
      <Text style={styles.aide}>Une routine, une sortie, un temps de vie de classe. Un tap suffit.</Text>
      <View style={styles.blocs}>
        {TYPES_SANS_COMPETENCES.map((t) => (
          <PetitBloc
            key={t.libelle}
            emoji={t.emoji}
            libelle={t.libelle}
            moment={t.moment}
            onPress={() => versCreation({ titre: t.libelle, sansCompetences: true })}
          />
        ))}
        {/* L'issue de secours : une activité qui n'entre dans aucune case. */}
        <PetitBloc emoji="✏️" libelle="Autre" moment={null} onPress={() => versCreation({ sansCompetences: true })} />
      </View>
    </SousEcran>
  );
}

/** Un grand bloc du flux leçon : emoji teinté, titre, aide. Deux par ligne. */
function GrandBloc({
  emoji,
  moment,
  titre,
  aide,
  onPress,
}: {
  emoji: string;
  moment: Moment | null;
  titre: string;
  aide: string;
  onPress: () => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const fond = moment ? c.teinte[moment] : c.fond;
  return (
    <Presse accessibilityRole="button" accessibilityLabel={`${titre}, ${aide}`} onPress={onPress} style={styles.grandBloc}>
      <View style={[styles.grandEmoji, { backgroundColor: fond }]}>
        <Text style={styles.emojiGrand}>{emoji}</Text>
      </View>
      <View style={styles.grandCorps}>
        <Text style={styles.grandTitre}>{titre}</Text>
        <Text style={styles.grandAide}>{aide}</Text>
      </View>
    </Presse>
  );
}

/** Un petit bloc logistique : emoji + libellé, teinté de son moment. */
function PetitBloc({
  emoji,
  libelle,
  moment,
  onPress,
}: {
  emoji: string;
  libelle: string;
  moment: Moment | null;
  onPress: () => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const fond = moment ? c.teinte[moment] : c.fond;
  return (
    <Presse
      accessibilityRole="button"
      accessibilityLabel={libelle}
      onPress={onPress}
      style={styles.petitBloc}>
      <View style={[styles.petitPastille, { backgroundColor: fond }]}>
        <Text style={styles.petitEmoji}>{emoji}</Text>
      </View>
      <Text style={styles.petitTexte} numberOfLines={1}>
        {libelle}
      </Text>
    </Presse>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    titre: { marginTop: espace.sm },
    aide: { fontFamily: police.corps, fontSize: 14, color: c.encreDouce, marginTop: -espace.xs },

    // Les deux grands blocs du flux leçon. Empilement HORIZONTAL (emoji à gauche,
    // titre + aide à droite) pour gagner de la hauteur.
    deux: { flexDirection: 'row', gap: espace.sm },
    grandBloc: {
      flex: 1,
      flexDirection: 'row',
      alignItems: 'center',
      backgroundColor: c.surface,
      borderRadius: rayon.carte,
      borderWidth: 1,
      borderColor: c.bord,
      padding: espace.md,
      gap: espace.sm,
    },
    grandEmoji: {
      width: 44,
      height: 44,
      borderRadius: rayon.tuile,
      alignItems: 'center',
      justifyContent: 'center',
    },
    grandCorps: { flex: 1, gap: 2 },
    emojiGrand: { fontSize: 24 },
    grandTitre: { fontFamily: police.accent, fontSize: 15, color: c.encre },
    grandAide: { fontFamily: police.corps, fontSize: 13, lineHeight: 18, color: c.encreDouce },

    // Les petits blocs logistiques, en flot : carte blanche bordée, avec une
    // pastille colorée du moment qui porte l'emoji. La couleur ressort sur la
    // pastille au lieu de délaver tout le bloc.
    blocs: { flexDirection: 'row', flexWrap: 'wrap', gap: espace.sm },
    petitBloc: {
      flexDirection: 'row',
      alignItems: 'center',
      gap: espace.sm,
      paddingVertical: espace.xs,
      paddingHorizontal: espace.sm,
      borderRadius: rayon.bloc,
      backgroundColor: c.surface,
      borderWidth: 1,
      borderColor: c.bord,
    },
    petitPastille: {
      width: 30,
      height: 30,
      borderRadius: rayon.tuile,
      alignItems: 'center',
      justifyContent: 'center',
    },
    petitEmoji: { fontSize: 17 },
    petitTexte: { fontFamily: police.accent, fontSize: 14, color: c.encre },
  });
