import { Feather } from '@expo/vector-icons';
import { router } from 'expo-router';
import { ReactNode, useMemo } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, Text, useWindowDimensions, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { t } from '@/i18n';
import { espace, maxContenu, pointLarge, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Gabarit d'un écran empilé au-dessus des onglets : une barre avec le retour,
 * un titre, et le contenu en cartes.
 *
 * Il existe parce que la même barre était recopiée dans « ranger », dans les
 * trois écrans d'activité et dans les quatre écrans de réglages. Une barre
 * recopiée huit fois dérive huit fois, et c'est le seul endroit de l'app où le
 * geste de sortie se trouve : il n'a pas le droit de bouger d'un écran à
 * l'autre.
 */
export function SousEcran({
  titre,
  sousTitre,
  chargement = false,
  children,
  auRetour,
  actions,
  enteteFixe,
}: {
  titre: string;
  sousTitre?: string;
  chargement?: boolean;
  children?: ReactNode;
  /**
   * Un bandeau qui reste FIXE sous le titre, hors du défilement (une barre de
   * recherche à garder sous la main pendant qu'on parcourt une longue liste).
   */
  enteteFixe?: ReactNode;
  /** Pour un écran en étapes, où le retour remonte d'une étape avant de sortir. */
  auRetour?: () => void;
  /**
   * Boutons à droite de la barre (l'écrou du thème sur Réglages, par exemple).
   * Sans eux, l'emplacement reste un vide de même largeur que le retour, pour
   * que le titre reste centré.
   */
  actions?: ReactNode;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  // Grands écrans : barre de titre et colonne de contenu centrées, plafonnées.
  // Sous le seuil (tout téléphone), `large` est faux : mise en page inchangée.
  const { width } = useWindowDimensions();
  const large = width > pointLarge;
  return (
    <SafeAreaView style={styles.racine} edges={['top']}>
      <View style={[styles.barre, large && styles.colonne]}>
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={t.cloture.retour}
          onPress={() => (auRetour ? auRetour() : router.back())}
          style={styles.retour}>
          <Feather name="chevron-left" size={24} color={c.encre} />
        </Pressable>
        <View style={styles.centre}>
          <Text style={texte.section}>{titre}</Text>
          {sousTitre ? <Text style={texte.discret}>{sousTitre}</Text> : null}
        </View>
        {actions ? <View style={styles.actions}>{actions}</View> : <View style={styles.retour} />}
      </View>

      {enteteFixe ? (
        <View style={[styles.enteteFixe, large && styles.colonne]}>{enteteFixe}</View>
      ) : null}

      {chargement ? (
        <View style={styles.attente}>
          <ActivityIndicator color={c.encreDouce} />
        </View>
      ) : (
        <ScrollView
          contentContainerStyle={[styles.contenu, large && styles.colonne]}
          keyboardShouldPersistTaps="handled">
          {children}
        </ScrollView>
      )}
    </SafeAreaView>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  racine: { flex: 1, backgroundColor: c.fond },
  barre: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: espace.sm,
    paddingBottom: espace.sm,
  },
  centre: { alignItems: 'center', flex: 1 },
  retour: { width: 40, height: 40, alignItems: 'center', justifyContent: 'center' },
  actions: { minWidth: 40, height: 40, flexDirection: 'row', alignItems: 'center', justifyContent: 'flex-end', gap: espace.xs },
  attente: { flex: 1, alignItems: 'center', justifyContent: 'center' },
  contenu: { padding: espace.md, paddingBottom: espace.xl * 2, gap: espace.md },
  enteteFixe: {
    paddingHorizontal: espace.md,
    paddingBottom: espace.sm,
  },
  // Colonne centrée, plafonnée : appliquée seulement au-delà de `pointLarge`.
  colonne: { width: '100%', maxWidth: maxContenu, alignSelf: 'center' },
});
