import { Feather } from '@expo/vector-icons';
import { router } from 'expo-router';
import { useMemo, useState } from 'react';
import { Modal, Pressable, StyleSheet, Text, View } from 'react-native';

import { Presse } from '@/components/presse';
import { t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import { espace, ombre, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * Le sélecteur de classe, à droite du titre sur pilotage, journal et capter.
 *
 * 🔑 Une enseignante passe souvent d'une classe à l'autre dans la journée. Le
 * geste doit être sous la main partout où l'écran parle d'UNE classe, jamais
 * enfoui dans les réglages. On ne change pas la classe active en base, on la
 * mémorise (voir `useClasse`) : capter juste après atterrit dans la bonne classe.
 *
 * Une puce compacte (le nom de la classe + un chevron) ouvre une petite feuille
 * qui liste les classes en cours, la classe active cochée. Pas de vue « Toutes »
 * (décision Valentin 24/08) : le pilotage agrège mal des niveaux différents et
 * capter a besoin d'une cible unique. La dernière ligne mène à la gestion des
 * classes, pour en ajouter une sans quitter le fil.
 */
export function SelecteurClasse() {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { classe, enCours, choisir } = useClasse();
  const [ouvert, setOuvert] = useState(false);

  // Sans classe active, rien à sélectionner : le chip ne s'affiche pas.
  if (!classe) return null;

  return (
    <>
      <Presse
        accessibilityRole="button"
        accessibilityLabel={`${t.selecteurClasse.ouvrir}, ${classe.nom}`}
        onPress={() => setOuvert(true)}
        style={styles.puce}>
        <Text style={styles.puceTexte} numberOfLines={1}>
          {classe.nom}
        </Text>
        <Feather name="chevron-down" size={16} color={c.encre} />
      </Presse>

      <Modal visible={ouvert} transparent animationType="fade" onRequestClose={() => setOuvert(false)}>
        {/* Le voile ferme au tap hors de la feuille. */}
        <Pressable style={styles.voile} onPress={() => setOuvert(false)}>
          {/* La feuille ne referme pas quand on la touche elle-même. */}
          <Pressable style={styles.feuille} onPress={() => {}}>
            <Text style={styles.titre}>{t.selecteurClasse.titre}</Text>

            {enCours.map((cl) => {
              const actif = cl.id === classe.id;
              return (
                <Pressable
                  key={cl.id}
                  accessibilityRole="button"
                  accessibilityState={{ selected: actif }}
                  accessibilityLabel={cl.nom}
                  onPress={() => {
                    choisir(cl.id);
                    setOuvert(false);
                  }}
                  style={[styles.ligne, actif && styles.ligneActive]}>
                  <View style={styles.ligneCorps}>
                    <Text style={styles.ligneNom} numberOfLines={1}>
                      {cl.nom}
                    </Text>
                    <Text style={styles.ligneAnnee}>{cl.anneeScolaire}</Text>
                  </View>
                  {actif ? <Feather name="check" size={18} color={c.actif} /> : null}
                </Pressable>
              );
            })}

            <Pressable
              accessibilityRole="button"
              accessibilityLabel={t.selecteurClasse.gerer}
              onPress={() => {
                setOuvert(false);
                router.push('/vous/classes');
              }}
              style={styles.gerer}>
              <Feather name="settings" size={16} color={c.encreDouce} />
              <Text style={styles.gererTexte}>{t.selecteurClasse.gerer}</Text>
            </Pressable>
          </Pressable>
        </Pressable>
      </Modal>
    </>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    puce: {
      flexDirection: 'row',
      alignItems: 'center',
      gap: espace.xs,
      maxWidth: 130,
      paddingVertical: 6,
      paddingHorizontal: espace.sm,
      borderRadius: rayon.pastille,
      backgroundColor: c.surface,
      ...ombre.carte,
    },
    puceTexte: { fontFamily: police.accent, fontSize: 14, color: c.encre, flexShrink: 1 },
    voile: {
      flex: 1,
      backgroundColor: 'rgba(23, 22, 34, 0.4)',
      justifyContent: 'flex-end',
    },
    feuille: {
      backgroundColor: c.surface,
      borderTopLeftRadius: rayon.carte,
      borderTopRightRadius: rayon.carte,
      padding: espace.lg,
      paddingBottom: espace.xl,
      gap: espace.sm,
    },
    titre: { fontFamily: police.titre, fontSize: 18, color: c.encre, marginBottom: espace.xs },
    ligne: {
      flexDirection: 'row',
      alignItems: 'center',
      gap: espace.md,
      padding: espace.md,
      borderRadius: rayon.bloc,
      borderWidth: 1,
      borderColor: c.bord,
    },
    ligneActive: { borderColor: c.actif, backgroundColor: c.fond },
    ligneCorps: { flex: 1, gap: 2 },
    ligneNom: { fontFamily: police.corps, fontSize: 16, color: c.encre },
    ligneAnnee: { fontFamily: police.corps, fontSize: 13, color: c.encreDouce },
    gerer: {
      flexDirection: 'row',
      alignItems: 'center',
      gap: espace.sm,
      paddingVertical: espace.sm,
      paddingHorizontal: espace.md,
      marginTop: espace.xs,
    },
    gererTexte: { fontFamily: police.accent, fontSize: 14, color: c.encreDouce },
  });
