import AsyncStorage from '@react-native-async-storage/async-storage';
import { createContext, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';
import { Platform } from 'react-native';
import Purchases, {
  LOG_LEVEL,
  type CustomerInfo,
  type PurchasesError,
  type PurchasesPackage,
} from 'react-native-purchases';

import { monProfil } from './donnees';
import { env } from './env';
import { useMoi } from './session';

/**
 * L'identifiant de l'entitlement côté RevenueCat, celui qui débloque tout.
 *
 * C'est l'IDENTIFIANT (lookup_key) défini dans le tableau de bord RevenueCat,
 * pas seulement le nom d'affichage. Vérifié via l'API le 21/08/2026 : le
 * lookup_key est bien « EducooO GO! » (id interne entlcd686b6f1c). Une seule
 * lettre qui diffère et l'app croirait tout le monde non abonné, sans erreur.
 */
export const ENTITLEMENT_GO = 'EducooO GO!';

/** L'offering (catalogue de packages) présenté par défaut sur le paywall. */
export const OFFERING_DEFAUT = 'default';

type EtatAbonnement = {
  /** Vrai une fois RevenueCat configuré et la première info client reçue. */
  pret: boolean;
  /** Vrai si RevenueCat est utilisable (clé présente). Sinon tout est inerte. */
  disponible: boolean;
  /** Vrai si l'entitlement EducooO GO! est actif (achat RevenueCat). */
  abonne: boolean;
  /**
   * Le gate premium à utiliser PARTOUT pour ouvrir une fonctionnalité payante :
   * abonné RevenueCat OU période de grâce « mois offert » gérée par l'app encore
   * en cours. C'est la seule vérité d'accès, les écrans ne recombinent rien.
   */
  accesPremium: boolean;
  /**
   * Vrai une fois qu'on SAIT si l'accès est ouvert ou non : RevenueCat prêt ET
   * la grâce du profil chargée. Le gate dur s'en sert pour ne pas faire clignoter
   * le paywall pendant qu'on charge, exactement comme le garde de classe attend
   * de savoir avant de router.
   */
  premiumResolu: boolean;
  /** Vrai tant que la grâce « mois offert » de l'app court (indépendante de RC). */
  essaiAppActif: boolean;
  /** Fin de la grâce app (ISO), ou null si pas de grâce connue. */
  essaiExpireLe: string | null;
  /** La dernière info client connue, ou null tant qu'on n'a rien reçu. */
  infos: CustomerInfo | null;
  /**
   * Le package annuel de l'offering courant ($rc_annual), ou null tant qu'on ne
   * l'a pas chargé. C'est lui qui porte le prix localisé et l'éventuel essai
   * gratuit : le paywall lit tout depuis là plutôt que d'écrire un prix en dur.
   */
  offre: PurchasesPackage | null;
  /** Lance l'achat de l'offre annuelle. Renvoie vrai si on est abonné ensuite. */
  acheter: () => Promise<boolean>;
  /** Relit l'info client depuis RevenueCat (après un achat hors paywall, par ex). */
  rafraichir: () => Promise<void>;
  /** Restaure les achats précédents (obligatoire sur iOS, utile sur Android). */
  restaurer: () => Promise<boolean>;
};

const Contexte = createContext<EtatAbonnement | null>(null);

/** Vrai dès que l'entitlement EducooO GO! est dans les entitlements actifs. */
function estAbonne(infos: CustomerInfo | null): boolean {
  return !!infos && typeof infos.entitlements.active[ENTITLEMENT_GO] !== 'undefined';
}

/**
 * Vrai si la grâce « mois offert » court encore. La lecture de l'horloge vit
 * hors du composant (elle est impure) ; le fournisseur la refait à chaque
 * recalcul de sa valeur, exactement comme avant. On ne la fige pas au montage :
 * le fournisseur vit toute la session, une grâce qui expire doit finir par
 * verrouiller sans attendre un redémarrage.
 */
function graceEnCours(finIso: string | null): boolean {
  return !!finIso && Date.now() < Date.parse(finIso);
}

// La configuration de RevenueCat est un effet de bord global, pas un état React :
// elle ne doit avoir lieu qu'une fois pour tout le process, même si le
// fournisseur était remonté. Ce garde de module survit aux remontages, là où un
// useRef repartirait de zéro.
let dejaConfigure = false;

/**
 * Une seule source de vérité pour l'abonnement, posée sous le fournisseur de
 * session parce qu'il en dépend : quand quelqu'un se connecte, on relie son
 * identité Supabase à RevenueCat (logIn) pour que ses achats le suivent d'un
 * appareil à l'autre ; quand il se déconnecte, on repasse RevenueCat en anonyme
 * (logOut) pour ne pas prêter son abonnement au compte suivant sur le téléphone.
 */
export function FournisseurAbonnement({ children }: { children: ReactNode }) {
  const moi = useMoi();
  // 🚫 Sur le web, RevenueCat tourne en « Browser Mode » et refuse les clés
  // natives : `Purchases.configure` y lève une erreur NON rattrapée (errorCode
  // 11) qui blanchit toute l'app. On ne vend pas via le web, donc on rend le SDK
  // strictement inerte hors natif — ce garde, combiné à l'absence de clé, est la
  // ceinture ET les bretelles. Le fournisseur se déclare « prêt » sans se
  // configurer et l'accès premium repose sur la grâce « mois offert ». Natif
  // inchangé (Platform.OS !== 'web' y est toujours vrai).
  const disponible = Platform.OS !== 'web' && !!env.revenueCatKey;
  const [infos, setInfos] = useState<CustomerInfo | null>(null);
  const [offre, setOffre] = useState<PurchasesPackage | null>(null);
  const [essaiExpireLe, setEssaiExpireLe] = useState<string | null>(null);
  // Vrai une fois que la lecture de la grâce du profil a abouti (succès ou
  // échec). Distinct de « pas de grâce » : tant que c'est faux, on ne sait pas
  // encore, donc on ne verrouille pas. Sans session, il n'y a rien à lire :
  // l'accès est « résolu » d'emblée (voir plus bas).
  const [essaiCharge, setEssaiCharge] = useState(!moi);
  // Sans SDK disponible, on est « prêt » d'emblée : rien à configurer, et
  // personne ne doit rester bloqué derrière un chargement qui n'aura pas lieu.
  const [pret, setPret] = useState(!disponible);

  // Configuration unique + écoute des mises à jour. RevenueCat pousse une
  // nouvelle info client dès qu'un achat est validé côté store (y compris quand
  // le paywall natif fait le travail), donc on n'a pas à sonder : on écoute.
  useEffect(() => {
    // Pas de clé : `pret` est déjà vrai (état initial) pour ne bloquer personne,
    // mais abonne restera faux et tout le reste est neutralisé.
    if (!disponible) return;

    if (!dejaConfigure) {
      // Les logs verbeux ne servent qu'au développement : en prod ils
      // encombrent la console et exposent des détails d'implémentation.
      // On enveloppe la configuration : une clé refusée ne doit JAMAIS remonter
      // en erreur non rattrapée (ce qui blanchirait l'app). En cas d'échec on
      // reste simplement « prêt mais pas abonné ».
      try {
        Purchases.setLogLevel(__DEV__ ? LOG_LEVEL.DEBUG : LOG_LEVEL.ERROR);
        Purchases.configure({ apiKey: env.revenueCatKey! });
        dejaConfigure = true;
      } catch (e) {
        console.warn('RevenueCat: configuration impossible', e);
        // Écriture synchrone assumée : c'est l'issue d'un appel au SDK (système
        // externe) qui échoue dans l'effet même, sur un chemin d'erreur rare, et
        // la configuration ne peut pas quitter l'effet (effet de bord global).
        // eslint-disable-next-line react-hooks/set-state-in-effect
        setPret(true);
        return;
      }
    }

    const surMaj = (nouvelles: CustomerInfo) => setInfos(nouvelles);
    Purchases.addCustomerInfoUpdateListener(surMaj);

    // Le catalogue : on prend le package annuel de l'offering courant. On vise
    // d'abord le raccourci `.annual` (le package $rc_annual), et à défaut le
    // premier package disponible, pour ne pas tomber si l'offering est renommé.
    Purchases.getOfferings()
      .then((offerings) => {
        const courant = offerings.current;
        setOffre(courant?.annual ?? courant?.availablePackages[0] ?? null);
      })
      .catch((e) => console.warn('RevenueCat: offerings indisponibles', e));

    // Première lecture. Une erreur ici (réseau coupé au lancement) ne doit pas
    // faire planter l'app : on reste « pas abonné » et on réessaiera plus tard.
    Purchases.getCustomerInfo()
      .then(setInfos)
      .catch((e) => console.warn('RevenueCat: lecture initiale impossible', e))
      .finally(() => setPret(true));

    return () => {
      Purchases.removeCustomerInfoUpdateListener(surMaj);
    };
  }, [disponible]);

  // Synchronise l'identité RevenueCat avec la session Supabase. On attend que
  // RevenueCat soit configuré (`pret`) pour ne pas appeler logIn dans le vide.
  useEffect(() => {
    if (!disponible || !pret) return;

    if (moi) {
      // logIn renvoie l'info client à jour du compte relié : on la prend sans
      // attendre le prochain événement, pour que l'écran sache tout de suite.
      Purchases.logIn(moi)
        .then(({ customerInfo }) => setInfos(customerInfo))
        .catch((e) => console.warn('RevenueCat: logIn impossible', e));
    } else {
      // On ne déconnecte RevenueCat QUE si un compte y était relié. Appeler
      // `logOut` sur un utilisateur déjà anonyme ne fait rien d'utile mais le SDK
      // émet un warning bruyant (« LogOut was called but the current user is
      // anonymous ») que le `.catch` n'étouffe pas (c'est un log SDK, pas une
      // exception). On lit donc l'identité courante d'abord : les id anonymes sont
      // préfixés `$RCAnonymousID:`. Rien à déconnecter = on ne touche à rien.
      Purchases.getAppUserID()
        .then((id) => {
          if (id && !id.startsWith('$RCAnonymousID:')) {
            return Purchases.logOut().then(setInfos);
          }
        })
        .catch(() => {});
    }
  }, [moi, pret, disponible]);

  // La grâce « mois offert » gérée par l'app est INDÉPENDANTE de RevenueCat :
  // elle vaut même sans clé (SDK inerte). On lit donc la fin de grâce du profil
  // dès qu'il y a une session, sans attendre le SDK. Une erreur ici (réseau)
  // laisse simplement la grâce à null : on retombe sur le seul entitlement RC.
  //
  // L'état « chargé ou pas » suit la session au rendu où elle change (schéma
  // React « ajuster l'état quand une prop change »), pas dans l'effet.
  const [moiPrecedent, setMoiPrecedent] = useState(moi);
  if (moi !== moiPrecedent) {
    setMoiPrecedent(moi);
    if (!moi) {
      // Pas de session : rien à verrouiller (on est sur la connexion). On
      // considère l'accès « résolu » pour ne pas coincer un état de chargement.
      setEssaiExpireLe(null);
      setEssaiCharge(true);
    } else {
      setEssaiCharge(false);
    }
  }
  useEffect(() => {
    if (!moi) return;
    let vivant = true;
    // Clé par personne : la grâce d'un compte ne doit jamais servir à un autre
    // sur le même téléphone.
    const cle = `educooo.grace.${moi}`;
    monProfil()
      .then((p) => {
        const e = p?.essaiExpireLe ?? null;
        if (vivant) setEssaiExpireLe(e);
        // On garde la dernière date connue en local. Le gate est DUR : un
        // démarrage hors-ligne ne doit pas verrouiller à tort un mois offert
        // encore valable faute d'avoir pu relire le profil.
        AsyncStorage.setItem(cle, e ?? '').catch(() => {});
      })
      .catch(async () => {
        // Lecture réseau impossible : on retombe sur la dernière date connue.
        try {
          const cache = await AsyncStorage.getItem(cle);
          if (vivant) setEssaiExpireLe(cache || null);
        } catch {
          if (vivant) setEssaiExpireLe(null);
        }
      })
      .finally(() => {
        if (vivant) setEssaiCharge(true);
      });
    return () => {
      vivant = false;
    };
  }, [moi]);

  const valeur = useMemo<EtatAbonnement>(() => {
    // La grâce est active tant que sa date de fin est dans le futur. Une date
    // absente (null) veut dire « pas de grâce connue », donc pas d'accès par
    // ce biais : on retombe sur le seul entitlement RevenueCat.
    const essaiAppActif = graceEnCours(essaiExpireLe);
    return {
      pret,
      disponible,
      abonne: estAbonne(infos),
      accesPremium: estAbonne(infos) || essaiAppActif,
      premiumResolu: pret && essaiCharge,
      essaiAppActif,
      essaiExpireLe,
      infos,
      offre,
      acheter: async () => {
        if (!offre) throw new Error('Aucune offre à acheter (offering non chargé).');
        try {
          const { customerInfo } = await Purchases.purchasePackage(offre);
          setInfos(customerInfo);
          return estAbonne(customerInfo);
        } catch (e) {
          // L'annulation par l'utilisateur n'est pas une erreur : on renvoie
          // simplement « pas abonné » sans rien remonter. Le reste (paiement
          // refusé, réseau) est une vraie erreur que le paywall doit afficher.
          if ((e as PurchasesError).userCancelled) return false;
          throw e;
        }
      },
      rafraichir: async () => {
        if (!disponible) return;
        try {
          setInfos(await Purchases.getCustomerInfo());
        } catch (e) {
          console.warn('RevenueCat: rafraîchissement impossible', e);
        }
      },
      restaurer: async () => {
        if (!disponible) return false;
        const restaurees = await Purchases.restorePurchases();
        setInfos(restaurees);
        return estAbonne(restaurees);
      },
    };
  }, [pret, disponible, infos, offre, essaiExpireLe, essaiCharge]);

  return <Contexte.Provider value={valeur}>{children}</Contexte.Provider>;
}

export function useAbonnement(): EtatAbonnement {
  const valeur = useContext(Contexte);
  if (!valeur) throw new Error('useAbonnement doit être appelé sous FournisseurAbonnement.');
  return valeur;
}
