import { Feather } from '@expo/vector-icons';
import { useMemo, useState } from 'react';
import { Modal, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';

import { Avatar } from '@/components/avatar';
import { Alerte } from '@/components/formulaire';
import { Presse } from '@/components/presse';
import { t } from '@/i18n';
import {
  enregistrerPreset,
  envoyerPhotoAvatar,
  PRESETS_AVATAR,
  resoudreAvatar,
  retirerAvatar,
} from '@/lib/avatar';
import { espace, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * « Choisir mon avatar » — la modale de choix, montée depuis l'espace « Moi ».
 *
 * Deux voies, dans l'ordre du plus simple au plus engageant :
 *   1. une grille de presets (des poses de Cloudy) : un tap suffit ;
 *   2. « Ma photo » : on prend une image de la galerie, elle part dans le seau
 *      `avatars` et son URL se range sur le profil.
 * Et un retrait, pour revenir au défaut.
 *
 * 🔑 Contrôlée par le parent (`visible` / `onFermer`), elle remonte la nouvelle
 * valeur par `onChange` pour que l'écran « Moi » se rafraîchisse. La croix de
 * fermeture vit dans un en-tête FIXE, hors du défilement (charte : la croix
 * reste sous la main même quand la grille défile).
 */
export function AvatarChoisir({
  visible,
  valeurActuelle,
  onFermer,
  onChange,
}: {
  visible: boolean;
  valeurActuelle: string | null | undefined;
  onFermer: () => void;
  onChange: (valeur: string | null) => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);

  const resolu = resoudreAvatar(valeurActuelle);
  const presetActif = resolu.type === 'preset' ? resolu.pose : null;
  const aUnAvatar = resolu.type !== 'defaut';

  async function agir(
    action: () => Promise<string | null | undefined>,
    appliquer: (v: string | null) => void,
  ) {
    if (occupe) return;
    setOccupe(true);
    setErreur(null);
    try {
      const v = await action();
      // `undefined` = geste annulé (sélecteur de photo fermé) : on ne change rien.
      // `null` reste une valeur pleine et voulue (retrait de l'avatar).
      if (v === undefined) return;
      appliquer(v);
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.moi.avatar.erreur);
    } finally {
      setOccupe(false);
    }
  }

  function choisirPreset(cle: string) {
    void agir(
      async () => {
        await enregistrerPreset(cle);
        return cle;
      },
      (v) => {
        onChange(v);
        onFermer();
      },
    );
  }

  function choisirPhoto() {
    void agir(
      async () => {
        const url = await envoyerPhotoAvatar();
        // Annulation du sélecteur : `null` → on remonte `undefined` pour ne rien
        // changer (et ne pas fermer). Une URL → on l'applique.
        return url ?? undefined;
      },
      (v) => {
        onChange(v);
        onFermer();
      },
    );
  }

  function retirer() {
    void agir(
      async () => {
        await retirerAvatar();
        return null;
      },
      (v) => {
        onChange(v);
        onFermer();
      },
    );
  }

  return (
    <Modal visible={visible} transparent animationType="fade" onRequestClose={onFermer}>
      <Pressable style={styles.voile} onPress={onFermer}>
        <Pressable style={styles.feuille} onPress={() => {}}>
          {/* En-tête FIXE, hors ScrollView : la croix reste atteignable. */}
          <View style={styles.entete}>
            <Text style={styles.titre} numberOfLines={1}>
              {t.moi.avatar.titre}
            </Text>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={t.moi.avatar.fermer}
              onPress={onFermer}
              hitSlop={8}
              style={styles.croix}>
              <Feather name="x" size={20} color={c.encreDouce} />
            </Pressable>
          </View>

          <ScrollView contentContainerStyle={styles.corps} showsVerticalScrollIndicator={false}>
            {erreur ? <Alerte message={erreur} /> : null}

            <Text style={styles.sousTitre}>{t.moi.avatar.presetsTitre}</Text>
            <View style={styles.grille}>
              {PRESETS_AVATAR.map((p) => {
                const actif = presetActif === p.pose;
                return (
                  <Presse
                    key={p.cle}
                    accessibilityRole="button"
                    accessibilityState={{ selected: actif }}
                    accessibilityLabel={t.moi.avatar.poses[p.pose]}
                    onPress={() => choisirPreset(p.cle)}
                    style={[styles.tuile, actif && styles.tuileActive]}>
                    <Avatar valeur={p.cle} taille={56} />
                  </Presse>
                );
              })}
            </View>

            <Text style={styles.sousTitre}>{t.moi.avatar.photoTitre}</Text>
            <Presse
              accessibilityRole="button"
              accessibilityLabel={t.moi.avatar.photo}
              onPress={choisirPhoto}
              style={styles.ligne}>
              <View style={styles.ligneIcone}>
                <Feather name="image" size={18} color={c.action[1]} />
              </View>
              <View style={styles.ligneCorps}>
                <Text style={styles.ligneNom}>{t.moi.avatar.photo}</Text>
                <Text style={styles.ligneAide}>{t.moi.avatar.photoAide}</Text>
              </View>
              <Feather name="chevron-right" size={18} color={c.encreDouce} />
            </Presse>

            {aUnAvatar ? (
              <Presse
                accessibilityRole="button"
                accessibilityLabel={t.moi.avatar.retirer}
                onPress={retirer}
                style={styles.ligne}>
                <View style={styles.ligneIcone}>
                  <Feather name="rotate-ccw" size={18} color={c.encreDouce} />
                </View>
                <View style={styles.ligneCorps}>
                  <Text style={styles.ligneNom}>{t.moi.avatar.retirer}</Text>
                  <Text style={styles.ligneAide}>{t.moi.avatar.retirerAide}</Text>
                </View>
              </Presse>
            ) : null}
          </ScrollView>
        </Pressable>
      </Pressable>
    </Modal>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    voile: { flex: 1, backgroundColor: 'rgba(23, 22, 34, 0.4)', justifyContent: 'flex-end' },
    feuille: {
      backgroundColor: c.surface,
      borderTopLeftRadius: rayon.carte,
      borderTopRightRadius: rayon.carte,
      padding: espace.lg,
      paddingBottom: espace.xl,
      gap: espace.sm,
      maxHeight: '85%',
    },
    entete: { flexDirection: 'row', alignItems: 'center', gap: espace.sm },
    titre: { flex: 1, fontFamily: police.titre, fontSize: 18, color: c.encre },
    croix: { width: 32, height: 32, alignItems: 'center', justifyContent: 'center' },
    corps: { gap: espace.sm, paddingTop: espace.sm },
    sousTitre: {
      fontFamily: police.accent,
      fontSize: 13,
      color: c.encreDouce,
      marginTop: espace.sm,
      marginBottom: espace.xs,
    },
    grille: { flexDirection: 'row', flexWrap: 'wrap', gap: espace.sm },
    tuile: {
      padding: espace.xs,
      borderRadius: rayon.bloc,
      borderWidth: 2,
      borderColor: 'transparent',
    },
    tuileActive: { borderColor: c.actif, backgroundColor: c.actionTeinte },
    ligne: {
      flexDirection: 'row',
      alignItems: 'center',
      gap: espace.md,
      paddingVertical: espace.md,
      paddingHorizontal: espace.md,
      borderRadius: rayon.bloc,
      backgroundColor: c.fond,
    },
    ligneIcone: {
      width: 36,
      height: 36,
      borderRadius: rayon.pastille,
      alignItems: 'center',
      justifyContent: 'center',
      backgroundColor: c.actionTeinte,
    },
    ligneCorps: { flex: 1, gap: 2 },
    ligneNom: { fontFamily: police.accent, fontSize: 15, color: c.encre },
    ligneAide: { fontFamily: police.corps, fontSize: 13, color: c.encreDouce },
  });
