import AsyncStorage from '@react-native-async-storage/async-storage';
import { createContext, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';

import { mesClasses, type Classe } from './donnees';
import { useRequete } from './requete';
import { useSession } from './session';

type EtatClasse = {
  /** Toutes, archivées comprises. Pour l'écran qui les range en deux sections. */
  classes: Classe[];
  /** Celles de l'année en cours. C'est ce que « avoir une classe » veut dire. */
  enCours: Classe[];
  /** La classe active. Null seulement si l'enseignant·e n'en a aucune. */
  classe: Classe | null;
  choisir: (id: string) => void;
  chargement: boolean;
  erreur: string | null;
  recharger: () => void;
};

const Contexte = createContext<EtatClasse | null>(null);

/**
 * La classe active est un état global parce que trois écrans en dépendent, et
 * qu'une observation captée doit atterrir dans la même classe que celle qu'on
 * regardait. Passer l'identifiant en paramètre de navigation marcherait, mais
 * il suffirait d'un écran qui oublie de le transmettre pour ranger une
 * observation dans la mauvaise classe. Ici c'est impossible.
 */
export function FournisseurClasse({ children }: { children: ReactNode }) {
  const { session } = useSession();
  const [choisie, setChoisie] = useState<string | null>(null);

  // 🚨 La classe active se MÉMORISE, et ce n'est pas un confort.
  //
  // Sans ça, l'app repartait sur la première classe à chaque ouverture. Sur le
  // compte de démonstration ça ne se voit pas : il n'a qu'une classe. Mais
  // trois enseignantes sur huit en ont deux ou trois, et pour elles l'app
  // choisissait à leur place à chaque lancement.
  //
  // Le risque n'est pas l'agacement, c'est l'erreur silencieuse : capter une
  // observation en croyant être dans sa classe de l'après-midi et la ranger
  // dans celle du matin. Le commentaire ci-dessous dit qu'un identifiant ne
  // peut pas être mal transmis ; il ne disait rien du fait qu'on pouvait se
  // retrouver sur la mauvaise classe sans l'avoir demandé.
  //
  // Clé propre au compte : deux enseignantes qui partagent une tablette ne se
  // récupèrent pas la classe l'une de l'autre.
  const cle = session ? `educooo.classe.${session.user.id}` : null;

  // Plus de session : on oublie la classe choisie, au rendu où la clé change
  // (schéma React « ajuster l'état quand une prop change »), pas dans l'effet.
  const [clePrecedente, setClePrecedente] = useState(cle);
  if (cle !== clePrecedente) {
    setClePrecedente(cle);
    if (!cle) setChoisie(null);
  }

  useEffect(() => {
    if (!cle) return;
    let vivant = true;
    AsyncStorage.getItem(cle).then((valeur) => {
      if (vivant && valeur) setChoisie(valeur);
    });
    return () => {
      vivant = false;
    };
  }, [cle]);

  const { donnees, chargement, erreur, recharger } = useRequete(
    mesClasses,
    [session?.user.id],
    { actif: !!session },
  );

  const classes = donnees ?? [];
  const enCours = classes.filter((c) => !c.archivee);

  // 🚨 Le repli ne tombe QUE sur une classe en cours.
  //
  // Une archivée peut être active, mais seulement si elle a été choisie
  // explicitement : c'est la différence entre consulter son année passée et se
  // réveiller dedans. Sans cette distinction, une enseignante qui a tout
  // archivé se retrouverait à capter ses observations de septembre dans la
  // classe de juin.
  //
  // Et `enCours` est aussi ce que le garde de l'accueil doit regarder :
  // « aucune classe » veut dire aucune classe en cours, pas aucune ligne en
  // base, sinon l'onboarding ne se déclencherait jamais à la rentrée.
  const classe = classes.find((c) => c.id === choisie) ?? enCours[0] ?? null;

  const valeur = useMemo<EtatClasse>(
    () => ({
      classes,
      enCours,
      classe,
      choisir: (id: string) => {
        setChoisie(id);
        // On écrit sans attendre : si l'écriture échoue, on perd la mémoire du
        // choix au prochain lancement, pas le choix lui-même.
        if (cle) void AsyncStorage.setItem(cle, id);
      },
      chargement,
      erreur,
      recharger,
    }),
    [classes, enCours, classe, chargement, erreur, recharger, cle],
  );

  return <Contexte.Provider value={valeur}>{children}</Contexte.Provider>;
}

export function useClasse(): EtatClasse {
  const valeur = useContext(Contexte);
  if (!valeur) throw new Error('useClasse doit être appelé sous FournisseurClasse.');
  return valeur;
}
