import { Platform } from 'react-native';

/**
 * Le paywall lui-même est un écran maison (`app/abonnement.tsx`) : il colle à
 * la charte et se change sans release store. On garde en revanche le Customer
 * Center natif de RevenueCat, qui rend gratuitement des choses coûteuses à
 * refaire à la main (gérer, restaurer, demander un remboursement, résilier, et
 * les liens profonds vers l'App Store / le Play Store). Il ne dépend d'aucun
 * paywall : il marche dès que le SDK est configuré et le Customer Center activé
 * dans le tableau de bord.
 *
 * ⚠️ Le jour où l'on voudra de l'A/B testing sur le paywall (Experiments
 * RevenueCat), on remplacera la navigation vers l'écran maison par
 * `RevenueCatUI.presentPaywall(...)` ici, sans toucher au reste : toute la
 * logique d'achat vit déjà dans le fournisseur d'abonnement.
 */
export async function ouvrirEspaceClient(): Promise<void> {
  // `react-native-purchases-ui` est un module strictement natif, sans build web.
  // On le charge donc paresseusement (jamais à l'import du module, pour ne pas
  // casser l'écran Réglages sur le web) et seulement hors web. Sur le web, le
  // Customer Center n'existe pas : on ne fait rien (le bouton n'y mène jamais,
  // `abonne` étant toujours faux sans SDK configuré).
  if (Platform.OS === 'web') return;
  const RevenueCatUI = require('react-native-purchases-ui').default;
  await RevenueCatUI.presentCustomerCenter();
}
