import { Feather } from '@expo/vector-icons';
import { Image } from 'expo-image';
import { useMemo, useState } from 'react';
import { ActivityIndicator, Alert, Modal, Platform, Pressable, StyleSheet, Text, View } from 'react-native';

import { Presse } from '@/components/presse';
import { langue, t } from '@/i18n';
import {
  choisirPhoto,
  joindrePhotoActivite,
  listerMediasActivite,
  prendrePhoto,
  retirerMediaActivite,
  type ActivityMedia,
  type ImageChoisie,
} from '@/lib/activity-media';
import { useRequete } from '@/lib/requete';
import { espace, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * Les vignettes des photos jointes à une activité.
 *
 * 🚨 Sans elles, la photo qu'une enseignante joint disparaissait : elle « charge »
 * la photo mais ne la revoit jamais sur la séance. C'est le pendant lecture de la
 * section « Photos » de l'écran de clôture.
 *
 * En mode `editable` (la fiche de SA leçon), on ajoute deux gestes très demandés
 * (retours Mahé, Sophie) : **retirer** une photo (souvent celle de la prépa qui
 * restait) et **ajouter** deux-trois photos de l'activité réalisée (le jeu, la
 * récitation). La source (`activity_media`) et le plafond (6) sont côté base.
 *
 * En lecture seule (défaut), rien ne s'affiche tant qu'il n'y a pas d'image.
 */

/** Libellés locaux (autonomes, pas dans le catalogue i18n partagé). */
const L: Record<
  'fr' | 'nl',
  {
    ajouter: string;
    source: string;
    prendre: string;
    album: string;
    annuler: string;
    retirerTitre: string;
    retirer: string;
    erreurMax: string;
    erreur: string;
    groupePrepa: string;
    groupeRealise: string;
  }
> = {
  fr: {
    ajouter: 'Ajouter',
    source: 'Ajouter une photo',
    prendre: 'Prendre une photo',
    album: 'Choisir dans l’album',
    annuler: 'Annuler',
    retirerTitre: 'Retirer cette photo ?',
    retirer: 'Retirer',
    erreurMax: 'Tu as atteint le maximum de photos pour cette séance.',
    erreur: 'La photo n’a pas pu être ajoutée. Réessaie.',
    groupePrepa: 'Ta préparation',
    groupeRealise: 'La séance réalisée',
  },
  nl: {
    ajouter: 'Toevoegen',
    source: 'Een foto toevoegen',
    prendre: 'Een foto nemen',
    album: 'Uit het album kiezen',
    annuler: 'Annuleren',
    retirerTitre: 'Deze foto verwijderen?',
    retirer: 'Verwijderen',
    erreurMax: 'Je hebt het maximum aantal foto’s voor deze les bereikt.',
    erreur: 'De foto kon niet worden toegevoegd. Probeer opnieuw.',
    groupePrepa: 'Je voorbereiding',
    groupeRealise: 'De gegeven les',
  },
};

export function VignettesActivite({
  activiteId,
  taille = 84,
  etiquette = true,
  editable = false,
}: {
  activiteId: string;
  /** Côté de la tuile en points. */
  taille?: number;
  /** Affiche le libellé « Traces de la séance » au-dessus de la rangée. */
  etiquette?: boolean;
  /** Autorise l'ajout et le retrait de photos (la fiche de sa propre leçon). */
  editable?: boolean;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const l = L[langue] ?? L.fr;
  const [agrandie, setAgrandie] = useState<string | null>(null);
  const [occupe, setOccupe] = useState(false);

  const medias = useRequete(() => listerMediasActivite(activiteId), [activiteId]);
  const photos = medias.donnees ?? [];

  async function ajouterAvec(source: () => Promise<ImageChoisie | null>) {
    try {
      const image = await source();
      if (!image) return;
      setOccupe(true);
      await joindrePhotoActivite(activiteId, image);
      medias.recharger();
    } catch (e) {
      const msg = e instanceof Error && /maximum/i.test(e.message) ? l.erreurMax : l.erreur;
      Alert.alert(msg);
    } finally {
      setOccupe(false);
    }
  }

  function ajouter() {
    if (Platform.OS === 'web') {
      void ajouterAvec(choisirPhoto);
      return;
    }
    Alert.alert(l.source, undefined, [
      { text: l.prendre, onPress: () => void ajouterAvec(prendrePhoto) },
      { text: l.album, onPress: () => void ajouterAvec(choisirPhoto) },
      { text: l.annuler, style: 'cancel' },
    ]);
  }

  function supprimer(photo: ActivityMedia) {
    Alert.alert(l.retirerTitre, undefined, [
      { text: l.annuler, style: 'cancel' },
      {
        text: l.retirer,
        style: 'destructive',
        onPress: async () => {
          try {
            setOccupe(true);
            await retirerMediaActivite(photo);
            medias.recharger();
          } catch {
            Alert.alert(l.erreur);
          } finally {
            setOccupe(false);
          }
        },
      },
    ]);
  }

  const prepa = photos.filter((p) => p.kind === 'preparation');
  const realise = photos.filter((p) => p.kind !== 'preparation');

  // Rien à montrer : en lecture seule sans photo, aucun trou. En mode éditable, on
  // garde au moins le groupe « séance réalisée » avec sa tuile « Ajouter ».
  if (photos.length === 0 && !editable) return null;

  const vignette = (photo: ActivityMedia) => (
    <View key={photo.id} style={[styles.tuile, { width: taille, height: taille }]}>
      <Presse
        accessibilityRole="button"
        accessibilityLabel={t.medias.ouvrir}
        onPress={() => setAgrandie(photo.url)}
        style={styles.image}>
        <Image source={{ uri: photo.url }} style={styles.image} contentFit="cover" />
      </Presse>
      {editable ? (
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={l.retirerTitre}
          onPress={() => supprimer(photo)}
          disabled={occupe}
          hitSlop={6}
          style={styles.suppr}>
          <Feather name="x" size={14} color="#FFFFFF" />
        </Pressable>
      ) : null}
    </View>
  );

  const tuileAjout = (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={l.source}
      onPress={ajouter}
      disabled={occupe}
      style={[styles.ajout, { width: taille, height: taille }]}>
      {occupe ? (
        <ActivityIndicator color={c.action[1]} />
      ) : (
        <>
          <Feather name="plus" size={20} color={c.action[1]} />
          <Text style={styles.ajoutTexte}>{l.ajouter}</Text>
        </>
      )}
    </Pressable>
  );

  return (
    <View style={styles.bloc}>
      {/* Deux groupes distincts : la préparation (photos jointes à la création) et
          la séance réalisée (ajoutée ensuite). On peut retirer l'une pour montrer
          l'autre (retours Sophie, Mahé). L'ajout se fait dans « la séance réalisée ». */}
      {prepa.length > 0 ? (
        <View style={styles.groupe}>
          {etiquette ? <Text style={styles.etiquette}>{l.groupePrepa}</Text> : null}
          <View style={styles.rangee}>{prepa.map(vignette)}</View>
        </View>
      ) : null}

      {realise.length > 0 || editable ? (
        <View style={styles.groupe}>
          {etiquette ? <Text style={styles.etiquette}>{l.groupeRealise}</Text> : null}
          <View style={styles.rangee}>
            {realise.map(vignette)}
            {editable ? tuileAjout : null}
          </View>
        </View>
      ) : null}

      {/* Un tap ouvre la photo en grand. La croix reste fixe, hors de tout
          défilement : elle est toujours atteignable. */}
      <Modal
        visible={agrandie !== null}
        transparent
        animationType="fade"
        onRequestClose={() => setAgrandie(null)}>
        <View style={styles.voile}>
          <Pressable
            accessibilityRole="button"
            accessibilityLabel={t.medias.fermer}
            onPress={() => setAgrandie(null)}
            style={styles.croix}>
            <Feather name="x" size={22} color="#FFFFFF" />
          </Pressable>
          <Pressable style={styles.zoomFond} onPress={() => setAgrandie(null)}>
            {agrandie ? (
              <Image source={{ uri: agrandie }} style={styles.imageGrande} contentFit="contain" />
            ) : null}
          </Pressable>
        </View>
      </Modal>
    </View>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    bloc: { gap: espace.md },
    groupe: { gap: espace.sm },
    etiquette: { fontFamily: police.corps, fontSize: 14, color: c.encreDouce },
    rangee: { flexDirection: 'row', flexWrap: 'wrap', gap: espace.sm },
    tuile: {
      borderRadius: rayon.tuile,
      overflow: 'hidden',
      borderWidth: 1,
      borderColor: c.bord,
    },
    image: { width: '100%', height: '100%' },
    // La croix de retrait, en pastille sombre au coin de la vignette : lisible sur
    // n'importe quelle photo, toujours au même endroit.
    suppr: {
      position: 'absolute',
      top: 3,
      right: 3,
      width: 22,
      height: 22,
      borderRadius: 11,
      backgroundColor: 'rgba(23, 22, 34, 0.72)',
      alignItems: 'center',
      justifyContent: 'center',
    },
    // La tuile d'ajout : bordure tiretée, plus discrète qu'une photo.
    ajout: {
      borderRadius: rayon.tuile,
      borderWidth: 1.5,
      borderStyle: 'dashed',
      borderColor: c.bord,
      alignItems: 'center',
      justifyContent: 'center',
      gap: 2,
      backgroundColor: c.fond,
    },
    ajoutTexte: { fontFamily: police.accent, fontSize: 11, color: c.action[1] },
    // Le plein écran vit sur un voile d'encre sombre, indépendant du thème : une
    // photo se regarde sur du noir, clair ou sombre.
    voile: { flex: 1, backgroundColor: 'rgba(10, 9, 15, 0.94)' },
    zoomFond: { flex: 1, alignItems: 'center', justifyContent: 'center', padding: espace.lg },
    imageGrande: { width: '100%', height: '100%' },
    croix: {
      position: 'absolute',
      top: espace.xl + espace.md,
      right: espace.lg,
      zIndex: 2,
      width: 44,
      height: 44,
      borderRadius: 22,
      backgroundColor: 'rgba(23, 22, 34, 0.72)',
      alignItems: 'center',
      justifyContent: 'center',
    },
  });
