import AsyncStorage from '@react-native-async-storage/async-storage';

/**
 * Le drapeau du tour d'introduction.
 *
 * 🔑 Le tour ne se montre qu'UNE fois, à un arrivant NON connecté, AVANT la
 * connexion. Un seul drapeau dans AsyncStorage suffit : ce n'est pas une donnée
 * de compte (on n'est pas encore connecté quand on le pose), c'est une marque
 * d'appareil. Se déconnecter ne le remet donc pas à zéro : quelqu'un qui a déjà
 * vu le tour et qui se déconnecte retombe sur la connexion, pas sur le tour.
 *
 * ⚠️ En cas de lecture qui échoue, on considère le tour comme DÉJÀ VU. Le pire
 * des défauts serait de piéger quelqu'un dans un tour qu'il ne peut pas passer
 * parce que le stockage répond mal : mieux vaut le laisser filer vers la
 * connexion. Le tour est un bonus, jamais une porte.
 */
const CLE = 'educooo:intro-vu';

/**
 * La version du tour. 🔑 On l'incrémente à CHAQUE mise à jour du tour : tout le
 * monde le revoit alors une fois, même les comptes déjà créés qui avaient vu la
 * version précédente. C'est la demande explicite — « dès que le tour change,
 * tout le monde le revoit au moins une fois ». La comparaison se fait sur la
 * version stockée, plus sur la simple présence d'un drapeau.
 */
export const VERSION_INTRO = 3;

export async function aVuIntro(): Promise<boolean> {
  try {
    const brut = await AsyncStorage.getItem(CLE);
    if (brut === null) return false;
    // Ancien format (une date ISO posée par les premières versions) = tour vu en
    // version 1. On le lit comme tel pour que la mise à jour le remontre.
    const version = /^\d+$/.test(brut) ? parseInt(brut, 10) : 1;
    return version >= VERSION_INTRO;
  } catch {
    return true;
  }
}

export async function marquerIntroVue(): Promise<void> {
  try {
    await AsyncStorage.setItem(CLE, String(VERSION_INTRO));
  } catch {
    // Silencieux : ne pas voir le tour une fois de plus est sans gravité, et on
    // ne veut pas faire échouer le passage vers la connexion pour si peu.
  }
}
