import { Feather } from '@expo/vector-icons';
import { router } from 'expo-router';
import { useMemo, useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, Text, View } from 'react-native';

import { Carte } from '@/components/ecran';
import { SousEcran } from '@/components/sous-ecran';
import { Alerte, BoutonPrincipal, Champ, PaireBoutons, Pastilles } from '@/components/formulaire';
import { t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import { aRangerParEleve, creerEleve, elevesDe, nomAffiche } from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, ombre, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * La classe : qui est là, et par où entrer dans une fiche.
 *
 * Volontairement pauvre en fonctions. Ce que fait une enseignante ici, c'est
 * chercher quelqu'un pour voir où il en est ; tout le reste (modifier, archiver,
 * les besoins spécifiques) se fait rarement et peut vivre dans la fiche.
 */
export default function MaClasse() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { classe, enCours } = useClasse();
  const classeId = classe?.id ?? null;

  const [recherche, setRecherche] = useState('');
  const [ajoutOuvert, setAjoutOuvert] = useState(false);
  const [prenom, setPrenom] = useState('');
  const [initiale, setInitiale] = useState('');
  // La classe cible de l'ajout : par défaut la classe active, mais on peut la
  // choisir explicitement (retour Sophie : lier l'élève à une classe précise).
  const [classeCible, setClasseCible] = useState<string | null>(classeId);
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);

  // On inclut les inactifs (élèves partis) : ils restent visibles, grisés, en
  // bas de liste, pour pouvoir les rouvrir et les réactiver au besoin.
  const eleves = useRequete(() => elevesDe(classeId!, true), [classeId], { actif: !!classeId });
  const aRanger = useRequete(() => aRangerParEleve(classeId!), [classeId], { actif: !!classeId });
  // Les actifs d'abord, les inactifs (partis) en bas — l'ordre alpha à l'intérieur
  // est déjà celui de la requête.
  const liste = [...(eleves.donnees ?? [])].sort((a, b) => Number(b.actif) - Number(a.actif));

  const filtres = useMemo(() => {
    const terme = recherche.trim().toLowerCase();
    if (!terme) return liste;
    return liste.filter((e) => nomAffiche(e).toLowerCase().includes(terme));
  }, [liste, recherche]);

  async function ajouter() {
    const cible = classeCible ?? classeId;
    if (!cible) return;
    setErreur(null);
    setOccupe(true);
    try {
      await creerEleve({ classeId: cible, prenom, initialeNom: initiale });
      setPrenom('');
      setInitiale('');
      setAjoutOuvert(false);
      eleves.recharger();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.classe.erreurAjout);
    } finally {
      setOccupe(false);
    }
  }

  return (
    <SousEcran titre={t.classe.titre}>
      {eleves.erreur ? <Alerte message={t.classe.erreur} /> : null}

        {liste.length > 3 ? (
          <Champ
            value={recherche}
            onChangeText={setRecherche}
            placeholder={t.classe.recherche}
            autoCorrect={false}
            autoCapitalize="none"
          />
        ) : null}

        {eleves.chargement ? (
          <View style={styles.attente}>
            <ActivityIndicator color={c.encreDouce} />
          </View>
        ) : null}

        {!eleves.chargement && liste.length === 0 ? (
          <Carte>
            <Text style={texte.discret}>{t.classe.aucun}</Text>
          </Carte>
        ) : null}

        {!eleves.chargement && liste.length > 0 && filtres.length === 0 ? (
          <Carte>
            <Text style={texte.discret}>{t.classe.aucunResultat}</Text>
          </Carte>
        ) : null}

        {filtres.map((e) => {
          const enAttente = aRanger.donnees?.get(e.id) ?? 0;
          // 🚨 Les besoins **cochés** seulement, jamais le besoin libre.
          //
          // En base, ce champ contient « 22Q11. Psychomotricité faible » et une
          // phrase qui nomme un enfant et énonce sa maladie. Afficher ça dans
          // une liste qui défile, sur une tablette posée dans une classe, c'est
          // le montrer à un parent, à une collègue ou à un autre enfant qui
          // passe derrière. Et tronqué à une ligne, ça n'apprend rien d'utile.
          //
          // Il reste sur la fiche de l'élève, où l'ouvrir est un geste
          // délibéré. Même logique que pour ce qui part vers le modèle : le
          // champ libre est celui dont on ne peut rien garantir.
          const marques = e.actif ? e.besoins : [t.classe.inactif, ...e.besoins];
          return (
            <Pressable
              key={e.id}
              accessibilityRole="button"
              // Sans nom accessible, un lecteur d'écran annonce « bouton » et
              // rien d'autre. Une carte cliquable en porte toujours un.
              accessibilityLabel={
                enAttente > 0
                  ? `${nomAffiche(e)}, ${t.classe.enAttente(enAttente)}`
                  : nomAffiche(e)
              }
              onPress={() => router.push({ pathname: '/classe/[id]', params: { id: e.id } })}>
              <Carte compacte>
                <View style={[styles.ligne, !e.actif && styles.ligneInactive]}>
                  {/* Une pastille d'initiale plutôt qu'un avatar : pas d'image à
                      générer, pas de fichier à stocker, et ça reste lisible. */}
                  <View style={styles.jeton}>
                    <Text style={styles.initiale}>{e.prenom.slice(0, 1).toUpperCase()}</Text>
                  </View>
                  <View style={styles.corps}>
                    <Text style={texte.corps}>{nomAffiche(e)}</Text>
                    {enAttente > 0 || marques.length ? (
                      <Text style={texte.discret} numberOfLines={1}>
                        {[enAttente > 0 ? t.classe.enAttente(enAttente) : null, ...marques]
                          .filter(Boolean)
                          .join(' · ')}
                      </Text>
                    ) : null}
                  </View>
                  {/* Gris tant que ce n'est pas rangé : la règle de la charte. */}
                  {enAttente > 0 ? <View style={styles.pointAttente} /> : null}
                  <Feather name="chevron-right" size={20} color={c.nonRattache} />
                </View>
              </Carte>
            </Pressable>
          );
        })}

        {ajoutOuvert ? (
          <Carte>
            {enCours.length > 1 ? (
              <Pastilles
                etiquette={t.classe.classeCible}
                options={enCours.map((cl) => ({ id: cl.id, libelle: cl.nom }))}
                choisi={classeCible ?? classeId}
                onChoisir={setClasseCible}
              />
            ) : null}
            <Champ
              etiquette={t.classe.prenom}
              value={prenom}
              onChangeText={setPrenom}
              placeholder={t.classe.prenomIndice}
              autoCorrect={false}
              autoFocus
              editable={!occupe}
            />
            <Champ
              etiquette={t.classe.initiale}
              value={initiale}
              onChangeText={(v) => setInitiale(v.slice(0, 2))}
              placeholder={t.classe.initialeIndice}
              autoCorrect={false}
              maxLength={2}
              editable={!occupe}
            />
            <Text style={styles.pourquoi}>{t.classe.initialePourquoi}</Text>
            {erreur ? <Alerte message={erreur} /> : null}
            {/* Ajouter + Annuler sur une seule ligne (retour Valentin 24/08) :
                principal en miel à droite, secondaire à cadre à gauche. */}
            <PaireBoutons
              principal={{
                libelle: t.classe.enregistrer,
                onPress: ajouter,
                occupe,
                inactif: !prenom.trim(),
              }}
              secondaire={{ libelle: t.commun.annuler, onPress: () => setAjoutOuvert(false) }}
            />
          </Carte>
        ) : (
          <BoutonPrincipal
            libelle={t.classe.ajouter}
            onPress={() => {
              setClasseCible(classeId);
              setAjoutOuvert(true);
            }}
          />
        )}

        {/* La classe est ce qui se transmet en juin : un pont discret vers la
            passation, en bas, là où l'année se projette vers la suivante. */}
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={t.passation.titre}
          onPress={() => router.push('/passation')}>
          <Carte compacte>
            <View style={styles.ligne}>
              <View style={styles.jetonPont}>
                <Feather name="arrow-right-circle" size={19} color={c.actif} />
              </View>
              <View style={styles.corps}>
                <Text style={texte.corps}>{t.passation.titre}</Text>
                <Text style={texte.discret}>{t.classe.versPassation}</Text>
              </View>
              <Feather name="chevron-right" size={20} color={c.nonRattache} />
            </View>
          </Carte>
        </Pressable>
    </SousEcran>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  attente: { paddingVertical: espace.xl, alignItems: 'center' },
  ligne: { flexDirection: 'row', gap: espace.md, alignItems: 'center' },
  ligneInactive: { opacity: 0.5 },
  pointAttente: {
    width: 8,
    height: 8,
    borderRadius: 4,
    backgroundColor: c.nonRattache,
  },
  jeton: {
    width: 38,
    height: 38,
    borderRadius: rayon.tuile,
    backgroundColor: c.fond,
    alignItems: 'center',
    justifyContent: 'center',
    ...ombre.carte,
  },
  jetonPont: {
    width: 38,
    height: 38,
    borderRadius: rayon.tuile,
    backgroundColor: c.actionTeinte,
    alignItems: 'center',
    justifyContent: 'center',
  },
  initiale: { fontFamily: police.titre, fontSize: 16, color: c.encre },
  corps: { flex: 1, gap: espace.xs },
  pourquoi: { fontFamily: police.corps, fontSize: 13, color: c.encreDouce, lineHeight: 18 },
});
