import { useMemo } from 'react';
import { StyleSheet, Text, View } from 'react-native';

import { langue } from '@/i18n';
import type { AbsenceProf, TypeAbsence } from '@/lib/donnees';
import { police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/** Le libellé court d'un motif, en local (règle studio i18n, comme TAG_COLLEGUE). */
const MOTIFS: Record<'fr' | 'nl', Record<TypeAbsence, string>> = {
  fr: {
    maladie: '🤒 Malade',
    reunion: '👥 Réunion',
    conference: '🎓 Formation',
    conges_scolaires: '🏖️ Congé',
    autre: '🚪 Absent·e',
  },
  nl: {
    maladie: '🤒 Ziek',
    reunion: '👥 Vergadering',
    conference: '🎓 Opleiding',
    conges_scolaires: '🏖️ Verlof',
    autre: '🚪 Afwezig',
  },
};
const DEMI = {
  fr: { matin: 'matin', apresmidi: 'après-midi' },
  nl: { matin: 'ochtend', apresmidi: 'namiddag' },
};

/** « 🤒 Malade · matin ». */
export function libelleAbsence(a: AbsenceProf): string {
  const l = langue === 'nl' ? 'nl' : 'fr';
  const motif = MOTIFS[l][a.type];
  return a.demiJournee ? `${motif} · ${DEMI[l][a.demiJournee]}` : motif;
}

/**
 * La marque d'absence posée sur un jour (en-tête de colonne du semainier, vue
 * jour, fil du journal). Retour Sophie 24/09 : déclarer « maladie » récupérait
 * bien les activités, mais rien ne disait ensuite que ce jour-là elle était
 * malade. La semaine doit raconter le réel, pas seulement le prévu.
 */
export function BadgeAbsence({ absences, compact = false }: { absences: AbsenceProf[]; compact?: boolean }) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  if (!absences.length) return null;
  return (
    <View style={styles.rangee}>
      {absences.map((a) => (
        <View key={a.id} style={[styles.badge, compact && styles.badgeCompact]}>
          <Text style={[styles.texte, compact && styles.texteCompact]} numberOfLines={1}>
            {libelleAbsence(a)}
          </Text>
        </View>
      ))}
    </View>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    rangee: { flexDirection: 'row', flexWrap: 'wrap', gap: 4, justifyContent: 'center' },
    badge: {
      paddingHorizontal: 10,
      paddingVertical: 4,
      borderRadius: rayon.pastille,
      backgroundColor: c.actionTeinte,
      borderWidth: 1,
      borderColor: c.action[1],
    },
    badgeCompact: { paddingHorizontal: 6, paddingVertical: 2 },
    texte: { fontFamily: police.accent, fontSize: 13, color: c.encre },
    texteCompact: { fontSize: 11 },
  });
