import { View } from 'react-native';
import Svg, {
  Circle,
  Defs,
  G,
  LinearGradient,
  Path,
  Rect,
  Stop,
  Text as SvgText,
} from 'react-native-svg';

import { t } from '@/i18n';
import { police } from '@/theme/tokens';

/**
 * Un trophée d'étape, dessiné en react-native-svg.
 *
 * 🔑 On NE charge PAS les .svg d'`assets/trophees` : il n'y a pas de
 * svg-transformer dans le projet, donc un `import` de .svg ne rend rien. On
 * réplique ici la géométrie et les couleurs de la source (voir
 * `assets/trophees/etape-1.svg` et sa variante verrouillée, dont ce composant
 * est le portage fidèle) : hexagone pointe en haut aux ANGLES ARRONDIS (identité
 * arrondie EducooO), jante en dégradé d'action, corps encre, numéro centré, et
 * le CHAPEAU EducooO (la marque, en couleur) dans la zone haute — entre la jante
 * et le numéro. La variante verrouillée passe en gris et ajoute un cadenas, et
 * le chapeau y est grisé, comme la source.
 *
 * Les deux `d=` d'hexagone (jante / corps) sont copiés tels quels depuis le SVG
 * généré par `assets/trophees/generer.mjs` (roundedHexPath, R_OUT=80 / R_IN=68,
 * arrondi 0.2·r) : les deux surfaces restent ainsi identiques au pixel.
 *
 * Les identifiants de dégradé sont uniques par instance (palier + variante) :
 * plusieurs trophées coexistent à l'écran, et des `id` partagés se marcheraient
 * dessus.
 */

// Hexagones aux sommets arrondis, copiés du SVG généré (viewBox 200×210).
const HEX_JANTE =
  'M 113.86 46 Q 100 38 86.14 46 L 44.57 70 Q 30.72 78 30.72 94 L 30.72 142 Q 30.72 158 44.57 166 L 86.14 190 Q 100 198 113.86 190 L 155.43 166 Q 169.28 158 169.28 142 L 169.28 94 Q 169.28 78 155.43 70 Z';
const HEX_CORPS =
  'M 111.78 56.8 Q 100 50 88.22 56.8 L 52.89 77.2 Q 41.11 84 41.11 97.6 L 41.11 138.4 Q 41.11 152 52.89 158.8 L 88.22 179.2 Q 100 186 111.78 179.2 L 147.11 158.8 Q 158.89 152 158.89 138.4 L 158.89 97.6 Q 158.89 84 147.11 77.2 Z';

// Le chapeau EducooO (silhouette de la marque), même transform que le SVG.
const CHAPEAU_TRANSFORM = 'translate(100,54) scale(0.36) translate(-60,-13)';
const CHAPEAU_PLATEAU = 'M60 13 L116 38 L60 60 L4 38 Z';
const CHAPEAU_CALOTTE = 'M33 46 L33 66 C33 82 45 90 60 90 C75 90 87 82 87 66 L87 46 L60 58 Z';
const CHAPEAU_CORDON = 'M114 38 C121 48 120 60 115 69';

const PALETTE = {
  obtenu: {
    jante: ['#FFB03A', '#FF7A59'],
    corps: ['#211F2E', '#17161F'],
    chapeau: ['#FFC46A', '#F2A03C'],
    numero: '#FFFFFF',
    numeroOpacite: 1,
    numeroY: 118,
  },
  verrouille: {
    jante: ['#C7C5D2', '#9A98A8'],
    corps: ['#2E2C3A', '#211F2E'],
    chapeau: ['#B6B4C4', '#8E8C9C'],
    numero: '#B6B4C4',
    numeroOpacite: 0.55,
    // Remonté pour laisser la place au cadenas, comme dans la source verrouillée.
    numeroY: 112,
  },
} as const;

export function Trophee({
  palier,
  obtenu,
  taille = 96,
}: {
  palier: number;
  obtenu: boolean;
  /** Largeur en points. La hauteur suit le ratio 200×210 de la source. */
  taille?: number;
}) {
  const variante = obtenu ? 'obtenu' : 'verrouille';
  const p = PALETTE[variante];
  const uid = `troph-${palier}-${variante}`;
  const largeur = taille;
  const hauteur = (taille * 210) / 200;

  return (
    <View
      accessibilityRole="image"
      accessibilityLabel={
        obtenu ? t.moi.tropheeObtenu(palier) : t.moi.tropheeVerrouille(palier)
      }>
      <Svg width={largeur} height={hauteur} viewBox="0 0 200 210">
        <Defs>
          <LinearGradient id={`${uid}-jante`} x1="0" y1="0" x2="1" y2="1">
            <Stop offset="0" stopColor={p.jante[0]} />
            <Stop offset="1" stopColor={p.jante[1]} />
          </LinearGradient>
          <LinearGradient id={`${uid}-corps`} x1="0" y1="0" x2="0" y2="1">
            <Stop offset="0" stopColor={p.corps[0]} />
            <Stop offset="1" stopColor={p.corps[1]} />
          </LinearGradient>
          <LinearGradient id={`${uid}-chapeau`} x1="0" y1="0" x2="0" y2="1">
            <Stop offset="0" stopColor={p.chapeau[0]} />
            <Stop offset="1" stopColor={p.chapeau[1]} />
          </LinearGradient>
          <LinearGradient id={`${uid}-lustre`} x1="0" y1="0" x2="0" y2="1">
            <Stop offset="0" stopColor="#FFFFFF" stopOpacity={0.14} />
            <Stop offset="0.55" stopColor="#FFFFFF" stopOpacity={0} />
          </LinearGradient>
        </Defs>

        {/* Jante : hexagone plein aux angles arrondis (dégradé d'action, ou gris). */}
        <Path d={HEX_JANTE} fill={`url(#${uid}-jante)`} />
        {/* Corps : hexagone intérieur encre, puis un lustre discret par-dessus. */}
        <Path d={HEX_CORPS} fill={`url(#${uid}-corps)`} />
        <Path d={HEX_CORPS} fill={`url(#${uid}-lustre)`} />

        {/* Le numéro du palier. */}
        <SvgText
          x={100}
          y={p.numeroY}
          fill={p.numero}
          fillOpacity={p.numeroOpacite}
          fontFamily={police.titre}
          fontWeight="800"
          fontSize={66}
          textAnchor="middle"
          alignmentBaseline="central">
          {palier}
        </SvgText>

        {/* Le cadenas, seulement verrouillé. */}
        {!obtenu ? (
          <G transform="translate(100,150)">
            <Path
              d="M -8 -3 v -5 a 8 8 0 0 1 16 0 v 5"
              fill="none"
              stroke="#D7D5DF"
              strokeWidth={4.5}
              strokeLinecap="round"
            />
            <Rect x={-13} y={-3} width={26} height={20} rx={5} fill="#D7D5DF" />
            <Circle cx={0} cy={5} r={2.6} fill="#211F2E" />
            <Rect x={-1.4} y={6} width={2.8} height={6} rx={1.4} fill="#211F2E" />
          </G>
        ) : null}

        {/* Le chapeau EducooO, dans la zone haute (entre la jante et le numéro). */}
        <G transform={CHAPEAU_TRANSFORM} fill={`url(#${uid}-chapeau)`}>
          <Path d={CHAPEAU_PLATEAU} />
          <Path d={CHAPEAU_CALOTTE} />
          <Path
            d={CHAPEAU_CORDON}
            fill="none"
            stroke={`url(#${uid}-chapeau)`}
            strokeWidth={6.5}
            strokeLinecap="round"
          />
          <Rect x={108.5} y={67} width={13} height={27} rx={6.5} />
        </G>
      </Svg>
    </View>
  );
}
