import NetInfo, { type NetInfoState } from '@react-native-community/netinfo';
import { useEffect, useState } from 'react';
import { Platform } from 'react-native';

// 🌐 Sur le web, NetInfo teste l'accès Internet en interrogeant en boucle une URL
// de « joignabilité » (par défaut l'origine du site). Sur GitHub Pages, cette
// URL répond 404 : la détection marche quand même (une réponse HTTP prouve
// qu'on est en ligne), mais la console se remplit de 404 rouges qui font croire
// à une app cassée. Sur le web, `navigator.onLine` (porté par `isConnected`)
// suffit à notre logique optimiste. On coupe donc le sondage HTTP hors natif. Le
// natif n'appelle jamais `configure` ici : son comportement est strictement inchangé.
//
// 🔴 PIÈGE CORRIGÉ (28/08) : quand `reachabilityShouldRun` renvoie false,
// l'implémentation web de NetInfo ne laisse PAS `isInternetReachable` à `null`,
// elle le force à **`false`** (voir internetReachability.ts, branche `else` de
// `_setExpectsConnection`). Traité naïvement, ça faisait croire l'app HORS-LIGNE
// EN PERMANENCE sur le web : toute capture partait dans la file d'attente au lieu
// d'être écrite en base, et la file ne se rejouait jamais (le rejeu se garde
// aussi sur `estEnLigne`). D'où « c'est noté » sans jamais retrouver l'obs.
// La parade : sur le web, on IGNORE `isInternetReachable` et on ne se fie qu'à
// `isConnected` (= `navigator.onLine`). Voir `enLigneDepuis`.
if (Platform.OS === 'web') {
  NetInfo.configure({ reachabilityShouldRun: () => false });
}

/**
 * L'état du réseau, une seule lecture pour toute l'app.
 *
 * Le filet minimal hors-ligne repose sur une question simple : « peut-on
 * espérer qu'une requête parte ? ». On répond de façon **optimiste** : tant que
 * l'appareil est connecté à un réseau et que rien ne prouve qu'Internet est
 * injoignable, on tente. Si la requête échoue quand même pour une raison réseau,
 * la couche d'écriture (`donnees.ts`) enfile l'observation plutôt que de la
 * perdre — donc être trop optimiste ici ne coûte jamais une donnée, ça coûte au
 * pire un aller-retour raté qui bascule ensuite en file.
 *
 * `isInternetReachable` peut valoir `null` (état encore inconnu au démarrage) :
 * on le traite comme « en ligne » pour ne jamais bloquer une capture à tort.
 */
function enLigneDepuis(etat: NetInfoState): boolean {
  // Sur le web, `isInternetReachable` est forcé à `false` par NetInfo dès qu'on
  // coupe le sondage (voir le bloc `configure` ci-dessus) : on ne s'y fie donc
  // pas, seul `isConnected` (= `navigator.onLine`) compte. Sinon l'app se croit
  // hors-ligne à vie et n'écrit plus rien.
  if (Platform.OS === 'web') return etat.isConnected !== false;
  return etat.isConnected !== false && etat.isInternetReachable !== false;
}

/**
 * Vérifie l'état du réseau à la demande, sans hook. Sert au chemin d'écriture,
 * qui a besoin de décider « tenter le réseau ou enfiler » au moment précis de la
 * capture, pas de réagir à un état React.
 */
export async function estEnLigne(): Promise<boolean> {
  try {
    const etat = await NetInfo.fetch();
    return enLigneDepuis(etat);
  } catch {
    // Si on n'arrive même pas à interroger NetInfo, on reste optimiste : on
    // tentera le réseau et, en cas d'échec, la file prendra le relais.
    return true;
  }
}

/**
 * S'abonne aux **retours** en ligne : le callback n'est appelé que sur la
 * transition hors-ligne → en ligne, jamais sur l'inverse. C'est exactement le
 * moment où l'on veut rejouer la file d'attente. Renvoie une fonction de
 * désabonnement.
 */
export function surRetourEnLigne(rappel: () => void): () => void {
  let etaitEnLigne: boolean | null = null;
  return NetInfo.addEventListener((etat) => {
    const maintenant = enLigneDepuis(etat);
    if (etaitEnLigne === false && maintenant) rappel();
    etaitEnLigne = maintenant;
  });
}

/**
 * L'état réseau réactif, pour l'affichage (griser une action, montrer un
 * bandeau « hors-ligne »). On part optimiste (`true`) le temps de la première
 * lecture, pour ne pas afficher « hors-ligne » l'espace d'un instant au
 * démarrage alors que la connexion est là.
 */
export function useEnLigne(): boolean {
  const [enLigne, setEnLigne] = useState(true);

  useEffect(() => {
    let vivant = true;
    NetInfo.fetch().then((etat) => {
      if (vivant) setEnLigne(enLigneDepuis(etat));
    });
    const desabonner = NetInfo.addEventListener((etat) => {
      if (vivant) setEnLigne(enLigneDepuis(etat));
    });
    return () => {
      vivant = false;
      desabonner();
    };
  }, []);

  return enLigne;
}
