import { Feather } from '@expo/vector-icons';
import { router, useFocusEffect } from 'expo-router';
import { useCallback, useMemo } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

import { Carte, EnteteSection } from '@/components/ecran';
import { Tuile } from '@/components/elements';
import { Alerte } from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { VignettesMedias } from '@/components/vignettes-medias';
import { t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import { elevesDe, observationsDe, type Eleve } from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, police, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * La liste « À ranger » : toutes les observations en attente de la classe
 * active, ouvertes depuis la boîte de réception.
 *
 * 🔑 Elle a un vrai domicile depuis que le journal ne déroule plus le fil « ce
 * que tu as capté » (retour Valentin 24/08) : le journal garde les jours de la
 * semaine, ce qui reste à ranger vit ici. Chaque ligne mène au rangement.
 */
export default function ARanger() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;

  const observations = useRequete(() => observationsDe(classeId!, 100), [classeId], {
    actif: !!classeId,
  });
  const eleves = useRequete(() => elevesDe(classeId!), [classeId], { actif: !!classeId });

  useFocusEffect(
    useCallback(() => {
      if (classeId) observations.recharger();
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [classeId]),
  );

  const nomsEleves = useMemo(() => {
    const table = new Map<string, string>();
    for (const e of eleves.donnees ?? ([] as Eleve[])) {
      table.set(e.id, e.initialeNom ? `${e.prenom} ${e.initialeNom}.` : e.prenom);
    }
    return table;
  }, [eleves.donnees]);

  const toutes = observations.donnees ?? [];
  const aRanger = toutes.filter((o) => o.statut === 'pending');
  // Les notes « à suivre » : classées sans attendu, mais gardées en vue. On les
  // retrouve ici, comme le promet le message de rangement, dans une section à
  // part sous ce qui reste à ranger.
  const aSuivre = toutes.filter((o) => o.statut !== 'pending' && o.suivi);

  return (
    <SousEcran titre={t.boite.listeTitre} chargement={observations.chargement}>
      {observations.erreur ? <Alerte message={t.journal.erreur} /> : null}

      {aRanger.length === 0 ? (
        <Carte>
          <Text style={texte.discret}>{t.boite.vide}</Text>
        </Carte>
      ) : (
        aRanger.map((o) => (
          <LigneObservation key={o.id} observation={o} nom={o.eleveId ? nomsEleves.get(o.eleveId) : null} />
        ))
      )}

      {aSuivre.length > 0 ? (
        <>
          <EnteteSection titre={t.ranger.suivi} />
          {aSuivre.map((o) => (
            <LigneObservation
              key={o.id}
              observation={o}
              nom={o.eleveId ? nomsEleves.get(o.eleveId) : null}
              suivi
            />
          ))}
        </>
      ) : null}
    </SousEcran>
  );
}

/** Une observation en ligne : texte, photo éventuelle, élève, et un état. */
function LigneObservation({
  observation: o,
  nom,
  suivi = false,
}: {
  observation: { id: string; texte: string; eleveId: string | null };
  nom: string | null | undefined;
  /** Pour une note « à suivre » : tuile teintée et libellé d'état dédié. */
  suivi?: boolean;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={o.texte || t.boite.aRanger}
      onPress={() => router.push({ pathname: '/ranger/[id]', params: { id: o.id } })}>
      <Carte compacte>
        <View style={styles.ligne}>
          <Tuile icone={suivi ? 'bookmark' : 'edit-3'} moment={suivi ? 'sortie' : undefined} />
          <View style={styles.corps}>
            {o.texte ? (
              <Text style={texte.corps} numberOfLines={2}>
                {o.texte}
              </Text>
            ) : null}
            <VignettesMedias observationId={o.id} taille={48} />
            <Text style={texte.discret}>
              {nom ?? t.journal.sansEleve}
              {' · '}
              {suivi ? t.ranger.suivi : t.etat.nonRattache}
            </Text>
          </View>
          <Feather name="chevron-right" size={20} color={c.nonRattache} />
        </View>
      </Carte>
    </Pressable>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    ligne: { flexDirection: 'row', gap: espace.md, alignItems: 'center' },
    corps: { flex: 1, gap: espace.xs },
  });
