import {
  ParrainagePanneau,
  PARRAINAGE_SOUS_TITRE,
  PARRAINAGE_TITRE,
} from '@/components/parrainage-panneau';
import { SousEcran } from '@/components/sous-ecran';

/**
 * L'écran-route `/parrainage` : il enveloppe le panneau de parrainage dans un
 * `SousEcran` (barre de retour, titre).
 *
 * Le contenu (partage, code, suivi, manne, filleul·es) vit désormais dans le
 * composant partagé `<ParrainagePanneau />`, pour que l'onglet Parrainage de
 * Groupes affiche EXACTEMENT le même écran sans le dupliquer. Cette route reste
 * valide car d'autres points d'entrée y mènent encore.
 */
export default function Parrainage() {
  return (
    <SousEcran titre={PARRAINAGE_TITRE} sousTitre={PARRAINAGE_SOUS_TITRE}>
      <ParrainagePanneau />
    </SousEcran>
  );
}
