import * as AppleAuthentication from 'expo-apple-authentication';
import { useMemo, useRef, useState } from 'react';
import {
  KeyboardAvoidingView,
  Linking,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  View,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { Cloudy } from '@/components/cloudy';
import {
  Alerte,
  BoutonDiscret,
  BoutonPrincipal,
  BoutonSecondaire,
  Champ,
} from '@/components/formulaire';
import { langue, t, type Langue } from '@/i18n';
import type { Reseau } from '@/lib/donnees';
import { ACCUEIL_V2 } from '@/lib/flags';
import { NIVEAUX_FWB } from '@/lib/niveaux';
import { ecrireBrouillonOnboarding } from '@/lib/onboarding';
import { supabase } from '@/lib/supabase';
import { appleDisponible, connexionApple, connexionGoogle, googleDisponible } from '@/lib/social';
import { espace, ombre, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Les libellés du nouvel accueil (`ACCUEIL_V2`) et des ajouts mot de passe.
 * Tenus en local, comme le sélecteur de thème dans les réglages : autonomes,
 * pour ne pas éditer le catalogue i18n partagé (et ses deux langues strictes)
 * pendant que d'autres sessions le migrent. À remonter dans `@/i18n` quand la
 * traduction de l'app se stabilisera. La question reprend mot pour mot celle
 * validée avec Valentin, au point médian (écriture inclusive studio).
 */
const LIB: Record<
  Langue,
  {
    accueilQuestion: string;
    decouvrir: string;
    decouvrirIndice: string;
    dejaCompte: string;
    dejaCompteIndice: string;
    retour: string;
    motDePasseOublie: string;
    recupInfo: string;
  }
> = {
  fr: {
    accueilQuestion: 'Nouveau·elle par ici, ou tu as déjà un compte ?',
    decouvrir: 'Je découvre',
    decouvrirIndice: 'On met ta classe en route ensemble, ton compte se crée à la fin.',
    dejaCompte: 'J’ai déjà un compte',
    dejaCompteIndice: 'Retrouve ta classe et tes leçons.',
    retour: 'Retour',
    motDePasseOublie: 'Mot de passe oublié ?',
    recupInfo:
      'On t’envoie un code de connexion par email. Une fois connecté·e, tu choisis un nouveau mot de passe dans Réglages.',
  },
  nl: {
    accueilQuestion: 'Nieuw hier, of heb je al een account?',
    decouvrir: 'Ik ontdek',
    decouvrirIndice: 'We zetten je klas samen op, je account maak je op het einde aan.',
    dejaCompte: 'Ik heb al een account',
    dejaCompteIndice: 'Vind je klas en je lessen terug.',
    retour: 'Terug',
    motDePasseOublie: 'Wachtwoord vergeten?',
    recupInfo:
      'We sturen je een aanmeldcode per e-mail. Eenmaal aangemeld kies je een nieuw wachtwoord in Instellingen.',
  },
};

/** Les trois réseaux de la FWB, comme sur l'onboarding (`bienvenue`). */
const RESEAUX: { id: Reseau; titre: string; aide: string }[] = [
  { id: 'officiel', titre: t.bienvenue.reseauOfficiel, aide: t.bienvenue.reseauOfficielAide },
  { id: 'libre_confessionnel', titre: t.bienvenue.reseauLibreConf, aide: t.bienvenue.reseauLibreConfAide },
  {
    id: 'libre_non_confessionnel',
    titre: t.bienvenue.reseauLibreNonConf,
    aide: t.bienvenue.reseauLibreNonConfAide,
  },
];

/**
 * La longueur du code est un réglage du serveur (`mailer_otp_length`), pas une
 * constante de l'app. Elle valait 8 pendant que je validais 6, donc personne
 * n'aurait pu se connecter. On accepte une plage : si le réglage change, l'app
 * continue de fonctionner au lieu de refuser un code valide.
 */
const MIN_CODE = 6;
const MAX_CODE = 8;
/** Longueur minimale imposée par le projet Supabase (`password_min_length`). */
const MIN_MOT_DE_PASSE = 6;

// Le WhatsApp du studio pour le tarif de groupe (écoles, équipes). C'est un
// contact commercial, pas le support d'Anne-Charlotte (celui des réglages) :
// une école qui équipe son équipe passe par une conversation, pas par un
// paiement en libre-service.
const WHATSAPP_TARIF_GROUPE = 'https://wa.me/32473122452';
const longueurPlausible = (chiffres: string) =>
  chiffres.length >= MIN_CODE && chiffres.length <= MAX_CODE;

/**
 * Connexion par code à six chiffres, pas par lien magique.
 *
 * Le lien magique oblige à gérer un retour par lien profond, qui se comporte
 * différemment sur le web, sur iOS et sur Android, et qui casse dès qu'une
 * messagerie ouvre le lien dans son propre navigateur. Un code se recopie
 * partout de la même façon.
 *
 * 🔑 ET C'EST CE QUI REMPLACE L'ÉCRAN « MOT DE PASSE OUBLIÉ »
 *
 * L'app héritée en avait un, et il n'est pas porté — volontairement. Le chemin
 * par mot de passe existe encore, discret, parce qu'un examinateur Apple ne
 * reçoit pas nos emails et que des comptes créés dans l'app web en ont un. Mais
 * quelqu'un qui l'oublie n'a rien à récupérer : le bouton « Recevoir un code
 * par email » est sur le même écran, et il ouvre la porte sans rien réinitialiser.
 *
 * Un parcours de récupération en moins, c'est un formulaire de moins où se
 * tromper, un email de plus qui ne part pas, et un jeton de réinitialisation
 * qui n'existe nulle part.
 */
export default function Connexion() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  // Les étapes « accueil », « decouverteNiveau » et « decouverteReseau »
  // n'existent QUE sous `ACCUEIL_V2`. Drapeau éteint, l'étape de départ reste
  // « email » : l'écran s'ouvre exactement comme avant.
  type Etape = 'accueil' | 'decouverteNiveau' | 'decouverteReseau' | 'email' | 'code' | 'motDePasse';
  const [etape, setEtape] = useState<Etape>(ACCUEIL_V2 ? 'accueil' : 'email');
  // « connexion » = quelqu'un qui revient ; « inscription » = le chemin « Je
  // découvre ». On ne s'en sert qu'à la fin : sous « inscription », on laisse un
  // brouillon d'onboarding (niveau + réseau déjà choisis, + proposer un mot de
  // passe) que `bienvenue` reprendra une fois la session posée.
  const [mode, setMode] = useState<'connexion' | 'inscription'>('connexion');
  const [email, setEmail] = useState('');
  const [code, setCode] = useState('');
  const [motDePasse, setMotDePasse] = useState('');
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);
  // Un message doux, non alarmant (réinitialisation partie) : distinct de
  // l'erreur, il ne se lit pas comme une panne.
  const [info, setInfo] = useState<string | null>(null);
  // Les choix pré-compte du parcours « Je découvre ». Rangés dans le brouillon
  // à la création du compte, jamais avant : aucune écriture réseau pré-session.
  const [niveauxDec, setNiveauxDec] = useState<string[]>([]);
  const [reseauDec, setReseauDec] = useState<Reseau | null>(null);
  const champCode = useRef<TextInput>(null);

  const emailPropre = email.trim().toLowerCase();
  const emailPlausible = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(emailPropre);

  /**
   * Envoie le code à six chiffres. `recuperation` = l'utilisateur·rice a tapé
   * « Mot de passe oublié ? » : le code de connexion EST la récupération (on
   * n'envoie pas de lien de réinitialisation, on ne câble aucun retour par lien
   * profond, cf. l'entête). Une fois entré·e, on choisit un nouveau mot de passe
   * dans Réglages. La seule différence : un mot doux sur l'écran du code.
   */
  async function demanderCode(recuperation = false) {
    setErreur(null);
    setInfo(null);
    if (!emailPlausible) return setErreur(t.connexion.emailInvalide);
    setOccupe(true);
    const { error } = await supabase.auth.signInWithOtp({
      email: emailPropre,
      options: { shouldCreateUser: true },
    });
    setOccupe(false);
    // On passe à l'étape suivante même en cas d'erreur d'adresse inconnue, pour
    // ne pas révéler qui possède un compte. Seule une panne réelle est montrée.
    if (error) {
      // En développement, on montre la cause technique en plus du message doux :
      // un « l'envoi a échoué » sans détail fait perdre une heure à chaque fois.
      if (__DEV__) console.error('[connexion] signInWithOtp', error.status, error.code, error.message);
      const panne = !error.status || error.status >= 500;
      if (panne) {
        return setErreur(
          __DEV__ ? `${t.connexion.envoiRate}\n[dev] ${error.status ?? 'sans statut'} ${error.code ?? ''} ${error.message}` : t.connexion.envoiRate,
        );
      }
      if (error.status === 429) {
        return setErreur(
          __DEV__ ? `Trop de demandes.\n[dev] ${error.message}` : t.connexion.tropDeDemandes,
        );
      }
    }
    // La récupération réussie porte un mot doux sur l'écran du code : pas de
    // panique, le code te reconnecte, le nouveau mot de passe se choisit ensuite.
    if (recuperation) setInfo(LIB[langue].recupInfo);
    setEtape('code');
    setTimeout(() => champCode.current?.focus(), 250);
  }

  /**
   * Connexions Apple et Google, en natif.
   *
   * La navigation n'est pas déclenchée ici : dès que Supabase pose la session,
   * le garde de `_layout` bascule tout seul, comme pour le code et le mot de
   * passe. Une annulation (feuille fermée) n'affiche rien : ce n'est pas une
   * panne. Seule une vraie erreur montre l'alerte, et jamais le détail technique
   * du fournisseur, qui ne dit rien d'utile à une enseignante.
   */
  /**
   * Dépose le brouillon d'onboarding (niveaux + réseau pré-choisis dans « Je
   * découvre ») pour que `bienvenue` reprenne au bon endroit après la création du
   * compte. À faire sur TOUS les chemins de fin d'inscription : le code, mais AUSSI
   * Apple/Google. Sans ça, finir par un login social faisait re-choisir niveau et
   * réseau depuis zéro. `definirMotDePasse` : proposer d'en définir un ensuite
   * (oui pour le code, non pour un social login qui a déjà son fournisseur).
   */
  async function deposerBrouillonSiInscription(definirMotDePasse: boolean) {
    if (mode !== 'inscription') return;
    await ecrireBrouillonOnboarding({
      niveaux: niveauxDec,
      reseau: reseauDec,
      definirMotDePasse,
    }).catch(() => {});
  }

  async function surApple() {
    setErreur(null);
    setOccupe(true);
    // Le brouillon AVANT le login : dès que la session est posée, le garde bascule
    // sur `bienvenue`, qui doit déjà y trouver niveaux + réseau.
    await deposerBrouillonSiInscription(false);
    const { erreur: e } = await connexionApple();
    setOccupe(false);
    if (e) setErreur(t.connexion.erreurSociale);
  }

  async function surGoogle() {
    setErreur(null);
    setOccupe(true);
    await deposerBrouillonSiInscription(false);
    const { erreur: e } = await connexionGoogle();
    setOccupe(false);
    if (e) setErreur(t.connexion.erreurSociale);
  }

  async function validerCode() {
    setErreur(null);
    const chiffres = code.replace(/\D/g, '');
    if (!longueurPlausible(chiffres)) return setErreur(t.connexion.codeInvalide);
    setOccupe(true);
    const { error } = await supabase.auth.verifyOtp({
      email: emailPropre,
      token: chiffres,
      type: 'email',
    });
    setOccupe(false);
    if (error) return setErreur(t.connexion.codeRefuse);
    // Chemin « Je découvre » : le compte vient d'être créé (`shouldCreateUser`
    // était vrai). On dépose le brouillon (niveau, réseau) pour que `bienvenue`
    // reprenne au bon endroit, avec proposition de mot de passe. Écrit AVANT que
    // le garde ne bascule d'écran ; sans effet hors mode inscription.
    await deposerBrouillonSiInscription(true);
    // Pas de navigation ici : le garde de session dans _layout bascule tout seul
    // dès que la session existe. Deux endroits qui naviguent, c'est un conflit.
  }

  /**
   * Chemin par mot de passe, volontairement discret.
   *
   * Il existe pour deux raisons et pas une de plus. Un examinateur Apple doit
   * pouvoir entrer, et il ne reçoit pas nos emails : sans ce chemin, l'app est
   * rejetée au titre de la règle 2.1. Et une adresse d'école partagée reçoit
   * mal les codes.
   *
   * Le message d'erreur ne distingue jamais « adresse inconnue » de « mauvais
   * mot de passe » : la différence dirait qui a un compte à quelqu'un qui teste
   * des adresses au hasard.
   */
  async function connecterAvecMotDePasse() {
    setErreur(null);
    if (!emailPlausible) return setErreur(t.connexion.emailInvalide);
    if (motDePasse.length < MIN_MOT_DE_PASSE) return setErreur(t.connexion.motDePasseCourt);
    setOccupe(true);
    const { error } = await supabase.auth.signInWithPassword({
      email: emailPropre,
      password: motDePasse,
    });
    setOccupe(false);
    if (error) {
      if (__DEV__) console.error('[connexion] signInWithPassword', error.status, error.code);
      return setErreur(t.connexion.identifiantsRefuses);
    }
  }

  return (
    <SafeAreaView style={styles.racine}>
      <KeyboardAvoidingView
        style={styles.racine}
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
        <ScrollView contentContainerStyle={styles.contenu} keyboardShouldPersistTaps="handled">
          <View style={styles.marque}>
            {/* Sur l'accueil, une Cloudy qui salue, joyeuse : elle souhaite la
                bienvenue avant de demander quoi que ce soit. Partout ailleurs,
                Cloudy au chapeau — le logo (mortier multicolore) qui porte
                l'identité à elle seule, wordmark retiré. */}
            <Cloudy pose={etape === 'accueil' ? 'salut' : 'chapeau'} taille={124} anime />
          </View>

          {etape === 'accueil' ? (
            <View style={styles.carte}>
              <Text style={texte.titre}>{t.connexion.titre}</Text>
              <Text style={styles.intro}>{LIB[langue].accueilQuestion}</Text>
              {/* Deux chemins, un seul dégradé d'action (la charte) : « Je
                  découvre » porte l'action, « J'ai déjà un compte » reste
                  secondaire. Le premier lance l'onboarding sans compte ; le
                  compte se crée à la fin. */}
              <BoutonPrincipal
                libelle={LIB[langue].decouvrir}
                onPress={() => {
                  setErreur(null);
                  setInfo(null);
                  setMode('inscription');
                  setEtape('decouverteNiveau');
                }}
              />
              <Text style={styles.rassure}>{LIB[langue].decouvrirIndice}</Text>
              <BoutonSecondaire
                libelle={LIB[langue].dejaCompte}
                onPress={() => {
                  setErreur(null);
                  setInfo(null);
                  setMode('connexion');
                  setEtape('email');
                }}
              />
              <Text style={styles.rassure}>{LIB[langue].dejaCompteIndice}</Text>
            </View>
          ) : etape === 'decouverteNiveau' ? (
            <View style={styles.carte}>
              <Text style={texte.titre}>{t.bienvenue.niveauTitre}</Text>
              <Text style={styles.rassure}>{t.bienvenue.niveauAide}</Text>
              <View style={styles.rangee}>
                {NIVEAUX_FWB.map((n) => {
                  const actif = niveauxDec.includes(n);
                  return (
                    <Pressable
                      key={n}
                      accessibilityRole="button"
                      accessibilityState={{ selected: actif }}
                      accessibilityLabel={`${t.bienvenue.niveauTitre} ${n}`}
                      onPress={() =>
                        setNiveauxDec((l) =>
                          actif
                            ? l.filter((x) => x !== n)
                            : // On garde l'ordre officiel, pas l'ordre des taps.
                              NIVEAUX_FWB.filter((x) => x === n || l.includes(x)),
                        )
                      }
                      style={[styles.niveau, actif && styles.niveauActif]}>
                      <Text style={[styles.texteNiveau, actif && styles.texteNiveauActif]}>{n}</Text>
                    </Pressable>
                  );
                })}
              </View>
              <BoutonPrincipal
                libelle={t.bienvenue.niveauSuivant}
                onPress={() => setEtape('decouverteReseau')}
                inactif={niveauxDec.length === 0}
              />
              <BoutonDiscret libelle={LIB[langue].retour} onPress={() => setEtape('accueil')} />
            </View>
          ) : etape === 'decouverteReseau' ? (
            <View style={styles.carte}>
              <Text style={texte.titre}>{t.bienvenue.reseauTitre}</Text>
              <Text style={styles.rassure}>{t.bienvenue.reseauAide}</Text>
              <View style={styles.reseaux}>
                {RESEAUX.map((r) => {
                  const actif = reseauDec === r.id;
                  return (
                    <Pressable
                      key={r.id}
                      accessibilityRole="button"
                      accessibilityState={{ selected: actif }}
                      accessibilityLabel={`${r.titre}, ${r.aide}`}
                      onPress={() => setReseauDec(r.id)}
                      style={[styles.reseau, actif && styles.reseauActif]}>
                      <Text style={[styles.reseauTitre, actif && styles.reseauTitreActif]}>
                        {r.titre}
                      </Text>
                      <Text style={[styles.reseauAide, actif && styles.reseauAideActif]}>
                        {r.aide}
                      </Text>
                    </Pressable>
                  );
                })}
              </View>
              {/* On termine le pré-compte par l'email : envoyer le code CRÉE le
                  compte (`shouldCreateUser`), puis `bienvenue` reprend la suite. */}
              <BoutonPrincipal
                libelle={t.bienvenue.niveauSuivant}
                onPress={() => setEtape('email')}
                inactif={!reseauDec}
              />
              <BoutonDiscret
                libelle={LIB[langue].retour}
                onPress={() => setEtape('decouverteNiveau')}
              />
            </View>
          ) : etape === 'email' ? (
            <View style={styles.carte}>
              <Text style={texte.titre}>{t.connexion.titre}</Text>
              {/* Virage mobile-first : sur le web, on ne pousse pas la création
                  de compte (elle se fait sur l'app), le web est un complément. */}
              <Text style={styles.intro}>
                {Platform.OS === 'web' ? t.connexion.introWeb : t.connexion.intro}
              </Text>
              <Champ
                etiquette={t.connexion.email}
                value={email}
                onChangeText={setEmail}
                placeholder={t.connexion.emailIndice}
                autoCapitalize="none"
                autoCorrect={false}
                autoComplete="email"
                keyboardType="email-address"
                inputMode="email"
                returnKeyType="go"
                onSubmitEditing={() => demanderCode()}
                editable={!occupe}
              />
              {erreur ? <Alerte message={erreur} /> : null}
              <BoutonPrincipal
                libelle={t.connexion.envoyer}
                onPress={() => demanderCode()}
                occupe={occupe}
                inactif={!emailPlausible}
              />
              {/* La réassurance descend sous le bouton, en plus petit : c'est un
                  argument, pas le sujet. Le sujet, c'est d'entrer. */}
              <Text style={styles.rassure}>
                {Platform.OS === 'web' ? t.connexion.accrocheWeb : t.connexion.accroche}
              </Text>

              {appleDisponible || googleDisponible ? (
                <View style={styles.ou}>
                  <View style={styles.trait} />
                  <Text style={styles.ouTexte}>{t.connexion.ou}</Text>
                  <View style={styles.trait} />
                </View>
              ) : null}

              {appleDisponible ? (
                <AppleAuthentication.AppleAuthenticationButton
                  buttonType={AppleAuthentication.AppleAuthenticationButtonType.SIGN_IN}
                  buttonStyle={AppleAuthentication.AppleAuthenticationButtonStyle.BLACK}
                  cornerRadius={rayon.bloc}
                  style={styles.apple}
                  onPress={surApple}
                />
              ) : null}

              {googleDisponible ? (
                <BoutonSecondaire
                  libelle={t.connexion.avecGoogle}
                  onPress={surGoogle}
                  occupe={occupe}
                />
              ) : null}

              <BoutonDiscret
                libelle={t.connexion.autrement}
                onPress={() => {
                  setErreur(null);
                  setInfo(null);
                  setEtape('motDePasse');
                }}
              />
              {/* Retour au choix « découvre / déjà un compte », seulement sous le
                  nouvel accueil : on peut se raviser sans redémarrer l'app. */}
              {ACCUEIL_V2 ? (
                <BoutonDiscret
                  libelle={LIB[langue].retour}
                  onPress={() => {
                    setErreur(null);
                    setInfo(null);
                    setEtape('accueil');
                  }}
                />
              ) : null}
            </View>
          ) : etape === 'motDePasse' ? (
            <View style={styles.carte}>
              <Text style={texte.titre}>{t.connexion.titre}</Text>
              <Champ
                etiquette={t.connexion.email}
                value={email}
                onChangeText={setEmail}
                placeholder={t.connexion.emailIndice}
                autoCapitalize="none"
                autoCorrect={false}
                autoComplete="email"
                keyboardType="email-address"
                inputMode="email"
                editable={!occupe}
              />
              <Champ
                etiquette={t.connexion.motDePasse}
                value={motDePasse}
                onChangeText={setMotDePasse}
                secureTextEntry
                autoCapitalize="none"
                autoCorrect={false}
                autoComplete="current-password"
                textContentType="password"
                returnKeyType="go"
                onSubmitEditing={connecterAvecMotDePasse}
                editable={!occupe}
              />
              {erreur ? <Alerte message={erreur} /> : null}
              {info ? <Text style={styles.info}>{info}</Text> : null}
              <BoutonPrincipal
                libelle={t.connexion.connecter}
                onPress={connecterAvecMotDePasse}
                occupe={occupe}
                inactif={!emailPlausible || motDePasse.length < MIN_MOT_DE_PASSE}
              />
              {/* Mot de passe oublié : pas de lien de réinitialisation (aucun retour
                  par lien profond à gérer). On envoie un code de connexion — la
                  même porte de secours que partout — et on choisit un nouveau mot
                  de passe dans Réglages une fois entré·e. */}
              <BoutonDiscret
                libelle={LIB[langue].motDePasseOublie}
                onPress={() => demanderCode(true)}
              />
              <BoutonDiscret
                libelle={t.connexion.parCode}
                onPress={() => {
                  setMotDePasse('');
                  setErreur(null);
                  setInfo(null);
                  setEtape('email');
                }}
              />
            </View>
          ) : (
            <View style={styles.carte}>
              <Text style={texte.titre}>{t.connexion.codeTitre}</Text>
              <Text style={[texte.discret, styles.accroche]}>
                {t.connexion.codeAccroche(emailPropre)}
              </Text>
              {/* Mot doux de récupération, le cas échéant : le code te reconnecte,
                  le nouveau mot de passe se choisit ensuite dans Réglages. */}
              {info ? <Text style={styles.info}>{info}</Text> : null}
              <Champ
                ref={champCode}
                etiquette={t.connexion.code}
                value={code}
                onChangeText={setCode}
                placeholder={t.connexion.codeIndice}
                keyboardType="number-pad"
                inputMode="numeric"
                autoComplete="one-time-code"
                textContentType="oneTimeCode"
                maxLength={MAX_CODE}
                style={styles.champCode}
                returnKeyType="go"
                onSubmitEditing={validerCode}
                editable={!occupe}
              />
              {erreur ? <Alerte message={erreur} /> : null}
              <BoutonPrincipal
                libelle={t.connexion.valider}
                onPress={validerCode}
                occupe={occupe}
                inactif={!longueurPlausible(code.replace(/\D/g, ''))}
              />
              <BoutonDiscret libelle={t.connexion.renvoyer} onPress={() => demanderCode()} />
              <BoutonDiscret
                libelle={t.connexion.changerEmail}
                onPress={() => {
                  setCode('');
                  setErreur(null);
                  setEtape('email');
                }}
              />
            </View>
          )}

          {/* Invitation au tarif de groupe, discrète, sous la carte et
              seulement à l'entrée : elle s'adresse à une direction ou une
              équipe, pas à quelqu'un en train de taper son code. Elle ouvre une
              conversation WhatsApp avec le studio plutôt qu'un parcours d'achat. */}
          {etape === 'email' ? (
            <Text
              style={styles.tarifGroupe}
              onPress={() => void Linking.openURL(WHATSAPP_TARIF_GROUPE)}>
              {t.connexion.tarifGroupe}
            </Text>
          ) : null}
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

