/**
 * « Je serai absent·e » : déclarer une absence pour récupérer une journée déjà
 * planifiée et remettre ses activités dans le vivier « à replanifier ».
 *
 * 🔑 Aucun concurrent ne le fait, et c'est le geste que réclame une prof malade :
 * la journée était posée, rien n'a eu lieu, il ne faut pas tout ressaisir. On
 * choisit le JOUR, la PORTÉE (journée, matin, après-midi, créneaux précis), et
 * on récupère. Le report vide la date des activités : elles quittent la semaine
 * et deviennent replanifiables (voir `declarerAbsence`).
 *
 * Le motif reste optionnel MAIS il est bien stocké : `declarerAbsence` insère une
 * ligne dans `teacher_absences` (type, note, demi-journée, dates), que la vue
 * direction agrège ensuite par motif (jamais nominatif).
 */

const MIDI = '12:00';

const L = {
  titre: 'Je serai absent·e',
  sousTitre: 'Récupère ta journée, replanifie plus tard',
  choisirJour: 'Quel jour ?',
  portee: 'Quelle partie de la journée ?',
  portees: {
    jour: 'Journée entière',
    matin: 'Matin',
    apresmidi: 'Après-midi',
    creneaux: 'Créneaux précis',
  } as Record<PorteeAbsence, string>,
  creneauxAide: 'Coche les moments touchés par ton absence.',
  sansCreneau: "Pas d'horaire ce jour-là. Choisis « Journée entière » pour tout récupérer.",
  motifType: 'Motif (facultatif)',
  motifAide: "Sert au suivi agrégé de la direction — jamais nominatif, jamais un contrôle.",
  types: {
    maladie: 'Maladie',
    reunion: 'Réunion',
    conference: 'Conférence, formation',
    conges_scolaires: 'Congé',
    autre: 'Autre',
  } as Record<TypeAbsence, string>,
  motif: 'Note (facultatif)',
  motifPlaceholder: 'Un mot, si tu veux…',
  aujourdhui: "Aujourd'hui",
  rien: 'Rien de prévu à récupérer ce jour-là.',
  noter: 'Noter mon absence',
  note: 'Absence notée. Elle apparaît sur ta semaine.',
  dejaNotee: 'Déjà noté ce jour-là',
  retirer: 'Retirer',
  recuperer: (n: number) =>
    n === 0 ? 'Récupérer ces activités' : n === 1 ? 'Récupérer 1 activité' : `Récupérer ${n} activités`,
  semaine: 'Semaine',
  precedente: 'Semaine précédente',
  suivante: 'Semaine suivante',
  fait: (n: number) =>
    n === 0
      ? "Aucune activité n'était à récupérer."
      : n === 1
        ? '1 activité récupérée. Retrouve-la dans « À replanifier ».'
        : `${n} activités récupérées. Retrouve-les dans « À replanifier ».`,
  erreur: "L'absence n'a pas pu être déclarée. Réessaie.",
};

function isoDe(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

/** Le jour de la semaine (1 = lundi, 7 = dimanche) d'une date ISO, comme `Creneau.jour`. */
function dowDe(iso: string): number {
  const [a, m, j] = iso.split('-').map((n) => parseInt(n, 10));
  const jour = new Date(a, m - 1, j).getDay();
  return jour === 0 ? 7 : jour;
}

export default function Absence() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;

  const aujourdhui = isoDe(new Date());
  const [date, setDate] = useState(aujourdhui);
  const [portee, setPortee] = useState<PorteeAbsence>('jour');
  const [creneauxCoches, setCreneauxCoches] = useState<Set<string>>(new Set());
  const [type, setType] = useState<TypeAbsence | null>(null);
  const [motif, setMotif] = useState('');
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState(false);

  // Les créneaux de la semaine EFFECTIVE (fond + propres à la semaine) : une
  // activité peut pointer un créneau spécifique à cette semaine-là.
  const lundiISO = lundiDeISO(date);
  // Les absences déjà notées ce jour-là : on les montre, et on peut en retirer une.
  const deja = useRequete(() => absencesEntre(classeId!, date, date), [classeId, date], {
    actif: !!classeId,
  });
  const creneaux = useRequete(() => creneauxDe(classeId!, lundiISO), [classeId, lundiISO], {
    actif: !!classeId,
  });

  // Les activités posées ce jour-là, pour l'aperçu du nombre récupérable.
  const activites = useRequete(
    () => listeActivites({ classeId: classeId!, depuis: date, jusqua: date, limite: 200 }),
    [classeId, date],
    { actif: !!classeId },
  );

  const creneauxDuJour = useMemo(
    () =>
      (creneaux.donnees ?? [])
        .filter((cr) => cr.jour === dowDe(date))
        .sort((a, b) => a.debut.localeCompare(b.debut)),
    [creneaux.donnees, date],
  );

  const debutParCreneau = useMemo(() => {
    const table = new Map<string, string>();
    for (const cr of creneaux.donnees ?? []) table.set(cr.id, cr.debut);
    return table;
  }, [creneaux.donnees]);

  // L'aperçu du nombre d'activités qui seront récupérées, avec exactement la même
  // règle que `declarerAbsence` : matin/après-midi sur l'heure du créneau, les
  // séances sans créneau seulement en journée entière.
  const aRecuperer = useMemo(() => {
    const posees = (activites.donnees ?? []).filter((a) => a.statut !== 'completed' && a.date === date);
    if (portee === 'jour') return posees.length;
    if (portee === 'creneaux') {
      return posees.filter((a) => a.creneauId && creneauxCoches.has(a.creneauId)).length;
    }
    return posees.filter((a) => {
      if (!a.creneauId) return false;
      const debut = debutParCreneau.get(a.creneauId);
      if (!debut) return false;
      const avantMidi = debut < MIDI;
      return portee === 'matin' ? avantMidi : !avantMidi;
    }).length;
  }, [activites.donnees, date, portee, creneauxCoches, debutParCreneau]);

  function choisirJour(cle: string) {
    setDate(cle);
    // Un jour sans les créneaux cochés d'un autre jour : on repart propre.
    setCreneauxCoches(new Set());
  }

  function basculerCreneau(id: string) {
    setCreneauxCoches((prev) => {
      const suite = new Set(prev);
      if (suite.has(id)) suite.delete(id);
      else suite.add(id);
      return suite;
    });
  }

  async function recuperer() {
    if (!classeId || occupe) return;
    setErreur(false);
    setOccupe(true);
    try {
      const n = await declarerAbsence({
        classeId,
        date,
        portee,
        creneauIds: portee === 'creneaux' ? [...creneauxCoches] : undefined,
        type: type ?? undefined,
        note: motif,
      });
      // Confirme le nombre reporté, puis renvoie l'enseignante d'où elle vient.
      if (Platform.OS === 'web') {
        if (typeof window !== 'undefined') window.alert(n === 0 && type ? L.note : L.fait(n));
        router.back();
      } else {
        Alert.alert(L.titre, n === 0 && type ? L.note : L.fait(n), [
          { text: 'OK', onPress: () => router.back() },
        ]);
      }
    } catch {
      setErreur(true);
    } finally {
      setOccupe(false);
    }
  }

  // Rien à récupérer n'empêche plus de NOTER l'absence si un motif est choisi
  // (retour Sophie 24/09 : « je ne sais pas l'ajouter moi-même », le bouton
  // restait grisé les jours sans leçon posée).
  const desactive =
    (aRecuperer === 0 && !type) || (portee === 'creneaux' && creneauxCoches.size === 0) || occupe;

  async function retirer(id: string) {
    try {
      await retirerAbsence(id);
      deja.recharger();
    } catch {
      setErreur(true);
    }
  }

  return (
    <SousEcran titre={L.titre} sousTitre={L.sousTitre}>
      {erreur ? <Alerte message={L.erreur} /> : null}

      {/* Le jour : une semaine de cinq pastilles, navigable. */}
      <Carte compacte>
        <Text style={styles.label}>{L.choisirJour}</Text>
        {/* Un vrai calendrier, passé et futur (même sélecteur que la création). */}
        <SelecteurJoursMenu unique choisis={[date]} onBasculer={choisirJour} />
        {(deja.donnees ?? []).length ? (
          <View style={styles.deja}>
            <Text style={texte.discret}>{L.dejaNotee}</Text>
            {(deja.donnees ?? []).map((a) => (
              <View key={a.id} style={styles.dejaLigne}>
                <BadgeAbsence absences={[a]} />
                <Pressable accessibilityRole="button" onPress={() => void retirer(a.id)} hitSlop={8}>
                  <Text style={styles.retirer}>{L.retirer}</Text>
                </Pressable>
              </View>
            ))}
          </View>
        ) : null}
      </Carte>

      {/* La portée : journée, matin, après-midi, ou créneaux précis. */}
      <Carte compacte>
        <Text style={styles.label}>{L.portee}</Text>
        <View style={styles.rangee}>
          {(['jour', 'matin', 'apresmidi', 'creneaux'] as PorteeAbsence[]).map((p) => {
            const actif = p === portee;
            return (
              <Pressable
                key={p}
                accessibilityRole="button"
                accessibilityState={{ selected: actif }}
                accessibilityLabel={L.portees[p]}
                onPress={() => setPortee(p)}
                style={[styles.chip, actif && styles.chipActif]}>
                <Text style={[styles.chipTexte, actif && styles.chipTexteActif]}>{L.portees[p]}</Text>
              </Pressable>
            );
          })}
        </View>

        {portee === 'creneaux' ? (
          <View style={styles.creneaux}>
            {creneauxDuJour.length === 0 ? (
              <Text style={texte.discret}>{L.sansCreneau}</Text>
            ) : (
              <>
                <Text style={texte.discret}>{L.creneauxAide}</Text>
                {creneauxDuJour.map((cr) => (
                  <CreneauCoche
                    key={cr.id}
                    creneau={cr}
                    coche={creneauxCoches.has(cr.id)}
                    onBasculer={() => basculerCreneau(cr.id)}
                  />
                ))}
              </>
            )}
          </View>
        ) : null}
      </Carte>

      {/* Le motif, facultatif : il ne sert qu'au suivi AGRÉGÉ de la direction,
          jamais nominatif. On le laisse optionnel pour ne pas alourdir le geste. */}
      <Carte>
        <Pastilles
          etiquette={L.motifType}
          options={TYPES_ABSENCE.map((tp) => ({ id: tp, libelle: L.types[tp] }))}
          choisi={type}
          onChoisir={(v) => setType((v as TypeAbsence) ?? null)}
        />
        <Text style={texte.discret}>{L.motifAide}</Text>
      </Carte>

      {/* Note libre optionnelle. */}
      <Champ
        etiquette={L.motif}
        placeholder={L.motifPlaceholder}
        value={motif}
        onChangeText={setMotif}
      />

      {aRecuperer === 0 && !activites.chargement ? (
        <Text style={styles.rien}>{L.rien}</Text>
      ) : null}

      <BoutonPrincipal
        libelle={aRecuperer === 0 && type ? L.noter : L.recuperer(aRecuperer)}
        onPress={() => void recuperer()}
        occupe={occupe}
        inactif={desactive}
      />
    </SousEcran>
  );
}

/** Une ligne de créneau cochable, pour la portée « créneaux précis ». */
function CreneauCoche({
  creneau,
  coche,
  onBasculer,
}: {
  creneau: Creneau;
  coche: boolean;
  onBasculer: () => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <Pressable
      accessibilityRole="checkbox"
      accessibilityState={{ checked: coche }}
      accessibilityLabel={`${creneau.debut} ${creneau.libelle}`}
      onPress={onBasculer}
      style={[styles.ligneCreneau, coche && styles.ligneCreneauCoche]}>
      <View style={[styles.case, coche && styles.caseCoche]}>
        {coche ? <Feather name="check" size={14} color={c.surface} /> : null}
      </View>
      <Text style={styles.creneauTexte}>
        {creneau.debut} {creneau.libelle}
      </Text>
    </Pressable>
  );
}

