import { createContext, useContext, useState, type ReactNode } from 'react';

/**
 * Le cadre web de l'app plafonne la colonne à une largeur de téléphone (voir
 * `CadreWeb` dans `_layout`). C'est le bon défaut : l'app est dessinée pour une
 * colonne unique. Mais certains écrans, la GRILLE du semainier en tête, ont
 * besoin de la largeur de l'écran pour respirer (jours en colonnes).
 *
 * Ce petit contexte laisse un écran demander la « pleine largeur » web pendant
 * qu'il est à l'affiche, et le cadre s'élargit. À réserver au web : sur natif,
 * `CadreWeb` est un passe-plat, ce drapeau n'a aucun effet.
 */
const Contexte = createContext<{ pleine: boolean; setPleine: (v: boolean) => void }>({
  pleine: false,
  setPleine: () => {},
});

export function FournisseurLargeurWeb({ children }: { children: ReactNode }) {
  const [pleine, setPleine] = useState(false);
  return <Contexte.Provider value={{ pleine, setPleine }}>{children}</Contexte.Provider>;
}

export function useLargeurWeb() {
  return useContext(Contexte);
}
